CREATE OR REPLACE FUNCTION private.bar_comanda_finalizar_venda(p_comanda_id uuid, p_empresa uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_comanda    public.bar_comandas%rowtype;
  v_venda      uuid;
  v_numero     integer;
  v_item       record;
  v_item_venda bigint;
  v_saldo      record;
begin
  select * into v_comanda from public.bar_comandas
   where id = p_comanda_id and empresa_id = p_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;

  -- REVISÃO 3 (016) preservada: pega-ou-cria a ÚNICA venda desta comanda.
  if v_comanda.venda_id is null then
    insert into public.contadores_venda as c (empresa_id, ultimo_numero)
    values (p_empresa, 1)
    on conflict (empresa_id) do update set ultimo_numero = c.ultimo_numero + 1
    returning c.ultimo_numero into v_numero;

    insert into public.vendas (empresa_id, numero_venda, cliente_id, forma_pagamento, total, tipo, criado_por)
    values (p_empresa, v_numero, null, 'dividido', 0, 'bar', auth.uid())
    returning id into v_venda;

    update public.bar_comandas set venda_id = v_venda where id = v_comanda.id and empresa_id = p_empresa;
  else
    v_venda := v_comanda.venda_id;
  end if;

  -- Faturamento (snapshot em itens_venda) de todo item não estornado ainda sem item_venda_id —
  -- nunca duplica um item já faturado por um pagamento estilo antigo anterior, ou por uma
  -- finalização anterior desta mesma comanda (reabertura por estorno seguida de nova quitação).
  for v_item in
    select bpi.id, bpi.produto_id, bpi.quantidade, bpi.preco_unitario
      from public.bar_pedidos_itens bpi
     where bpi.comanda_id = p_comanda_id and bpi.empresa_id = p_empresa
       and bpi.estornado = false and bpi.item_venda_id is null
     order by bpi.id
  loop
    insert into public.itens_venda (empresa_id, venda_id, produto_id, quantidade, preco_unitario)
    values (p_empresa, v_venda, v_item.produto_id, v_item.quantidade, v_item.preco_unitario)
    returning id into v_item_venda;

    update public.bar_pedidos_itens set item_venda_id = v_item_venda
     where id = v_item.id and empresa_id = p_empresa;
  end loop;

  -- Religa à venda todo pagamento desta comanda que ainda estivesse sem venda_id (pagamentos
  -- estilo novo, inclusive os já estornados antes desta quitação — mantém o histórico completo).
  update public.bar_pagamentos set venda_id = v_venda
   where comanda_id = p_comanda_id and empresa_id = p_empresa and venda_id is null;

  -- vendas.total = TOTAL FINAL da comanda no instante da quitação — igual, por construção
  -- (saldo = 0), ao total efetivamente pago, mesmo com pagamentos estilo antigo e novo
  -- misturados na mesma comanda.
  select * into v_saldo from private.bar_comanda_saldo_calcular(p_comanda_id, p_empresa);
  update public.vendas set total = v_saldo.total_final where id = v_venda and empresa_id = p_empresa;

  perform private.bar_venda_recalcular_forma_pagamento(v_venda, p_empresa);

  return v_venda;
end;
$function$

CREATE OR REPLACE FUNCTION private.bar_comanda_saldo_calcular(p_comanda_id uuid, p_empresa uuid)
 RETURNS TABLE(total_itens_consumido numeric, itens_pendentes_subtotal numeric, itens_em_aberto integer, desconto numeric, acrescimo numeric, taxa_servico numeric, total_pago_estilo_antigo numeric, total_pago_estilo_novo numeric, total_pago numeric, total_final numeric, saldo numeric)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_comanda public.bar_comandas%rowtype;
begin
  select * into v_comanda from public.bar_comandas
   where id = p_comanda_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;

  -- Total consumido (informativo): TODOS os itens não estornados, pagos ou não, a preço cheio —
  -- é o número que a tela mostra como "TOTAL CONSUMIDO" bruto antes de qualquer ajuste.
  select coalesce(sum(bpi.quantidade * bpi.preco_unitario), 0)
    into total_itens_consumido
    from public.bar_pedidos_itens bpi
   where bpi.comanda_id = p_comanda_id and bpi.empresa_id = p_empresa
     and bpi.estornado = false;

  -- Itens ainda NÃO vinculados a nenhum pagamento estilo antigo — é sobre este subtotal que os
  -- ajustes de nível de comanda (desconto/acréscimo/taxa) e o pagamento monetário atuam.
  select coalesce(sum(bpi.quantidade * bpi.preco_unitario), 0), count(*)
    into itens_pendentes_subtotal, itens_em_aberto
    from public.bar_pedidos_itens bpi
   where bpi.comanda_id = p_comanda_id and bpi.empresa_id = p_empresa
     and bpi.estornado = false and bpi.pagamento_id is null;

  desconto := coalesce(v_comanda.desconto, 0);
  acrescimo := coalesce(v_comanda.acrescimo, 0);
  taxa_servico := coalesce(v_comanda.taxa_servico, 0);

  -- Pagamentos "estilo antigo" (016): têm ao menos um bar_pedidos_itens vinculado via
  -- pagamento_id. O valor deles já está definitivamente assentado (incluindo qualquer
  -- desconto/acréscimo/taxa daquele pagamento específico) e nunca é recalculado aqui — os itens
  -- que cobrem já saíram de itens_pendentes_subtotal acima.
  select coalesce(sum(bp.total), 0) into total_pago_estilo_antigo
    from public.bar_pagamentos bp
   where bp.comanda_id = p_comanda_id and bp.empresa_id = p_empresa
     and bp.estornado = false
     and exists (
       select 1 from public.bar_pedidos_itens bpi
        where bpi.pagamento_id = bp.id and bpi.empresa_id = p_empresa
     );

  -- Pagamentos "estilo novo" (018): lançamentos puramente monetários, nunca vinculados a item
  -- nenhum — é sobre eles que desconto/acréscimo/taxa (nível comanda) e o saldo em aberto atuam.
  select coalesce(sum(bp.total), 0) into total_pago_estilo_novo
    from public.bar_pagamentos bp
   where bp.comanda_id = p_comanda_id and bp.empresa_id = p_empresa
     and bp.estornado = false
     and not exists (
       select 1 from public.bar_pedidos_itens bpi
        where bpi.pagamento_id = bp.id and bpi.empresa_id = p_empresa
     );

  total_pago := round(total_pago_estilo_antigo + total_pago_estilo_novo, 2);

  -- TOTAL FINAL = o que já está definitivamente assentado (pagamentos estilo antigo, com seus
  -- próprios ajustes já embutidos) + o restante pendente, ajustado pelos ajustes de nível de
  -- comanda. Por construção, quando o saldo chega a zero, total_final == total_pago sempre —
  -- mesmo numa comanda que misturou os dois estilos.
  total_final := round(total_pago_estilo_antigo + itens_pendentes_subtotal - desconto + acrescimo + taxa_servico, 2);
  saldo := round(total_final - total_pago, 2);
  if saldo < 0 and saldo > -0.01 then
    saldo := 0;
  end if;

  total_itens_consumido := round(total_itens_consumido, 2);
  itens_pendentes_subtotal := round(itens_pendentes_subtotal, 2);
  total_pago_estilo_antigo := round(total_pago_estilo_antigo, 2);
  total_pago_estilo_novo := round(total_pago_estilo_novo, 2);
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION private.bar_garcons_ator(p_ator uuid, OUT o_empresa uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_papel  text;
  v_perm   text[];
  v_ativo  boolean;
  v_status text;
  v_bloq   boolean;
begin
  if p_ator is null then
    raise exception 'Sessão expirada. Faça login novamente.'
      using errcode = '28000';
  end if;

  select
    p.empresa_id,
    p.papel,
    p.permissoes,
    p.ativo,
    e.status_conta,
    e.bloqueado
  into
    o_empresa,
    v_papel,
    v_perm,
    v_ativo,
    v_status,
    v_bloq
  from public.perfis p
  join public.empresas e on e.id = p.empresa_id
  where p.id = p_ator;

  if o_empresa is null then
    raise exception 'Usuário sem empresa vinculada.'
      using errcode = '42501';
  end if;

  if v_status <> 'aprovado' or v_bloq then
    raise exception 'Seu acesso está bloqueado. Entre em contato com seu revendedor.'
      using errcode = '42501';
  end if;

  if not v_ativo then
    raise exception 'Seu usuário está desativado. Fale com o administrador da empresa.'
      using errcode = '42501';
  end if;

  -- Verifica diretamente a empresa do proprietário recebido em p_ator.
  -- Não usa empresa_tem_modulo(), pois esta depende de auth.uid().
  if not exists (
    select 1
    from public.empresa_modulos m
    where m.empresa_id = o_empresa
      and m.modulo = 'bar'
      and m.ativo = true
  ) then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.'
      using errcode = '42501';
  end if;

  if v_papel <> 'proprietario' then
    raise exception 'Você não tem permissão para gerenciar garçons.'
      using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.bar_historico_trava_fiscal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.vendas;
BEGIN
 SELECT * INTO v FROM public.vendas WHERE id=new.venda_id AND empresa_id=new.empresa_id FOR UPDATE;
 IF v.tipo='bar' AND v.cancelada_em IS NOT NULL THEN
   RAISE EXCEPTION 'Venda do Bar cancelada: documento fiscal deve seguir o procedimento fiscal próprio.';
 END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION private.bar_mesa_abrir_interna(p_mesa_id uuid, p_pessoas integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_mesa    public.bar_mesas%rowtype;
  v_comanda uuid;
  v_pessoas integer := coalesce(p_pessoas, 0);
begin
  if v_pessoas < 0 or v_pessoas > 200 then
    raise exception 'Quantidade de pessoas inválida.';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status = 'fechada' then
    raise exception 'Esta mesa está fora de serviço.';
  end if;
  if v_mesa.status <> 'livre' then
    raise exception 'Esta mesa já está ocupada.';
  end if;

  insert into public.bar_comandas (empresa_id, mesa_id, criado_por)
  values (v_empresa, p_mesa_id, auth.uid())
  returning id into v_comanda;

  update public.bar_mesas
     set status = 'ocupada', comanda_atual_id = v_comanda, pessoas_atual = v_pessoas, aberta_em = now()
   where id = p_mesa_id and empresa_id = v_empresa;

  if v_pessoas > 0 then
    insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, tipo, quantidade, criado_por)
    values (v_empresa, p_mesa_id, v_comanda, 'entrada', v_pessoas, auth.uid());
  end if;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, criado_por, detalhes)
  values (v_empresa, 'mesa_aberta', p_mesa_id, v_comanda, auth.uid(), jsonb_build_object('pessoas', v_pessoas));

  return v_comanda;
end;
$function$

CREATE OR REPLACE FUNCTION private.bar_produto_componente_valida()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_tipo         text;
  v_produto_pai  uuid;
begin
  select bp.tipo, bp.produto_id into v_tipo, v_produto_pai
    from public.bar_produtos bp
   where bp.id = new.bar_produto_id and bp.empresa_id = new.empresa_id;
  if v_tipo is null then
    raise exception 'Item de cardápio do bar não encontrado para este componente.';
  end if;
  if v_tipo <> 'composto' then
    raise exception 'Só é possível cadastrar componentes para um item de cardápio do tipo composto.';
  end if;
  if v_produto_pai = new.componente_produto_id then
    raise exception 'Um item composto não pode ter a si mesmo como componente.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.bar_produto_composto_excluir(p_id uuid, p_confirmar boolean DEFAULT false, p_nome_confirmado text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid;
  v_produto public.bar_produtos%rowtype;
  v_nome text;
  v_pedidos bigint;
  v_escolhas bigint;
  v_dependencias bigint;
begin
  if auth.uid() is null then
    raise exception 'Sessão expirada. Faça login novamente.' using errcode = '28000';
  end if;
  v_empresa := private.exigir_empresa_ativa();
  if not private.empresa_tem_modulo('bar') or not private.perm('bar_configurar') then
    raise exception 'Você não tem permissão para configurar produtos do Bar.' using errcode = '42501';
  end if;

  select bp.* into v_produto from public.bar_produtos bp
   where bp.id = p_id and bp.empresa_id = v_empresa and bp.tipo = 'composto'
   for update;
  if not found then
    raise exception 'Produto composto não encontrado nesta empresa.' using errcode = 'P0002';
  end if;
  select pr.nome into v_nome from public.produtos pr
   where pr.id = v_produto.produto_id and pr.empresa_id = v_empresa;
  if not found then raise exception 'Produto do catálogo não encontrado.'; end if;

  select count(*) into v_pedidos from public.bar_pedidos_itens i
   where i.empresa_id = v_empresa and i.bar_produto_id = p_id;
  select count(*) into v_escolhas from public.bar_pedidos_itens_escolhas e
   join public.bar_produto_grupos g on g.id = e.grupo_id and g.empresa_id = e.empresa_id
   where e.empresa_id = v_empresa and g.bar_produto_id = p_id;
  select
    (select count(*) from public.bar_produtos_componentes c
      where c.empresa_id = v_empresa and c.componente_produto_id = v_produto.produto_id and c.bar_produto_id <> p_id)
    + (select count(*) from public.bar_produto_grupo_opcoes o
       join public.bar_produto_grupos g on g.id = o.grupo_id and g.empresa_id = o.empresa_id
      where o.empresa_id = v_empresa and o.produto_id = v_produto.produto_id and g.bar_produto_id <> p_id)
    into v_dependencias;

  if p_confirmar is true then
    if p_nome_confirmado is distinct from v_nome then
      raise exception 'Confirme a exclusão com o nome atual do produto. Abra a confirmação novamente.';
    end if;
    update public.bar_produtos set ativo_cardapio = false
     where id = p_id and empresa_id = v_empresa and ativo_cardapio = true;
    v_produto.ativo_cardapio := false;
  end if;
  return jsonb_build_object(
    'id',p_id,'empresa_id',v_empresa,'produto_id',v_produto.produto_id,'nome',v_nome,
    'ativo_cardapio',v_produto.ativo_cardapio,'estrategia','desativacao',
    'pedidos_itens',v_pedidos,'escolhas_historicas',v_escolhas,'dependencias',v_dependencias
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.caixa_exigir_aberto(p_tipo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_tipo    text := upper(btrim(coalesce(p_tipo, '')));
  v_caixa   uuid;
begin
  -- Receber pagamentos não concede acesso ao resumo ou ao fechamento do caixa.
  -- As RPCs de pagamento mantêm suas próprias permissões e validações existentes.
  if v_tipo = 'BAR' and not private.caixa_pode_operar(v_tipo) then
    raise exception 'Você não tem permissão para registrar pagamentos no bar.' using errcode = '42501';
  end if;
  select c.id into v_caixa
    from public.caixas c
   where c.empresa_id = v_empresa and c.tipo_caixa = v_tipo and c.status = 'aberto'
     for share;
  if v_caixa is null then
    if v_tipo = 'BAR' then
      raise exception 'O Caixa do Bar está fechado. Abra o caixa para receber este pagamento.' using errcode = 'CX001';
    end if;
    raise exception 'Não existe Caixa PDV aberto. Abra o caixa para continuar.' using errcode = 'CX001';
  end if;
  return v_caixa;
end;
$function$

CREATE OR REPLACE FUNCTION private.caixa_tipo_validar(p_tipo text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v text := upper(btrim(coalesce(p_tipo, '')));
begin
  if v not in ('PDV', 'BAR') then
    raise exception 'Tipo de caixa inválido (use PDV ou BAR).';
  end if;
  return v;
end;
$function$

CREATE OR REPLACE FUNCTION private.caixa_vinculo_validar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caixa public.caixas%rowtype;
  v_tipo text := tg_argv[0];
begin
  IF tg_table_name='vendas' AND to_jsonb(new)->>'tipo'='bar' THEN v_tipo:='BAR'; END IF;
  if tg_op = 'UPDATE' then
    if old.caixa_id is not null and new.caixa_id is distinct from old.caixa_id then
      raise exception 'O vínculo do movimento com o caixa não pode ser alterado.';
    end if;
    if new.caixa_id is not distinct from old.caixa_id then
      return new;
    end if;
  end if;

  -- o pagamento de uma venda do PDV acompanha SEMPRE o caixa da venda (inclusive "sem caixa" nas antigas)
  if tg_op = 'INSERT' and tg_argv[1] = 'venda' then
    if not exists (select 1 from public.vendas v
                    where v.empresa_id = new.empresa_id and v.id = new.venda_id
                      and v.caixa_id is not distinct from new.caixa_id) then
      raise exception 'O pagamento precisa estar no mesmo caixa da venda.';
    end if;
  end if;

  if new.caixa_id is null then
    return new;
  end if;

  select * into v_caixa
    from public.caixas c
   where c.id = new.caixa_id and c.empresa_id = new.empresa_id
     for share;
  if not found then
    raise exception 'Caixa não encontrado para esta empresa.';
  end if;
  if v_caixa.tipo_caixa <> v_tipo then
    raise exception 'Caixa de tipo incompatível: este movimento só pode ser ligado a um Caixa %.', v_tipo;
  end if;
  if v_caixa.status <> 'aberto' then
    raise exception 'O caixa informado já está fechado.' using errcode = 'CX001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.cpf_valido(p_cpf text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_cpf   text := regexp_replace(coalesce(p_cpf, ''), '[^0-9]', '', 'g');
  v_soma  integer;
  v_resto integer;
  v_dv1   integer;
  v_dv2   integer;
  i       integer;
begin
  if length(v_cpf) <> 11 then
    return false;
  end if;

  -- Sequências com os 11 dígitos iguais (000.000.000-00, 111.111.111-11, ...) passam pela conta
  -- de dígito verificador matematicamente, mas nunca são CPFs reais — rejeitadas explicitamente.
  if v_cpf ~ '^(\d)\1{10}$' then
    return false;
  end if;

  v_soma := 0;
  for i in 1..9 loop
    v_soma := v_soma + substr(v_cpf, i, 1)::integer * (11 - i);
  end loop;
  v_resto := v_soma % 11;
  v_dv1 := case when v_resto < 2 then 0 else 11 - v_resto end;
  if v_dv1 <> substr(v_cpf, 10, 1)::integer then
    return false;
  end if;

  v_soma := 0;
  for i in 1..10 loop
    v_soma := v_soma + substr(v_cpf, i, 1)::integer * (12 - i);
  end loop;
  v_resto := v_soma % 11;
  v_dv2 := case when v_resto < 2 then 0 else 11 - v_resto end;
  if v_dv2 <> substr(v_cpf, 11, 1)::integer then
    return false;
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.exigir_empresa_ativa()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid    uuid := (select auth.uid());
  v_emp    uuid;
  v_status text;
  v_bloq   boolean;
  v_ativo  boolean;
begin
  if v_uid is null then
    raise exception 'Sessão expirada. Faça login novamente.' using errcode = '28000';
  end if;
  select e.id, e.status_conta, e.bloqueado, p.ativo into v_emp, v_status, v_bloq, v_ativo
    from public.perfis p join public.empresas e on e.id = p.empresa_id
   where p.id = v_uid;
  if v_emp is null then
    raise exception 'Usuário sem empresa vinculada.' using errcode = '42501';
  end if;
  if v_status = 'pendente' then
    raise exception 'Sua conta ainda está em análise.' using errcode = '42501';
  end if;
  if v_status <> 'aprovado' or v_bloq then
    raise exception 'Seu acesso está bloqueado. Entre em contato com seu revendedor.' using errcode = '42501';
  end if;
  if not v_ativo then
    raise exception 'Seu usuário está desativado. Fale com o administrador da empresa.' using errcode = '42501';
  end if;
  return v_emp;
end;
$function$

CREATE OR REPLACE FUNCTION private.florest_autorizacao_consumir(p_token uuid, p_ator uuid, p_operacao text, p_alvo uuid, p_parametros jsonb)
 RETURNS private.florest_autorizacoes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.florest_autorizacoes;
begin
 select * into t from private.florest_autorizacoes where token=p_token for update;
 if not found or t.solicitante_id<>p_ator or t.operacao<>p_operacao or t.alvo_id<>p_alvo or t.parametros<>coalesce(p_parametros,'{}') then raise exception 'Autorização não corresponde à operação.' using errcode='42501'; end if;
 if t.consumida_em is not null then return t; end if;
 if t.expira_em<clock_timestamp() or not exists(select 1 from public.perfis p join public.empresas em on em.id=p.empresa_id where p.id=t.autorizador_id and p.empresa_id=t.empresa_id and p.ativo and p.papel='proprietario' and em.status_conta='aprovado' and not em.bloqueado)
 or not exists(select 1 from public.perfis where id=p_ator and empresa_id=t.empresa_id and ativo) then raise exception 'Autorização expirada ou revogada.' using errcode='42501'; end if;
 update private.florest_autorizacoes set consumida_em=now(),transacao=txid_current() where token=p_token returning * into t;
 return t;
end $function$

CREATE OR REPLACE FUNCTION private.florest_cnpj_valido(p_cnpj text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  declare
    d  text := regexp_replace(coalesce(p_cnpj, ''), '\D', '', 'g');
    w1 int[] := array[5,4,3,2,9,8,7,6,5,4,3,2];
    w2 int[] := array[6,5,4,3,2,9,8,7,6,5,4,3,2];
    s  int;
    r  int;
    i  int;
  begin
    if length(d) <> 14 or d ~ '^(\d)\1{13}$' then return false; end if;
    s := 0;
    for i in 1..12 loop s := s + substr(d, i, 1)::int * w1[i]; end loop;
    r := s % 11; r := case when r < 2 then 0 else 11 - r end;
    if r <> substr(d, 13, 1)::int then return false; end if;
    s := 0;
    for i in 1..13 loop s := s + substr(d, i, 1)::int * w2[i]; end loop;
    r := s % 11; r := case when r < 2 then 0 else 11 - r end;
    return r = substr(d, 14, 1)::int;
  end;
  $function$

CREATE OR REPLACE FUNCTION private.florest_normalizar_cadastro(p_dados jsonb, p_modo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
  declare
    v_estrito boolean := (p_modo = 'estrito');
    v_tol     boolean := (p_modo = 'tolerante');
    v_ufs     text[]  := array['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
    v_out     jsonb   := '{}'::jsonb;
    rec       record;
    c         text;
    r         text;
    d         text;
    ok        boolean;
  begin
    if p_modo is null or p_modo not in ('estrito','parcial','tolerante') then
      raise exception 'CE000: modo inválido.' using errcode = 'CE000';
    end if;
    if p_dados is null or jsonb_typeof(p_dados) <> 'object' then
      if v_tol then return v_out; end if;
      raise exception 'CE001: dados inválidos.' using errcode = 'CE001';
    end if;

    -- campos de texto livre
    for rec in
      select * from (values
        ('nome',         2, 200, true),
        ('razao_social', 2, 200, true),
        ('responsavel',  2, 200, true),
        ('logradouro',   2, 200, true),
        ('numero',       1,  20, true),
        ('complemento',  1, 100, false),
        ('bairro',       2, 100, true),
        ('cidade',       2, 100, true)
      ) as t(k, mn, mx, obr)
    loop
      c := rec.k; r := null; ok := true;
      if p_dados ? c and jsonb_typeof(p_dados -> c) <> 'null' then
        if jsonb_typeof(p_dados -> c) <> 'string' then
          ok := false;
        else
          r := regexp_replace(btrim(p_dados ->> c), '\s+', ' ', 'g');
          if r = '' then
            r := null;
          elsif r ~ '[[:cntrl:]]' or char_length(r) < rec.mn or char_length(r) > rec.mx then
            ok := false;
          end if;
        end if;
      end if;
      if not ok then
        if v_tol then r := null; else raise exception 'CE001: dado inválido ou ausente: %', c using errcode = 'CE001'; end if;
      end if;
      if r is null and v_estrito and rec.obr then
        raise exception 'CE001: dado inválido ou ausente: %', c using errcode = 'CE001';
      end if;
      if r is not null then v_out := v_out || jsonb_build_object(c, r); end if;
    end loop;

    -- campos com formato: cnpj, telefone, cep, uf
    foreach c in array array['cnpj','telefone','cep','uf'] loop
      r := null; ok := true;
      if p_dados ? c and jsonb_typeof(p_dados -> c) <> 'null' then
        if jsonb_typeof(p_dados -> c) <> 'string' then
          ok := false;
        else
          r := btrim(p_dados ->> c);
          if r = '' then
            r := null;
          elsif c = 'uf' then
            r := upper(r);
            ok := (r = any (v_ufs));
          else
            d := regexp_replace(r, '\D', '', 'g');
            if c = 'telefone' and length(d) in (12, 13) and left(d, 2) = '55' then d := substr(d, 3); end if;
            r := d;
            if c = 'cnpj' then
              ok := private.florest_cnpj_valido(d);
            elsif c = 'telefone' then
              ok := (d ~ '^[1-9][1-9]\d{8,9}$');
            else
              ok := (d ~ '^\d{8}$' and d <> '00000000');
            end if;
          end if;
        end if;
      end if;
      if not ok then
        if v_tol then r := null; else raise exception 'CE001: dado inválido ou ausente: %', c using errcode = 'CE001'; end if;
      end if;
      if r is null and v_estrito then
        raise exception 'CE001: dado inválido ou ausente: %', c using errcode = 'CE001';
      end if;
      if r is not null then v_out := v_out || jsonb_build_object(c, r); end if;
    end loop;

    return v_out;
  end;
  $function$

CREATE OR REPLACE FUNCTION private.florest_perfil_guardar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid; ator uuid:=auth.uid();
begin
 e:=case when tg_op='INSERT' then new.empresa_id else old.empresa_id end;
 -- Serialização de promoções/desativações concorrentes na mesma empresa.
 perform pg_advisory_xact_lock(hashtextextended(e::text,9481));
 -- A escrita no mutex também detecta concorrência em REPEATABLE READ/SERIALIZABLE.
 insert into private.florest_proprietarios_mutex as m(empresa_id) values(e) on conflict(empresa_id) do update set revisao=m.revisao+1;
 if tg_op='UPDATE' and (new.empresa_id is distinct from old.empresa_id or new.id is distinct from old.id) then
  raise exception 'Identidade do perfil não pode ser transferida.' using errcode='42501';
 end if;
 if tg_op='DELETE' or (tg_op='UPDATE' and old.papel='proprietario' and old.ativo and (new.papel<>'proprietario' or not new.ativo)) then
  if old.papel='proprietario' and old.ativo and not exists(select 1 from public.perfis where empresa_id=e and papel='proprietario' and ativo and id<>old.id) then
   raise exception 'A empresa precisa manter pelo menos um proprietário ativo.' using errcode='42501';
  end if;
 end if;
 if tg_op<>'DELETE' and new.papel='proprietario' then
  new.tipo_acesso:='erp';
 end if;
 if tg_op='UPDATE' and new.papel is distinct from old.papel and ator is not null and not exists(
  select 1 from public.perfis where id=ator and empresa_id=e and papel='proprietario' and ativo
 ) then raise exception 'Somente proprietário pode alterar o perfil Proprietário.' using errcode='42501'; end if;
 if tg_op='DELETE' then return old; end if; return new;
end $function$

CREATE OR REPLACE FUNCTION private.pdv_comandas_garantir_posicoes(p_empresa_id uuid, p_quantidade integer DEFAULT 10)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_novas integer;
begin
  if p_empresa_id is null or p_quantidade is null or p_quantidade < 1 or p_quantidade > 999 then
    raise exception 'Parâmetros inválidos para criar posições de comanda (empresa obrigatória; quantidade entre 1 e 999).';
  end if;
  insert into public.pdv_comandas (empresa_id, numero)
  select p_empresa_id, g.n
    from generate_series(1, p_quantidade) as g(n)
  on conflict (empresa_id, numero) do nothing;
  get diagnostics v_novas = row_count;
  return v_novas;
end;
$function$

CREATE OR REPLACE FUNCTION private.pdv_prazo_proteger_recebimento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa uuid := private.exigir_empresa_ativa(); v_tipo text; v_rec public.contas_receber_recebimentos%rowtype;
  v_caixa public.caixas%rowtype; v_soma numeric;
BEGIN
  IF NEW.empresa_id IS DISTINCT FROM v_empresa OR NOT private.perm('financeiro') THEN
    RAISE EXCEPTION 'Recebimento não autorizado nesta empresa.' USING ERRCODE='42501';
  END IF;
  v_tipo := private.contas_receber_tipo_caixa(NEW.titulo_id,v_empresa);
  SELECT * INTO v_rec FROM public.contas_receber_recebimentos r WHERE r.id=NEW.recebimento_id AND r.empresa_id=v_empresa;
  IF v_rec.id IS NULL OR v_rec.caixa_id IS NULL OR v_tipo IS NULL THEN RAISE EXCEPTION 'Recebimento sem caixa/origem identificável.'; END IF;
  SELECT * INTO v_caixa FROM public.caixas c WHERE c.id=v_rec.caixa_id AND c.empresa_id=v_empresa FOR SHARE;
  IF NOT FOUND OR v_caixa.status<>'aberto' OR v_caixa.tipo_caixa IS DISTINCT FROM v_tipo THEN
    RAISE EXCEPTION 'Abra o Caixa % correto para receber o título.',v_tipo USING ERRCODE='CX001';
  END IF;
  SELECT coalesce(sum(f.valor),0) INTO v_soma FROM public.contas_receber_recebimentos_formas f
    WHERE f.recebimento_id=v_rec.id AND f.empresa_id=v_empresa;
  IF v_soma<>v_rec.valor_total THEN RAISE EXCEPTION 'Formas de pagamento não conferem com o recebimento.'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.produto_exigir_ativo(p_empresa uuid, p_produto uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_nome text;
begin
  select p.nome into v_nome
    from public.produtos p
   where p.id = p_produto and p.empresa_id = p_empresa and p.ativo = false;
  if found then
    raise exception 'O produto "%" está inativo e não pode ser usado em novas vendas ou lançamentos. Reative-o em Produtos para voltar a utilizá-lo.', v_nome;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.produtos_exigir_ativos(p_empresa uuid, p_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_nomes text;
begin
  if p_ids is null or cardinality(p_ids) = 0 then return; end if;
  select string_agg('"' || x.nome || '"', ', ' order by x.nome) into v_nomes
    from (select distinct p.nome
            from public.produtos p
           where p.empresa_id = p_empresa and p.id = any (p_ids) and p.ativo = false) x;
  if v_nomes is not null then
    raise exception 'Produto(s) inativo(s): %. Produtos inativos não podem ser usados em novas vendas ou lançamentos. Reative-os em Produtos para voltar a utilizá-los.', v_nomes;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.taxas_consolidar(e uuid, d date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total numeric; anterior text:=coalesce(current_setting('private.taxas_interno',true),'');
begin
 perform pg_advisory_xact_lock(hashtextextended('taxas-dia:'||e::text||':'||d::text,0));
 select coalesce(sum(valor_taxa),0) into total from private.taxas_pagamentos where empresa_id=e and data=d and ativo;
 perform set_config('private.taxas_interno','1',true);
 if total=0 then delete from public.despesas where empresa_id=e and data=d and taxas_automaticas;
 else insert into public.despesas(empresa_id,descricao,categoria,valor,data,vencimento,status,pago_em,taxas_automaticas,observacoes)
 values(e,'Despesa administrativa de cartões','Despesa administrativa de cartões',total,d,d,'pago',d,true,'Taxas de cartões e Pix. Calculadas automaticamente pelos pagamentos.')
 on conflict(empresa_id,data) where taxas_automaticas do update set valor=excluded.valor;
 end if;
 perform set_config('private.taxas_interno',anterior,true);
end $function$

CREATE OR REPLACE FUNCTION private.taxas_registrar(p_origem text, p_id uuid, p_meta jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid; bruto numeric; forma text; vid uuid; bid uuid; dt date; cfg private.taxas_versoes%rowtype; b text; taxa numeric:=0; tem boolean; anulada boolean:=false;
begin
 if p_meta->'taxas'->>'config_id' is null then return; end if;
 if p_origem='pdv' then
 select p.empresa_id,p.valor,p.forma_pagamento,p.venda_id,(p.criado_em at time zone 'America/Sao_Paulo')::date,v.cancelada_em is not null into e,bruto,forma,vid,dt,anulada from public.vendas_pagamentos p join public.vendas v on v.id=p.venda_id and v.empresa_id=p.empresa_id where p.id=p_id;
 else
 select p.empresa_id,p.valor,p.forma_pagamento,p.pagamento_id,(p.criado_em at time zone 'America/Sao_Paulo')::date,bp.estornado into e,bruto,forma,bid,dt,anulada from public.bar_pagamentos_formas p join public.bar_pagamentos bp on bp.id=p.pagamento_id and bp.empresa_id=p.empresa_id where p.id=p_id;
 end if;
 if e is null or e is distinct from private.empresa_id_ativa() then raise exception 'Pagamento de outra empresa' using errcode='42501'; end if;
 select * into cfg from private.taxas_versoes where id=(p_meta->'taxas'->>'config_id')::uuid and empresa_id=e;
 if not found then raise exception 'Configuração de outra empresa ou inexistente' using errcode='42501'; end if;
 b:=nullif(p_meta->'taxas'->>'bandeira','');
 if cfg.ativo and forma in ('Pix','Cartão de Débito','Cartão de Crédito') then
 select exists(select 1 from jsonb_array_elements(cfg.regras) r where r->>'forma'=forma) into tem;
 if tem then
  select (r->>'percentual')::numeric into taxa from jsonb_array_elements(cfg.regras) r where r->>'forma'=forma and coalesce(r->>'bandeira','')=coalesce(b,'');
  if taxa is null then raise exception 'Selecione uma bandeira com taxa cadastrada'; end if;
 end if;
 end if;
 taxa:=coalesce(taxa,0);
 insert into private.taxas_pagamentos(origem,pagamento_id,empresa_id,config_id,venda_id,bar_pagamento_id,data,forma,bandeira,valor_bruto,percentual,valor_taxa,ativo)
 values(p_origem,p_id,e,cfg.id,vid,bid,dt,forma,b,bruto,taxa,round(bruto*taxa/100,2),not anulada) on conflict do nothing;
 perform private.taxas_consolidar(e,dt);
end $function$

CREATE OR REPLACE FUNCTION private.taxas_reverter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;
begin
 if tg_table_name='vendas' then
  if new.cancelada_em is not distinct from old.cancelada_em then return new; end if;
  update private.taxas_pagamentos set ativo=new.cancelada_em is null where empresa_id=new.empresa_id and origem='pdv' and venda_id=new.id;
  for r in select distinct empresa_id,data from private.taxas_pagamentos where empresa_id=new.empresa_id and origem='pdv' and venda_id=new.id loop perform private.taxas_consolidar(r.empresa_id,r.data); end loop;
 elsif tg_table_name='bar_pagamentos' then
  if new.estornado is not distinct from old.estornado then return new; end if;
  update private.taxas_pagamentos set ativo=not new.estornado where empresa_id=new.empresa_id and origem='bar' and bar_pagamento_id=new.id;
  for r in select distinct empresa_id,data from private.taxas_pagamentos where empresa_id=new.empresa_id and origem='bar' and bar_pagamento_id=new.id loop perform private.taxas_consolidar(r.empresa_id,r.data); end loop;
 end if; return new;
end $function$

CREATE OR REPLACE FUNCTION private.usuarios_alvo(p_ator uuid, p_alvo uuid, OUT o_empresa uuid, OUT o_papel_ator text, OUT o_perm_ator text[])
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_t record;
begin
  select a.o_empresa, a.o_papel, a.o_permissoes into o_empresa, o_papel_ator, o_perm_ator
    from private.usuarios_ator(p_ator) a;
  if p_alvo is null or p_alvo = p_ator then
    raise exception 'Você não pode alterar o seu próprio acesso.' using errcode = '42501';
  end if;
  select p.papel, p.permissoes into v_t
    from public.perfis p where p.id = p_alvo and p.empresa_id = o_empresa;
  if not found then
    raise exception 'Usuário não encontrado.' using errcode = '42501';
  end if;
  if v_t.papel = 'proprietario' then
    raise exception 'O proprietário da empresa não pode ser alterado.' using errcode = '42501';
  end if;
  if o_papel_ator <> 'proprietario' and 'usuarios' = any (v_t.permissoes) then
    raise exception 'Somente o proprietário pode alterar quem administra usuários.' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.usuarios_ator(p_ator uuid, OUT o_empresa uuid, OUT o_papel text, OUT o_permissoes text[])
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_bloq   boolean;
  v_ativo  boolean;
begin
  if p_ator is null then
    raise exception 'Sessão expirada. Faça login novamente.' using errcode = '28000';
  end if;
  select p.empresa_id, p.papel, p.permissoes, p.ativo, e.status_conta, e.bloqueado
    into o_empresa, o_papel, o_permissoes, v_ativo, v_status, v_bloq
    from public.perfis p join public.empresas e on e.id = p.empresa_id
   where p.id = p_ator;
  if o_empresa is null then
    raise exception 'Usuário sem empresa vinculada.' using errcode = '42501';
  end if;
  if v_status <> 'aprovado' or v_bloq then
    raise exception 'Seu acesso está bloqueado. Entre em contato com seu revendedor.' using errcode = '42501';
  end if;
  if not v_ativo then
    raise exception 'Seu usuário está desativado. Fale com o administrador da empresa.' using errcode = '42501';
  end if;
  if o_papel <> 'proprietario' and not ('usuarios' = any (o_permissoes)) then
    raise exception 'Você não tem permissão para administrar usuários e acessos.' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.usuarios_normalizar_permissoes(p_perm text[], p_ator_papel text, p_ator_perm text[])
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v text[];
begin
  if p_perm is null then
    raise exception 'Informe as permissões do usuário.';
  end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v from unnest(p_perm) x;
  if exists (select 1 from unnest(v) x where x is null or x <> all (private.usuarios_modulos())) then
    raise exception 'Permissão inválida.';
  end if;
  if p_ator_papel <> 'proprietario' then
    if 'usuarios' = any (v) then
      raise exception 'Somente o proprietário pode liberar o módulo Usuários e Acessos.' using errcode = '42501';
    end if;
    if not (v <@ p_ator_perm) then
      raise exception 'Você só pode liberar módulos aos quais você mesmo tem acesso.' using errcode = '42501';
    end if;
  end if;
  return v;
end;
$function$

CREATE OR REPLACE FUNCTION private.venda_mista_validar_pagamentos(p_pagamentos jsonb)
 RETURNS TABLE(ordem integer, forma_pagamento text, valor numeric)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  c_formas constant text[] := array['Dinheiro', 'Pix', 'Cartão de Débito', 'Cartão de Crédito', 'Outros'];
  v_item   jsonb;
  v_ord    integer;
  v_forma  text;
  v_valor  numeric;
begin
  if p_pagamentos is null or jsonb_typeof(p_pagamentos) <> 'array' then
    raise exception 'Informe os pagamentos da venda (lista de formas de pagamento).';
  end if;
  if jsonb_array_length(p_pagamentos) < 1 then
    raise exception 'Informe ao menos uma forma de pagamento.';
  end if;
  if jsonb_array_length(p_pagamentos) > 10 then
    raise exception 'Formas de pagamento demais em uma única venda (máximo 10).';
  end if;

  for v_item, v_ord in
    select e.item, e.ord::integer
      from jsonb_array_elements(p_pagamentos) with ordinality as e(item, ord)
     order by e.ord
  loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Pagamento % inválido.', v_ord;
    end if;

    if jsonb_typeof(v_item -> 'forma_pagamento') is distinct from 'string' then
      raise exception 'Pagamento %: forma de pagamento não informada.', v_ord;
    end if;
    v_forma := normalize(btrim(v_item ->> 'forma_pagamento'), NFC);
    if not (v_forma = any (c_formas)) then
      raise exception 'Pagamento %: forma de pagamento inválida (%). Use: Dinheiro, Pix, Cartão de Débito, Cartão de Crédito ou Outros.', v_ord, v_forma;
    end if;

    if jsonb_typeof(v_item -> 'valor') is distinct from 'number' then
      raise exception 'Pagamento %: o valor deve ser um número.', v_ord;
    end if;
    v_valor := (v_item ->> 'valor')::numeric;
    if v_valor <= 0 then
      raise exception 'Pagamento %: o valor deve ser maior que zero.', v_ord;
    end if;
    if v_valor <> round(v_valor, 2) then
      raise exception 'Pagamento %: o valor deve ter no máximo duas casas decimais.', v_ord;
    end if;
    if v_valor > 99999999999.99 then
      raise exception 'Pagamento %: valor acima do limite permitido.', v_ord;
    end if;

    ordem := v_ord;
    forma_pagamento := v_forma;
    valor := v_valor;
    return next;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_comanda_finalizar_nota_prazo(p_comanda_id uuid, p_cliente_id uuid, p_vencimento date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa uuid := private.exigir_empresa_ativa();
  v_comanda public.bar_comandas%rowtype;
  v_mesa public.bar_mesas%rowtype;
  v_saldo record;
  v_caixa uuid;
  v_venda uuid;
  v_titulo uuid;
  v_numero integer;
  v_valor numeric(14,2);
BEGIN
  IF NOT private.empresa_tem_modulo('bar') OR NOT private.perm('bar_caixa') THEN
    RAISE EXCEPTION 'Sem permissão para Nota a Prazo no Módulo Bar.' USING errcode='42501';
  END IF;
  -- Sempre mesa -> comanda, inclusive ao recuperar uma resposta perdida.
  PERFORM 1 FROM public.bar_mesas m JOIN public.bar_comandas c ON c.mesa_id=m.id AND c.empresa_id=m.empresa_id
   WHERE c.id=p_comanda_id AND c.empresa_id=v_empresa FOR UPDATE OF m;
  SELECT * INTO v_comanda FROM public.bar_comandas WHERE id=p_comanda_id AND empresa_id=v_empresa FOR UPDATE;
  IF FOUND AND v_comanda.status='fechada' THEN
    SELECT cr.id,cr.venda_id,v.numero_venda,cr.valor_original INTO v_titulo,v_venda,v_numero,v_valor
      FROM public.contas_receber cr JOIN public.vendas v ON v.id=cr.venda_id AND v.empresa_id=cr.empresa_id
      WHERE cr.empresa_id=v_empresa AND cr.venda_id=v_comanda.venda_id AND cr.cliente_id=p_cliente_id
       AND cr.vencimento=p_vencimento AND cr.origem='nota_prazo' AND cr.status<>'cancelado' AND v.cancelada_em IS NULL;
    IF FOUND THEN RETURN jsonb_build_object('comanda_id',v_comanda.id,'mesa_id',v_comanda.mesa_id,'venda_id',v_venda,
     'numero_venda',v_numero,'titulo_id',v_titulo,'valor_a_receber',v_valor,'vencimento',p_vencimento,'repetida',true); END IF;
    RAISE EXCEPTION 'Comanda já finalizada. Confira o histórico antes de repetir com outros dados.';
  END IF;
  IF p_cliente_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.clientes WHERE id=p_cliente_id AND empresa_id=v_empresa
  ) THEN
    RAISE EXCEPTION 'Selecione um cliente cadastrado nesta empresa.';
  END IF;
  IF p_vencimento IS NULL OR p_vencimento < (now() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'Informe um vencimento válido (hoje ou uma data futura).';
  END IF;
  SELECT * INTO v_comanda FROM public.bar_comandas
   WHERE id=p_comanda_id AND empresa_id=v_empresa FOR UPDATE;
  IF NOT FOUND OR v_comanda.status <> 'aberta' THEN
    RAISE EXCEPTION 'Comanda inexistente ou já finalizada. Atualize a mesa.';
  END IF;
  SELECT * INTO v_mesa FROM public.bar_mesas
   WHERE id=v_comanda.mesa_id AND empresa_id=v_empresa FOR UPDATE;
  IF NOT FOUND OR v_mesa.status <> 'ocupada' OR v_mesa.comanda_atual_id IS DISTINCT FROM v_comanda.id THEN
    RAISE EXCEPTION 'Mesa não está ocupada por esta comanda.';
  END IF;
  IF EXISTS(SELECT 1 FROM public.contas_receber WHERE empresa_id=v_empresa AND venda_id=v_comanda.venda_id) THEN
    RAISE EXCEPTION 'A venda já possui título financeiro. Confira o histórico antes de fechar novamente.';
  END IF;
  v_caixa := private.caixa_exigir_aberto('BAR');
  SELECT * INTO v_saldo FROM private.bar_comanda_saldo_calcular(v_comanda.id,v_empresa);
  v_valor := round(v_saldo.saldo,2);
  IF v_valor <= 0.01 THEN
    RAISE EXCEPTION 'Não existe saldo em aberto para Nota a Prazo.';
  END IF;
  IF v_saldo.total_itens_consumido <= 0 THEN
    RAISE EXCEPTION 'Comanda sem consumo válido.';
  END IF;
  -- Finaliza a venda com os itens reais e os pagamentos já recebidos. Nenhum crédito fictício
  -- é registrado em bar_pagamentos; assim o caixa não soma Nota a Prazo como dinheiro.
  v_venda := private.bar_comanda_finalizar_venda(v_comanda.id,v_empresa);
  UPDATE public.vendas SET cliente_id=p_cliente_id,
      forma_pagamento=CASE WHEN v_saldo.total_pago > 0 THEN 'dividido' ELSE 'Nota a Prazo' END,
      caixa_id=v_caixa
   WHERE id=v_venda AND empresa_id=v_empresa;
  SELECT numero_venda INTO v_numero FROM public.vendas WHERE id=v_venda AND empresa_id=v_empresa;
  INSERT INTO public.contas_receber
    (empresa_id,cliente_id,venda_id,origem,valor_original,saldo_aberto,vencimento,criado_por)
  VALUES (v_empresa,p_cliente_id,v_venda,'nota_prazo',v_valor,v_valor,p_vencimento,auth.uid())
  RETURNING id INTO v_titulo;
  IF v_mesa.pessoas_atual <> 0 THEN
    INSERT INTO public.bar_movimentos_pessoas
      (empresa_id,mesa_id,comanda_id,tipo,quantidade,motivo,criado_por)
    VALUES (v_empresa,v_mesa.id,v_comanda.id,'saida_liberacao',-v_mesa.pessoas_atual,
      'Liberação por Nota a Prazo.',auth.uid());
  END IF;
  UPDATE public.bar_comandas SET status='fechada',fechada_em=now(),atualizado_em=now()
    WHERE id=v_comanda.id AND empresa_id=v_empresa;
  UPDATE public.bar_mesas SET status='livre',comanda_atual_id=NULL,aberta_em=NULL,pessoas_atual=0
    WHERE id=v_mesa.id AND empresa_id=v_empresa;
  INSERT INTO public.bar_eventos (empresa_id,tipo,mesa_id,comanda_id,referencia_id,detalhes,criado_por)
    VALUES (v_empresa,'mesa_fechada',v_mesa.id,v_comanda.id,v_titulo,
      jsonb_build_object('modelo','nota_prazo','cliente_id',p_cliente_id,'caixa_id',v_caixa,
                         'valor_a_receber',v_valor,'vencimento',p_vencimento),auth.uid());
  RETURN jsonb_build_object('comanda_id',v_comanda.id,'mesa_id',v_mesa.id,'venda_id',v_venda,
    'numero_venda',v_numero,'titulo_id',v_titulo,'valor_a_receber',v_valor,'vencimento',p_vencimento);
END;
$function$

CREATE OR REPLACE FUNCTION public.bar_comanda_pagar(p_comanda_id uuid, p_item_ids uuid[], p_formas jsonb, p_desconto numeric DEFAULT 0, p_acrescimo numeric DEFAULT 0, p_taxa_servico numeric DEFAULT 0, p_pessoas_liberadas integer DEFAULT 0)
 RETURNS TABLE(venda_id uuid, numero_venda integer, pagamento_id uuid, total numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_taxa_forma jsonb; v_taxa_id uuid;
  v_empresa     uuid := private.exigir_empresa_ativa();
  v_comanda     public.bar_comandas%rowtype;
  v_mesa        public.bar_mesas%rowtype;
  v_subtotal    numeric;
  v_total       numeric;
  v_soma_formas numeric;
  v_invalido    boolean;
  v_venda       uuid;
  v_numero      integer;
  v_pagamento   uuid;
  v_item        record;
  v_item_venda  bigint;
  v_saldo       record;
  v_caixa       uuid;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_caixa') then
    raise exception 'Você não tem permissão para registrar pagamentos no bar.' using errcode = '42501';
  end if;

  -- Migration 032: RECEBER pagamento exige Caixa BAR aberto.
  v_caixa := private.caixa_exigir_aberto('BAR');

  if p_desconto is null or p_desconto < 0 or p_acrescimo is null or p_acrescimo < 0
     or p_taxa_servico is null or p_taxa_servico < 0 then
    raise exception 'Desconto, acréscimo e taxa de serviço não podem ser negativos.';
  end if;
  if p_pessoas_liberadas is null or p_pessoas_liberadas < 0 then
    raise exception 'Quantidade de pessoas liberadas inválida.';
  end if;
  if p_formas is null or jsonb_typeof(p_formas) <> 'array' or jsonb_array_length(p_formas) = 0 then
    raise exception 'Informe ao menos uma forma de pagamento.';
  end if;
  if jsonb_array_length(p_formas) > 10 then
    raise exception 'Formas de pagamento demais em um único fechamento (máximo 10).';
  end if;

  begin
    select exists (
      select 1 from jsonb_to_recordset(p_formas) as x(forma_pagamento text, valor numeric)
       where x.forma_pagamento is null or btrim(x.forma_pagamento) = '' or x.valor is null or x.valor <= 0
    ) into v_invalido;
  exception when others then
    v_invalido := true;
  end;
  if v_invalido then
    raise exception 'Forma de pagamento inválida (nome e valor maior que zero são obrigatórios).';
  end if;

  select * into v_comanda from public.bar_comandas
   where id = p_comanda_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;
  if v_comanda.status <> 'aberta' then
    raise exception 'Esta comanda não está aberta.';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = v_comanda.mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if p_pessoas_liberadas > v_mesa.pessoas_atual then
    raise exception 'Não é possível liberar % pessoa(s): a mesa tem apenas % no momento.', p_pessoas_liberadas, v_mesa.pessoas_atual;
  end if;

  -- Itens em aberto (não estornados, ainda não pagos) desta comanda — FOR UPDATE trava contra o
  -- mesmo item entrar em dois fechamentos simultâneos (divisão de conta concorrente).
  create temporary table _bar_itens_pagar on commit drop as
  select bpi.id, bpi.quantidade, bpi.preco_unitario, bpi.produto_id
    from public.bar_pedidos_itens bpi
   where bpi.comanda_id = p_comanda_id
     and bpi.empresa_id = v_empresa
     and bpi.estornado = false
     and bpi.pagamento_id is null
     and (p_item_ids is null or bpi.id = any (p_item_ids))
   order by bpi.id
     for update of bpi;

  if not exists (select 1 from _bar_itens_pagar) then
    raise exception 'Não há itens em aberto para pagamento nesta comanda.';
  end if;
  if p_item_ids is not null and (select count(*) from _bar_itens_pagar) <> array_length(p_item_ids, 1) then
    raise exception 'Um ou mais itens informados não estão disponíveis para pagamento (já pagos, cancelados ou de outra comanda).';
  end if;

  select coalesce(sum(quantidade * preco_unitario), 0) into v_subtotal from _bar_itens_pagar;
  v_total := round(v_subtotal - p_desconto + p_acrescimo + p_taxa_servico, 2);
  if v_total < 0 then
    raise exception 'O total do pagamento não pode ficar negativo (confira desconto/acréscimo).';
  end if;

  select coalesce(sum(x.valor), 0) into v_soma_formas
    from jsonb_to_recordset(p_formas) as x(forma_pagamento text, valor numeric);
  if abs(v_soma_formas - v_total) > 0.01 then
    raise exception 'A soma das formas de pagamento (%) não confere com o total a pagar (%).', v_soma_formas, v_total;
  end if;

  -- REVISÃO 3 — pega-ou-cria a venda central da comanda (1 comanda = 1 venda = N pagamentos).
  if v_comanda.venda_id is null then
    insert into public.contadores_venda as c (empresa_id, ultimo_numero)
    values (v_empresa, 1)
    on conflict (empresa_id) do update set ultimo_numero = c.ultimo_numero + 1
    returning c.ultimo_numero into v_numero;

    insert into public.vendas (empresa_id, numero_venda, cliente_id, forma_pagamento, total, tipo, criado_por)
    values (v_empresa, v_numero, null, 'dividido', 0, 'bar', auth.uid())
    returning id into v_venda;

    update public.bar_comandas set venda_id = v_venda
     where id = v_comanda.id and empresa_id = v_empresa;
    v_comanda.venda_id := v_venda;
  else
    v_venda := v_comanda.venda_id;
    select vd.numero_venda into v_numero from public.vendas vd where vd.id = v_venda and vd.empresa_id = v_empresa;
  end if;

  insert into public.bar_pagamentos
    (empresa_id, comanda_id, venda_id, subtotal, desconto, acrescimo, taxa_servico, total, pessoas_liberadas, criado_por, caixa_id)
  values
    (v_empresa, p_comanda_id, v_venda, v_subtotal, p_desconto, p_acrescimo, p_taxa_servico, v_total, p_pessoas_liberadas, auth.uid(), v_caixa)
  returning id into v_pagamento;

  for v_taxa_forma in select value from jsonb_array_elements(p_formas) loop
    insert into public.bar_pagamentos_formas(empresa_id,pagamento_id,forma_pagamento,valor) values(v_empresa,v_pagamento,btrim(v_taxa_forma->>'forma_pagamento'),round((v_taxa_forma->>'valor')::numeric,2)) returning id into v_taxa_id;
    perform private.taxas_registrar('bar',v_taxa_id,v_taxa_forma);
  end loop;

  for v_item in select id, produto_id, quantidade, preco_unitario from _bar_itens_pagar order by id loop
    insert into public.itens_venda (empresa_id, venda_id, produto_id, quantidade, preco_unitario)
    values (v_empresa, v_venda, v_item.produto_id, v_item.quantidade, v_item.preco_unitario)
    returning id into v_item_venda;

    update public.bar_pedidos_itens
       set pagamento_id = v_pagamento, item_venda_id = v_item_venda
     where id = v_item.id and empresa_id = v_empresa;
  end loop;

  update public.vendas vd set total = vd.total + v_total
   where vd.id = v_venda and vd.empresa_id = v_empresa;

  perform private.bar_venda_recalcular_forma_pagamento(v_venda, v_empresa);

  if p_pessoas_liberadas > 0 then
    update public.bar_mesas set pessoas_atual = pessoas_atual - p_pessoas_liberadas
     where id = v_mesa.id and empresa_id = v_empresa;
    insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, pagamento_id, tipo, quantidade, criado_por)
    values (v_empresa, v_mesa.id, p_comanda_id, v_pagamento, 'saida_liberacao', -p_pessoas_liberadas, auth.uid());
  end if;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, referencia_id, detalhes, criado_por)
  values (v_empresa, 'pagamento_registrado', v_mesa.id, p_comanda_id, v_pagamento,
          jsonb_build_object('total', v_total, 'pessoas_liberadas', p_pessoas_liberadas), auth.uid());

  -- ---------------------------------------------------------------------------
  -- Migration 018 (Revisão 2) — LIBERAÇÃO AUTOMÁTICA DA MESA: usa a MESMA fonte única de verdade
  -- do novo modelo (private.bar_comanda_saldo_calcular) — nunca mais checa item por item. Um
  -- pagamento PARCIAL nunca satisfaz saldo <= 0, então nunca fecha a mesa por engano.
  -- ---------------------------------------------------------------------------
  select * into v_saldo from private.bar_comanda_saldo_calcular(p_comanda_id, v_empresa);
  if v_saldo.saldo <= 0.01 then
    perform public.bar_mesa_fechar(v_mesa.id);
  end if;

  venda_id := v_venda;
  numero_venda := v_numero;
  pagamento_id := v_pagamento;
  total := v_total;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_comanda_pagar_valor(p_comanda_id uuid, p_valor numeric, p_formas jsonb, p_idempotencia uuid, p_desconto numeric DEFAULT NULL::numeric, p_acrescimo numeric DEFAULT NULL::numeric, p_taxa_servico numeric DEFAULT NULL::numeric)
 RETURNS TABLE(comanda_id uuid, pagamento_id uuid, valor_recebido numeric, saldo_restante numeric, mesa_liberada boolean, venda_id uuid, numero_venda integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_taxa_forma jsonb; v_taxa_id uuid;
  v_empresa     uuid := private.exigir_empresa_ativa();
  v_comanda     public.bar_comandas%rowtype;
  v_mesa        public.bar_mesas%rowtype;
  v_existente   public.bar_pagamentos%rowtype;
  v_soma_formas numeric;
  v_invalido    boolean;
  v_pagamento   uuid;
  v_saldo_antes  record;
  v_saldo_depois record;
  v_venda       uuid;
  v_numero      integer;
  v_fechou      boolean := false;
  v_caixa       uuid;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_caixa') then
    raise exception 'Você não tem permissão para registrar pagamentos no bar.' using errcode = '42501';
  end if;

  if p_idempotencia is null then
    raise exception 'p_idempotencia é obrigatório.';
  end if;
  if p_valor is null or p_valor <= 0 then
    raise exception 'Informe um valor a receber maior que zero.';
  end if;
  if p_formas is null or jsonb_typeof(p_formas) <> 'array' or jsonb_array_length(p_formas) = 0 then
    raise exception 'Informe ao menos uma forma de pagamento.';
  end if;
  if jsonb_array_length(p_formas) > 10 then
    raise exception 'Formas de pagamento demais em um único recebimento (máximo 10).';
  end if;
  if p_desconto is not null and p_desconto < 0 then
    raise exception 'Desconto não pode ser negativo.';
  end if;
  if p_acrescimo is not null and p_acrescimo < 0 then
    raise exception 'Acréscimo não pode ser negativo.';
  end if;
  if p_taxa_servico is not null and p_taxa_servico < 0 then
    raise exception 'Taxa de serviço não pode ser negativa.';
  end if;

  begin
    select exists (
      select 1 from jsonb_to_recordset(p_formas) as x(forma_pagamento text, valor numeric)
       where x.forma_pagamento is null or btrim(x.forma_pagamento) = '' or x.valor is null or x.valor <= 0
    ) into v_invalido;
  exception when others then
    v_invalido := true;
  end;
  if v_invalido then
    raise exception 'Forma de pagamento inválida (nome e valor maior que zero são obrigatórios).';
  end if;

  select coalesce(sum(x.valor), 0) into v_soma_formas
    from jsonb_to_recordset(p_formas) as x(forma_pagamento text, valor numeric);
  if abs(v_soma_formas - p_valor) > 0.01 then
    raise exception 'A soma das formas de pagamento (%) não confere com o valor a receber (%).', v_soma_formas, p_valor;
  end if;

  select * into v_comanda from public.bar_comandas
   where id = p_comanda_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = v_comanda.mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;

  -- Idempotência: duplo clique / reenvio de rede com a MESMA chave nunca registra de novo — só
  -- devolve o resultado já efetivado da primeira chamada.
  select * into v_existente from public.bar_pagamentos
   where empresa_id = v_empresa and idempotencia_key = p_idempotencia;
  if found then
    select * into v_saldo_depois from private.bar_comanda_saldo_calcular(p_comanda_id, v_empresa);
    comanda_id := p_comanda_id;
    pagamento_id := v_existente.id;
    valor_recebido := v_existente.total;
    saldo_restante := greatest(v_saldo_depois.saldo, 0);
    mesa_liberada := (v_comanda.status = 'fechada') or (v_mesa.status = 'livre');
    venda_id := v_existente.venda_id;
    if v_existente.venda_id is not null then
      select vd.numero_venda into numero_venda from public.vendas vd
       where vd.id = v_existente.venda_id and vd.empresa_id = v_empresa;
    end if;
    return next;
    return;
  end if;

  -- Migration 032: RECEBER pagamento exige Caixa BAR aberto (lançar/enviar pedido NÃO exige). Fica depois do
  -- replay idempotente acima: repetir um pagamento já registrado nunca falha por caixa fechado depois.
  v_caixa := private.caixa_exigir_aberto('BAR');

  if v_comanda.status <> 'aberta' then
    raise exception 'Esta comanda não está aberta.';
  end if;

  -- Ajustes de nível de comanda: SUBSTITUEM (nunca somam) o que já estava persistido. Quando o
  -- parâmetro vem nulo, o valor já salvo é mantido sem alteração — um pagamento parcial seguinte
  -- nunca reaplica o desconto/taxa de novo.
  if p_desconto is not null or p_acrescimo is not null or p_taxa_servico is not null then
    update public.bar_comandas
       set desconto = coalesce(p_desconto, desconto),
           acrescimo = coalesce(p_acrescimo, acrescimo),
           taxa_servico = coalesce(p_taxa_servico, taxa_servico),
           atualizado_em = now()
     where id = v_comanda.id and empresa_id = v_empresa;

    select * into v_comanda from public.bar_comandas
     where id = p_comanda_id and empresa_id = v_empresa;
  end if;

  select * into v_saldo_antes from private.bar_comanda_saldo_calcular(p_comanda_id, v_empresa);

  if v_saldo_antes.saldo <= 0 then
    raise exception 'Esta comanda não tem saldo em aberto para pagamento.';
  end if;
  if p_valor > v_saldo_antes.saldo + 0.01 then
    raise exception 'O valor informado (R$ %) excede o saldo em aberto desta comanda (R$ %).', round(p_valor, 2), v_saldo_antes.saldo;
  end if;

  insert into public.bar_pagamentos
    (empresa_id, comanda_id, venda_id, subtotal, desconto, acrescimo, taxa_servico, total, pessoas_liberadas, idempotencia_key, criado_por, caixa_id)
  values
    (v_empresa, p_comanda_id, null, p_valor, 0, 0, 0, p_valor, 0, p_idempotencia, auth.uid(), v_caixa)
  returning id into v_pagamento;

  for v_taxa_forma in select value from jsonb_array_elements(p_formas) loop
    insert into public.bar_pagamentos_formas(empresa_id,pagamento_id,forma_pagamento,valor) values(v_empresa,v_pagamento,btrim(v_taxa_forma->>'forma_pagamento'),round((v_taxa_forma->>'valor')::numeric,2)) returning id into v_taxa_id;
    perform private.taxas_registrar('bar',v_taxa_id,v_taxa_forma);
  end loop;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, referencia_id, detalhes, criado_por)
  values (v_empresa, 'pagamento_registrado', v_mesa.id, p_comanda_id, v_pagamento,
          jsonb_build_object('total', p_valor, 'modelo', 'valor_monetario'), auth.uid());

  select * into v_saldo_depois from private.bar_comanda_saldo_calcular(p_comanda_id, v_empresa);

  if v_saldo_depois.saldo <= 0.01 then
    v_venda := private.bar_comanda_finalizar_venda(p_comanda_id, v_empresa);
    perform public.bar_mesa_fechar(v_mesa.id);
    v_fechou := true;
    select vd.numero_venda into v_numero from public.vendas vd where vd.id = v_venda and vd.empresa_id = v_empresa;
  else
    v_venda := v_comanda.venda_id;
    if v_venda is not null then
      select vd.numero_venda into v_numero from public.vendas vd where vd.id = v_venda and vd.empresa_id = v_empresa;
    end if;
  end if;

  comanda_id := p_comanda_id;
  pagamento_id := v_pagamento;
  valor_recebido := p_valor;
  saldo_restante := greatest(v_saldo_depois.saldo, 0);
  mesa_liberada := v_fechou;
  venda_id := v_venda;
  numero_venda := v_numero;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_comanda_resumo_financeiro(p_comanda_id uuid)
 RETURNS TABLE(subtotal_aberto numeric, total_pago numeric, total_consumido numeric, itens_em_aberto integer, desconto numeric, acrescimo numeric, taxa_servico numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_existe  boolean;
  v_saldo   record;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm_alguma(array['bar_visualizar', 'bar_mesas', 'bar_pedidos', 'bar_caixa', 'bar_configurar']::text[]) then
    raise exception 'Você não tem permissão para consultar o saldo de comandas do bar.' using errcode = '42501';
  end if;

  select exists (
    select 1 from public.bar_comandas where id = p_comanda_id and empresa_id = v_empresa
  ) into v_existe;
  if not v_existe then
    raise exception 'Comanda não encontrada.';
  end if;

  select * into v_saldo from private.bar_comanda_saldo_calcular(p_comanda_id, v_empresa);

  subtotal_aberto := greatest(v_saldo.saldo, 0);
  total_pago := v_saldo.total_pago;
  total_consumido := v_saldo.total_final;
  itens_em_aberto := v_saldo.itens_em_aberto;
  desconto := v_saldo.desconto;
  acrescimo := v_saldo.acrescimo;
  taxa_servico := v_saldo.taxa_servico;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_configurar_mesas(p_quantidade integer, p_taxa_servico_padrao_percentual numeric DEFAULT NULL::numeric)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa  uuid := private.exigir_empresa_ativa();
  v_atual    integer;
  v_bloqueio text;
  r          record;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_configurar') then
    raise exception 'Você não tem permissão para configurar o módulo Bar.' using errcode = '42501';
  end if;
  if p_quantidade is null or p_quantidade < 0 or p_quantidade > 500 then
    raise exception 'Quantidade de mesas inválida (de 0 a 500).';
  end if;
  if p_taxa_servico_padrao_percentual is not null and (p_taxa_servico_padrao_percentual < 0 or p_taxa_servico_padrao_percentual > 100) then
    raise exception 'Taxa de serviço padrão inválida (de 0 a 100).';
  end if;

  insert into public.bar_configuracoes (empresa_id, quantidade_mesas, taxa_servico_padrao_percentual, atualizado_por)
  values (v_empresa, p_quantidade, coalesce(p_taxa_servico_padrao_percentual, 0), auth.uid())
  on conflict (empresa_id) do update
    set quantidade_mesas = excluded.quantidade_mesas,
        taxa_servico_padrao_percentual = coalesce(p_taxa_servico_padrao_percentual, public.bar_configuracoes.taxa_servico_padrao_percentual),
        atualizado_por = excluded.atualizado_por
  returning quantidade_mesas into v_atual;

  -- Reduzindo: mesa acima do novo total só pode ser "fechada" (fora de serviço, nunca apagada)
  -- se estiver livre. Mesa ocupada acima do novo total BLOQUEIA a redução inteira.
  select string_agg(numero::text, ', ' order by numero) into v_bloqueio
    from public.bar_mesas
   where empresa_id = v_empresa and numero > p_quantidade and status = 'ocupada';
  if v_bloqueio is not null then
    raise exception 'Não é possível reduzir para % mesa(s): a(s) mesa(s) % está(ão) ocupada(s). Feche a conta antes.', p_quantidade, v_bloqueio;
  end if;

  update public.bar_mesas set status = 'fechada'
   where empresa_id = v_empresa and numero > p_quantidade and status = 'livre';

  -- Cria mesas novas que ainda não existem (1..N) e reabre mesas antigas que estavam "fechadas"
  -- por uma redução anterior e voltaram a caber no novo total (nunca cria linha duplicada).
  for r in select generate_series(1, p_quantidade) as numero loop
    insert into public.bar_mesas (empresa_id, numero, status)
    values (v_empresa, r.numero, 'livre')
    on conflict (empresa_id, numero) do update
      set status = 'livre'
      where public.bar_mesas.status = 'fechada';
  end loop;

  return v_atual;
end;
$function$

