CREATE OR REPLACE FUNCTION public.bar_garcom_atualizar(p_id uuid, p_nome text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_nome    text := btrim(coalesce(p_nome, ''));
  v_usuario text := nullif(lower(btrim(p_usuario)), '');
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.perfis p
     where p.id = (select auth.uid()) and p.empresa_id = v_empresa and p.papel = 'proprietario'
  ) then
    raise exception 'Você não tem permissão para gerenciar garçons.' using errcode = '42501';
  end if;
  if length(v_nome) < 2 or length(v_nome) > 200 then
    raise exception 'Informe o nome do garçom (2 a 200 caracteres).';
  end if;
  if v_usuario is null or v_usuario !~ '^\S{2,60}$' then
    raise exception 'Informe um usuário sem espaços, de 2 a 60 caracteres.';
  end if;
  if not exists (
    select 1 from public.perfis p
     where p.id = p_id and p.empresa_id = v_empresa and p.papel = 'funcionario'
       and p.ativo and p.tipo_acesso = 'garcom'
  ) then
    raise exception 'Garçom não encontrado.' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.perfis p
     where p.empresa_id = v_empresa and lower(p.usuario) = v_usuario and p.id <> p_id
  ) then
    raise exception 'Este nome de usuário já está em uso nesta empresa.';
  end if;
  update public.perfis set nome = v_nome, usuario = v_usuario where id = p_id and empresa_id = v_empresa;
end;
$function$

