CREATE OR REPLACE FUNCTION public.bar_garcom_vincular(p_ator uuid, p_user_id uuid, p_nome text, p_usuario text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid;
  v_nome    text := btrim(coalesce(p_nome, ''));
  v_usuario text := nullif(lower(btrim(p_usuario)), '');
begin
  select a.o_empresa into v_empresa from private.bar_garcons_ator(p_ator) a;
  if length(v_nome) < 2 or length(v_nome) > 200 then
    raise exception 'Informe o nome do garçom (2 a 200 caracteres).';
  end if;
  if v_usuario is null or v_usuario !~ '^\S{2,60}$' then
    raise exception 'Informe um usuário sem espaços, de 2 a 60 caracteres.';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'Usuário de autenticação não encontrado.';
  end if;
  if exists (select 1 from public.perfis p where p.id = p_user_id) then
    raise exception 'Este login já está vinculado a uma empresa.';
  end if;
  if (select count(*) from public.perfis p where p.empresa_id = v_empresa and p.papel = 'funcionario') >= 50 then
    raise exception 'Limite de 50 funcionários por empresa atingido.';
  end if;
  if exists (
    select 1 from public.perfis p
     where p.empresa_id = v_empresa and lower(p.usuario) = v_usuario
  ) then
    raise exception 'Este nome de usuário já está em uso nesta empresa.';
  end if;
  insert into public.perfis (id, empresa_id, nome, usuario, papel, permissoes, ativo, criado_por, tipo_acesso)
  values (p_user_id, v_empresa, v_nome, v_usuario, 'funcionario', private.bar_garcom_permissoes_padrao(), true, p_ator, 'garcom');
  return p_user_id;
end;
$function$

