CREATE OR REPLACE FUNCTION public.bar_mesa_adicionar_pessoas(p_mesa_id uuid, p_quantidade integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_mesa    public.bar_mesas%rowtype;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_mesas') then
    raise exception 'Você não tem permissão para alterar pessoas nas mesas do bar.' using errcode = '42501';
  end if;
  if p_quantidade is null or p_quantidade <= 0 then
    raise exception 'A quantidade a adicionar deve ser maior que zero. Para reduzir, peça a correção ao Caixa.';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status <> 'ocupada' then
    raise exception 'Esta mesa não está ocupada.';
  end if;

  update public.bar_mesas set pessoas_atual = pessoas_atual + p_quantidade
   where id = p_mesa_id and empresa_id = v_empresa;

  insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, tipo, quantidade, criado_por)
  values (v_empresa, p_mesa_id, v_mesa.comanda_atual_id, 'entrada', p_quantidade, auth.uid());

  return v_mesa.pessoas_atual + p_quantidade;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_mesa_cancelar(p_mesa_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa    uuid := private.exigir_empresa_ativa();
  v_motivo     text := btrim(coalesce(p_motivo, ''), E' \t\r\n');
  v_mesa       public.bar_mesas%rowtype;
  v_comanda    public.bar_comandas%rowtype;
  v_pagamentos integer;
  v_validos    integer;
  v_cancelados integer;
begin
perform private.florest_cancelamento_exigir('bar_mesa_cancelar',p_mesa_id);
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;

  if length(v_motivo) < 3 then
    raise exception 'Informe o motivo do cancelamento da mesa (mínimo 3 caracteres).';
  end if;

  -- Mesmo encadeamento de travas de bar_mesa_fechar / bar_pedido_lancar: mesa primeiro, depois comanda.
  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status <> 'ocupada' or v_mesa.comanda_atual_id is null then
    raise exception 'Esta mesa não está ocupada (talvez já tenha sido cancelada ou fechada).';
  end if;

  select * into v_comanda from public.bar_comandas
   where id = v_mesa.comanda_atual_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda da mesa não encontrada.';
  end if;
  if v_comanda.status <> 'aberta' then
    raise exception 'A comanda desta mesa não está aberta.';
  end if;

  -- 1) Pagamento de qualquer tipo (inclusive já estornado) ou venda ligada à comanda: fora do cancelamento.
  --    Venda nula => nunca houve documento fiscal para esta comanda (a venda é a origem de todo documento).
  select count(*) into v_pagamentos from public.bar_pagamentos
   where comanda_id = v_comanda.id and empresa_id = v_empresa;
  if v_pagamentos > 0 or v_comanda.venda_id is not null then
    raise exception 'Esta mesa já teve pagamento registrado e não pode ser cancelada. Use o estorno do pagamento (permissão própria); se não restar consumo, feche a mesa normalmente.';
  end if;

  -- 2) Consumo válido pendente: o operador precisa cancelar os itens antes (cada cancelamento é auditado e
  --    devolve o estoque do item).
  select count(*) into v_validos from public.bar_pedidos_itens
   where comanda_id = v_comanda.id and empresa_id = v_empresa and estornado = false;
  if v_validos > 0 then
    raise exception 'Esta mesa ainda tem % item(ns) lançado(s) e não cancelado(s). Cancele os itens antes de cancelar a mesa.', v_validos;
  end if;

  select count(*) into v_cancelados from public.bar_pedidos_itens
   where comanda_id = v_comanda.id and empresa_id = v_empresa and estornado = true;

  -- Pessoas: mesma baixa que o fechamento da mesa faz (log de pessoas nunca é apagado).
  if v_mesa.pessoas_atual <> 0 then
    insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, tipo, quantidade, motivo, criado_por)
    values (v_empresa, p_mesa_id, v_comanda.id, 'saida_liberacao', -v_mesa.pessoas_atual,
            'Liberação no cancelamento da mesa (Migration 045).', auth.uid());
  end if;

  update public.bar_comandas
     set status = 'cancelada', fechada_em = now(),
         cancelada_em = now(), cancelada_por = auth.uid(), cancelamento_motivo = v_motivo
   where id = v_comanda.id and empresa_id = v_empresa;

  update public.bar_mesas
     set status = 'livre', comanda_atual_id = null, aberta_em = null, pessoas_atual = 0
   where id = p_mesa_id and empresa_id = v_empresa;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, detalhes, criado_por)
  values (v_empresa, 'mesa_cancelada', p_mesa_id, v_comanda.id,
          jsonb_build_object('motivo', v_motivo, 'itens_cancelados', v_cancelados, 'mesa_numero', v_mesa.numero),
          auth.uid());

  return jsonb_build_object('ok', true, 'mesa_id', p_mesa_id, 'comanda_id', v_comanda.id,
                            'itens_cancelados', v_cancelados);
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_mesa_corrigir_pessoas(p_mesa_id uuid, p_pessoas_total integer, p_motivo text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_mesa    public.bar_mesas%rowtype;
  v_delta   integer;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_corrigir_pessoas') then
    raise exception 'Você não tem permissão para corrigir a quantidade de pessoas nas mesas do bar.' using errcode = '42501';
  end if;
  if p_pessoas_total is null or p_pessoas_total < 0 then
    raise exception 'Quantidade de pessoas inválida.';
  end if;
  if p_motivo is null or length(btrim(p_motivo)) < 3 then
    raise exception 'Informe o motivo da correção (mínimo 3 caracteres).';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status <> 'ocupada' then
    raise exception 'Esta mesa não está ocupada.';
  end if;

  v_delta := p_pessoas_total - v_mesa.pessoas_atual;
  if v_delta = 0 then
    return v_mesa.pessoas_atual;
  end if;

  update public.bar_mesas set pessoas_atual = p_pessoas_total
   where id = p_mesa_id and empresa_id = v_empresa;

  insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, tipo, quantidade, motivo, criado_por)
  values (v_empresa, p_mesa_id, v_mesa.comanda_atual_id, 'correcao', v_delta, btrim(p_motivo), auth.uid());

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, criado_por, detalhes)
  values (v_empresa, 'pessoas_corrigidas', p_mesa_id, v_mesa.comanda_atual_id, auth.uid(),
          jsonb_build_object('de', v_mesa.pessoas_atual, 'para', p_pessoas_total, 'motivo', btrim(p_motivo)));

  return p_pessoas_total;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_mesa_fechar(p_mesa_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_mesa    public.bar_mesas%rowtype;
  v_comanda public.bar_comandas%rowtype;
  v_saldo   record;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm_alguma(array['bar_mesas', 'bar_caixa']::text[]) then
    raise exception 'Você não tem permissão para fechar mesas do bar.' using errcode = '42501';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status <> 'ocupada' or v_mesa.comanda_atual_id is null then
    raise exception 'Esta mesa não está ocupada.';
  end if;

  select * into v_comanda from public.bar_comandas
   where id = v_mesa.comanda_atual_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda da mesa não encontrada.';
  end if;

  select * into v_saldo from private.bar_comanda_saldo_calcular(v_comanda.id, v_empresa);
  if v_saldo.saldo > 0.01 then
    raise exception 'Existem itens ou saldo não pagos nesta comanda (saldo em aberto: R$ %). Registre o pagamento antes de fechar a mesa.', v_saldo.saldo;
  end if;

  -- Pagamento normal já finaliza a venda antes de chamar este fechamento.
  -- Sem consumo válido, liberar uma mesa vazia não deve fabricar uma venda de valor zero.
  if v_comanda.venda_id is null and exists (
    select 1 from public.bar_pedidos_itens i
     where i.comanda_id = v_comanda.id and i.empresa_id = v_empresa and not i.estornado
  ) then
    perform private.bar_comanda_finalizar_venda(v_comanda.id,v_empresa);
  end if;
  if v_mesa.pessoas_atual <> 0 then
    insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, tipo, quantidade, motivo, criado_por)
    values (v_empresa, p_mesa_id, v_comanda.id, 'saida_liberacao', -v_mesa.pessoas_atual,
            'Liberação automática no fechamento simplificado (Migration 018).', auth.uid());
  end if;

  update public.bar_comandas set status = 'fechada', fechada_em = now()
   where id = v_comanda.id and empresa_id = v_empresa;

  update public.bar_mesas
     set status = 'livre', comanda_atual_id = null, aberta_em = null, pessoas_atual = 0
   where id = p_mesa_id and empresa_id = v_empresa;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, criado_por)
  values (v_empresa, 'mesa_fechada', p_mesa_id, v_comanda.id, auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_mesa_transferir(p_mesa_origem_id uuid, p_mesa_destino_numero integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_empresa uuid := private.exigir_empresa_ativa();
 v_origem public.bar_mesas%ROWTYPE;
 v_destino public.bar_mesas%ROWTYPE;
 v_comanda public.bar_comandas%ROWTYPE;
 v_destino_id uuid;
 v_lock record;
 v_pedidos integer;
BEGIN
 IF NOT private.empresa_tem_modulo('bar') THEN
   RAISE EXCEPTION 'Módulo Bar indisponível.' USING ERRCODE='42501';
 END IF;
 IF NOT private.perm_alguma(ARRAY['bar_mesas','bar_caixa']::text[]) THEN
   RAISE EXCEPTION 'Sem permissão para transferir mesas.' USING ERRCODE='42501';
 END IF;
 IF p_mesa_origem_id IS NULL OR p_mesa_destino_numero IS NULL OR p_mesa_destino_numero <= 0 THEN
   RAISE EXCEPTION 'Informe uma mesa de destino válida.';
 END IF;
 SELECT id INTO v_destino_id FROM public.bar_mesas
 WHERE empresa_id=v_empresa AND numero=p_mesa_destino_numero;
 IF v_destino_id IS NULL THEN RAISE EXCEPTION 'Mesa de destino não encontrada.'; END IF;
 IF v_destino_id=p_mesa_origem_id THEN RAISE EXCEPTION 'Origem e destino são a mesma mesa.'; END IF;
 -- Trava as duas mesas em ordem estável para evitar concorrência e deadlock.
 FOR v_lock IN SELECT id FROM public.bar_mesas
    WHERE empresa_id=v_empresa AND id IN (p_mesa_origem_id,v_destino_id)
    ORDER BY id FOR UPDATE LOOP
   NULL;
 END LOOP;
 SELECT * INTO v_origem FROM public.bar_mesas WHERE id=p_mesa_origem_id AND empresa_id=v_empresa;
 SELECT * INTO v_destino FROM public.bar_mesas WHERE id=v_destino_id AND empresa_id=v_empresa;
 IF v_origem.status <> 'ocupada' OR v_origem.comanda_atual_id IS NULL THEN
   RAISE EXCEPTION 'A mesa de origem precisa estar ocupada com comanda aberta.';
 END IF;
 IF v_destino.status <> 'livre' OR v_destino.comanda_atual_id IS NOT NULL THEN
   RAISE EXCEPTION 'A mesa de destino está ocupada ou indisponível.';
 END IF;
 SELECT * INTO v_comanda FROM public.bar_comandas
 WHERE id=v_origem.comanda_atual_id AND empresa_id=v_empresa FOR UPDATE;
 IF NOT FOUND OR v_comanda.status <> 'aberta' OR v_comanda.mesa_id <> v_origem.id THEN
   RAISE EXCEPTION 'Comanda inconsistente ou já encerrada. Transferência bloqueada.';
 END IF;
 -- O pedido mantém id/comanda/idempotência; muda apenas a mesa atual de atendimento.
 UPDATE public.bar_pedidos SET mesa_id=v_destino.id
 WHERE empresa_id=v_empresa AND comanda_id=v_comanda.id AND mesa_id=v_origem.id;
 GET DIAGNOSTICS v_pedidos = ROW_COUNT;
 UPDATE public.bar_comandas SET mesa_id=v_destino.id WHERE empresa_id=v_empresa AND id=v_comanda.id;
 UPDATE public.bar_mesas SET status='ocupada', comanda_atual_id=v_comanda.id,
   pessoas_atual=v_origem.pessoas_atual, aberta_em=COALESCE(v_origem.aberta_em,now())
 WHERE id=v_destino.id AND empresa_id=v_empresa;
 UPDATE public.bar_mesas SET status='livre', comanda_atual_id=NULL,
   pessoas_atual=0, aberta_em=NULL
 WHERE id=v_origem.id AND empresa_id=v_empresa;
 INSERT INTO public.bar_eventos (empresa_id,tipo,mesa_id,comanda_id,criado_por,detalhes)
 VALUES (v_empresa,'mesa_transferida',v_destino.id,v_comanda.id,auth.uid(),
 jsonb_build_object('origem_id',v_origem.id,'origem_numero',v_origem.numero,
                    'destino_id',v_destino.id,'destino_numero',v_destino.numero,
                    'pedidos_atualizados',v_pedidos));
 RETURN jsonb_build_object('sucesso',true,'mesa_origem',v_origem.numero,
     'mesa_destino',v_destino.numero,'comanda_id',v_comanda.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.bar_pagamento_estornar(p_pagamento_id uuid, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa       uuid := private.exigir_empresa_ativa();
  v_pagamento     public.bar_pagamentos%rowtype;
  v_venda         public.vendas%rowtype;
  v_comanda       public.bar_comandas%rowtype;
  v_mesa          public.bar_mesas%rowtype;
  v_doc           record;
  v_estilo_antigo boolean;
  v_mesa_ainda_e_desta_comanda boolean;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_estornar_pagamento') then
    raise exception 'Você não tem permissão para estornar pagamentos do bar.' using errcode = '42501';
  end if;
  if p_motivo is null or length(btrim(p_motivo)) < 3 then
    raise exception 'Informe o motivo do estorno (mínimo 3 caracteres).';
  end if;

  select * into v_pagamento from public.bar_pagamentos
   where id = p_pagamento_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Pagamento não encontrado.';
  end if;
  if v_pagamento.estornado then
    raise exception 'Este pagamento já foi estornado.';
  end if;

  -- Migration 018 (Revisão 2): um pagamento estilo novo pode ainda não ter venda_id (a venda só
  -- é criada quando o saldo chega a zero) — nesse caso não existe documento fiscal nem
  -- itens_venda para checar/reverter, então os blocos abaixo são pulados com segurança.
  if v_pagamento.venda_id is not null then
    select tipo_documento, status, numero into v_doc
      from public.documentos_fiscais
     where venda_id = v_pagamento.venda_id and status in ('processando', 'autorizada')
     limit 1;
    if found then
      raise exception 'Existe um documento fiscal % (status: %, número: %) para a venda desta conta. Trate o cancelamento/substituição fiscal primeiro — o estorno do pagamento do bar foi bloqueado para não ficar inconsistente com o Fiscal.',
        v_doc.tipo_documento, v_doc.status, coalesce(v_doc.numero, '—');
    end if;

    select * into v_venda from public.vendas
     where id = v_pagamento.venda_id and empresa_id = v_empresa
       for update;
    if not found then
      raise exception 'A venda associada a este pagamento não foi encontrada.';
    end if;
    if v_venda.cancelada_em is not null then
      raise exception 'Esta venda já foi cancelada por completo — não é possível estornar pagamentos individuais dela.';
    end if;
  end if;

  v_estilo_antigo := exists (
    select 1 from public.bar_pedidos_itens
     where pagamento_id = p_pagamento_id and empresa_id = v_empresa
  );

  update public.bar_pagamentos
     set estornado = true, estornado_em = now(), estornado_por = auth.uid(), estorno_motivo = btrim(p_motivo)
   where id = p_pagamento_id and empresa_id = v_empresa;

  if v_estilo_antigo then
    -- Comportamento ORIGINAL da Migration 016 (Revisão 3), inalterado: decrementa a venda pelo
    -- valor exato deste pagamento e remove só os itens_venda que ELE gerou.
    update public.vendas set total = total - v_pagamento.total
     where id = v_pagamento.venda_id and empresa_id = v_empresa;

    delete from public.itens_venda iv
     using public.bar_pedidos_itens bpi
     where bpi.pagamento_id = p_pagamento_id
       and bpi.empresa_id = v_empresa
       and bpi.item_venda_id = iv.id
       and iv.empresa_id = v_empresa;
  end if;
  -- Pagamento estilo novo: NUNCA tocou item nem venda ao ser registrado, então estornar também
  -- não toca — só a flag `estornado` acima, que já faz o saldo (private.bar_comanda_saldo_calcular)
  -- recalcular sozinho, na hora, um saldo em aberto maior. vendas.total (quando já existe)
  -- permanece exatamente o mesmo, como pedido explicitamente pelo usuário.

  if v_pagamento.venda_id is not null then
    perform private.bar_venda_recalcular_forma_pagamento(v_pagamento.venda_id, v_empresa);
  end if;

  select * into v_comanda from public.bar_comandas
   where id = v_pagamento.comanda_id and empresa_id = v_empresa
     for update;
  select * into v_mesa from public.bar_mesas
   where id = v_comanda.mesa_id and empresa_id = v_empresa
     for update;

  -- Condição de reabertura — corrigida na primeira versão desta migration, preservada sem
  -- nenhuma mudança: reabre quando a mesa ainda está nesta comanda OU quando a mesa está livre e
  -- nenhuma OUTRA comanda foi criada para ela desde que esta fechou. Nunca reabre por cima de um
  -- atendimento novo já em andamento.
  v_mesa_ainda_e_desta_comanda := (
    v_mesa.comanda_atual_id = v_comanda.id
  ) or (
    v_mesa.status = 'livre' and v_mesa.comanda_atual_id is null
    and not exists (
      select 1 from public.bar_comandas c2
       where c2.mesa_id = v_comanda.mesa_id and c2.empresa_id = v_empresa
         and c2.id <> v_comanda.id
         and c2.criado_em > v_comanda.fechada_em
    )
  );

  if v_mesa_ainda_e_desta_comanda then
    if v_estilo_antigo then
      update public.bar_pedidos_itens
         set pagamento_id = null
       where pagamento_id = p_pagamento_id and empresa_id = v_empresa;
    end if;

    if v_pagamento.pessoas_liberadas > 0 then
      update public.bar_mesas set pessoas_atual = pessoas_atual + v_pagamento.pessoas_liberadas
       where id = v_mesa.id and empresa_id = v_empresa;
      insert into public.bar_movimentos_pessoas (empresa_id, mesa_id, comanda_id, pagamento_id, tipo, quantidade, motivo, criado_por)
      values (v_empresa, v_mesa.id, v_comanda.id, p_pagamento_id, 'correcao', v_pagamento.pessoas_liberadas,
              'Estorno do pagamento: ' || btrim(p_motivo), auth.uid());
    end if;

    if v_comanda.status = 'fechada' then
      update public.bar_comandas set status = 'aberta', fechada_em = null
       where id = v_comanda.id and empresa_id = v_empresa;
      update public.bar_mesas set status = 'ocupada', comanda_atual_id = v_comanda.id,
             aberta_em = coalesce(aberta_em, now())
       where id = v_mesa.id and empresa_id = v_empresa and status <> 'ocupada';
    end if;
  end if;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, referencia_id, detalhes, criado_por)
  values (v_empresa, 'pagamento_estornado', v_comanda.mesa_id, v_pagamento.comanda_id, p_pagamento_id,
          jsonb_build_object(
            'motivo', btrim(p_motivo),
            'venda_id', v_pagamento.venda_id,
            'valor_estornado', v_pagamento.total,
            'estilo', case when v_estilo_antigo then 'itens' else 'valor_monetario' end,
            'itens_reabertos', v_mesa_ainda_e_desta_comanda and v_estilo_antigo,
            'mesa_reaproveitada_por_outro_atendimento', not v_mesa_ainda_e_desta_comanda
          ), auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_pedido_enviar(p_comanda_id uuid, p_itens jsonb, p_idempotencia uuid)
 RETURNS TABLE(pedido_id uuid, itens_criados integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa     uuid := private.exigir_empresa_ativa();
  v_comanda     public.bar_comandas%rowtype;
  v_sem_estoque boolean;
  v_existente   uuid;
  v_pedido      uuid;
  v_item_id     uuid;
  v_invalido    boolean;
  v_qtd_itens   integer := 0;
  r             record;
  v_nome        text;
  v_estoque     numeric;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_pedidos') then
    raise exception 'Você não tem permissão para lançar pedidos no bar.' using errcode = '42501';
  end if;
  if p_idempotencia is null then
    raise exception 'Falha interna: identificador de envio (idempotência) é obrigatório.';
  end if;

  -- Reenvio idempotente (duplo clique / retry de rede): devolve o pedido já criado, sem tocar em
  -- estoque de novo — trava de BANCO (UNIQUE empresa_id,idempotencia_key), igual à Migration 016.
  select id into v_existente from public.bar_pedidos
   where empresa_id = v_empresa and idempotencia_key = p_idempotencia;
  if v_existente is not null then
    pedido_id := v_existente;
    select count(*) into v_qtd_itens from public.bar_pedidos_itens bpi where bpi.pedido_id = v_existente;
    itens_criados := v_qtd_itens;
    return next;
    return;
  end if;

  select * into v_comanda from public.bar_comandas
   where id = p_comanda_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;
  if v_comanda.status <> 'aberta' then
    raise exception 'Esta comanda não está aberta para receber pedidos.';
  end if;

  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    raise exception 'O pedido precisa ter pelo menos um item.';
  end if;
  if jsonb_array_length(p_itens) > 200 then
    raise exception 'Itens demais em um único pedido (máximo 200).';
  end if;

  begin
    select exists (
      select 1 from jsonb_to_recordset(p_itens) as x(bar_produto_id uuid, quantidade numeric, observacao text, escolhas jsonb)
       where x.bar_produto_id is null or x.quantidade is null or x.quantidade <= 0
    ) into v_invalido;
  exception when others then
    v_invalido := true;
  end;
  if v_invalido then
    raise exception 'Item do pedido inválido (produto do cardápio e quantidade maior que zero são obrigatórios).';
  end if;

  select coalesce((select c.permitir_venda_sem_estoque from public.configuracoes_empresa c where c.empresa_id = v_empresa), false)
    into v_sem_estoque;

  -- Itens recebidos, na ordem enviada, já com o "instantâneo" do cardápio (preço/destino/produto
  -- núcleo) — e marcados se usam o modelo NOVO de grupos (usa_grupos = tem ao menos 1 grupo
  -- cadastrado para aquele bar_produto). Um composto sem nenhum grupo cadastrado continua sendo o
  -- modelo antigo (componentes), tratado exatamente como na Migration 016.
  create temporary table _bar_itens_pedido on commit drop as
  select x.ordem, x.bar_produto_id, round(x.quantidade, 4) as quantidade,
         nullif(btrim(coalesce(x.observacao, '')), '') as observacao, x.escolhas,
         bp.produto_id, bp.tipo, bp.destino_operacional, bp.ativo_cardapio,
         p.preco_venda, p.nome as produto_nome,
         exists (select 1 from public.bar_produto_grupos g where g.bar_produto_id = bp.id and g.empresa_id = v_empresa) as usa_grupos
    from rows from (jsonb_to_recordset(p_itens) as (bar_produto_id uuid, quantidade numeric, observacao text, escolhas jsonb))
         with ordinality as x(bar_produto_id, quantidade, observacao, escolhas, ordem)
    left join public.bar_produtos bp on bp.id = x.bar_produto_id and bp.empresa_id = v_empresa
    left join public.produtos p on p.id = bp.produto_id and p.empresa_id = v_empresa;

  if exists (select 1 from _bar_itens_pedido where produto_id is null) then
    raise exception 'Um ou mais itens do pedido não correspondem a produtos do cardápio do bar desta empresa.';
  end if;
  perform private.produtos_exigir_ativos(v_empresa, (select array_agg(ip.produto_id) from _bar_itens_pedido ip));   -- [046:bar_enviar_item]
  if exists (select 1 from _bar_itens_pedido where ativo_cardapio = false) then
    raise exception 'Um ou mais itens do pedido estão desativados no cardápio do bar.';
  end if;

  -- Valida e resolve as ESCOLHAS de cada item composto do modelo novo (requisitos #4/#5/#6):
  -- confere que a quantidade de escolhas bate com o configurado por grupo, que cada produto
  -- escolhido é opção válida daquele grupo, e BLOQUEIA o pedido inteiro se qualquer produto físico
  -- escolhido ainda estiver com destino "Não definido" (nunca lança "escondido" no destino errado).
  create temporary table _bar_escolhas_por_item (
    ordem integer, grupo_id uuid, grupo_nome text, produto_id uuid, produto_nome text,
    destino_operacional text, quantidade numeric(12,4)
  ) on commit drop;

  for r in select * from _bar_itens_pedido where tipo = 'composto' and usa_grupos loop
    if r.escolhas is null or jsonb_typeof(r.escolhas) <> 'array' or jsonb_array_length(r.escolhas) = 0 then
      raise exception 'O item "%" é um produto composto e precisa das escolhas obrigatórias (ex.: qual espeto, qual refrigerante).', r.produto_nome;
    end if;

    if exists (
      select 1
        from public.bar_produto_grupos g
       where g.bar_produto_id = r.bar_produto_id and g.empresa_id = v_empresa
         and g.quantidade_escolhas <> (
               select count(*) from jsonb_to_recordset(r.escolhas) as e(grupo_id uuid, produto_id uuid)
                where e.grupo_id = g.id
             )
    ) then
      raise exception 'O item "%" não tem a quantidade correta de escolhas em um ou mais grupos (grupos: %).', r.produto_nome,
        (select string_agg(g2.nome, ', ') from public.bar_produto_grupos g2 where g2.bar_produto_id = r.bar_produto_id and g2.empresa_id = v_empresa);
    end if;

    if exists (
      select 1 from jsonb_to_recordset(r.escolhas) as e(grupo_id uuid, produto_id uuid)
       where not exists (
               select 1 from public.bar_produto_grupos g where g.id = e.grupo_id and g.bar_produto_id = r.bar_produto_id and g.empresa_id = v_empresa
             )
          or not exists (
               select 1 from public.bar_produto_grupo_opcoes o
                where o.grupo_id = e.grupo_id and o.produto_id = e.produto_id and o.empresa_id = v_empresa
             )
    ) then
      raise exception 'O item "%" tem uma escolha inválida (grupo ou produto não configurado para este item).', r.produto_nome;
    end if;

    if exists (
      select 1
        from jsonb_to_recordset(r.escolhas) as e(grupo_id uuid, produto_id uuid)
        join public.bar_produtos bpe on bpe.produto_id = e.produto_id and bpe.empresa_id = v_empresa
       where bpe.destino_operacional = 'sem_destino'
    ) then
      raise exception 'O item "%" tem uma escolha cujo produto físico ainda está com destino "Não definido". Configure o destino (Bar ou Cozinha) desse produto em Destino dos Produtos antes de lançar o pedido.', r.produto_nome;
    end if;

    insert into _bar_escolhas_por_item (ordem, grupo_id, grupo_nome, produto_id, produto_nome, destino_operacional, quantidade)
    select r.ordem, e.grupo_id, g.nome, e.produto_id, pr.nome, bpe.destino_operacional,
           (r.quantidade * count(*))::numeric(12,4) as quantidade
      from jsonb_to_recordset(r.escolhas) as e(grupo_id uuid, produto_id uuid)
      join public.bar_produto_grupos g on g.id = e.grupo_id and g.empresa_id = v_empresa
      join public.produtos pr on pr.id = e.produto_id and pr.empresa_id = v_empresa
      join public.bar_produtos bpe on bpe.produto_id = e.produto_id and bpe.empresa_id = v_empresa
     group by r.ordem, e.grupo_id, e.produto_id, g.nome, pr.nome, bpe.destino_operacional;
  end loop;

  -- Baixa de estoque POR ITEM: simples (o próprio produto); composto modelo ANTIGO (componentes
  -- marcados baixar_estoque, idêntico à Migration 016); composto modelo NOVO (exatamente os
  -- produtos físicos escolhidos, já resolvidos acima em _bar_escolhas_por_item).
  create temporary table _bar_baixas_por_item on commit drop as
  select ip.ordem, ip.produto_id as produto_baixa_id, ip.quantidade as quantidade
    from _bar_itens_pedido ip
   where ip.tipo = 'simples'
  union all
  select ip.ordem, c.componente_produto_id as produto_baixa_id, (ip.quantidade * c.quantidade)::numeric as quantidade
    from _bar_itens_pedido ip
    join public.bar_produtos_componentes c on c.bar_produto_id = ip.bar_produto_id and c.empresa_id = v_empresa
   where ip.tipo = 'composto' and ip.usa_grupos = false and c.baixar_estoque = true
  union all
  select e.ordem, e.produto_id as produto_baixa_id, e.quantidade
    from _bar_escolhas_por_item e;

  -- Trava e baixa o estoque núcleo, um produto por vez, em ordem fixa (evita deadlock), pelo TOTAL
  -- agregado deste pedido — mesmo padrão de public.registrar_venda e da Migration 016.
  for r in
    select produto_baixa_id as produto_id, sum(quantidade) as qtd
      from _bar_baixas_por_item
     group by produto_baixa_id
     order by produto_baixa_id
  loop
    select p.nome, p.quantidade_estoque into v_nome, v_estoque
      from public.produtos p
     where p.id = r.produto_id and p.empresa_id = v_empresa
       for update;
    if not found then
      raise exception 'Produto do núcleo não encontrado para baixa de estoque.';
    end if;
    perform private.produto_exigir_ativo(v_empresa, r.produto_id);   -- [046:bar_enviar_baixa]
    if v_estoque < r.qtd and not v_sem_estoque then
      raise exception 'Estoque insuficiente para "%": disponível %, necessário %.', v_nome, v_estoque, r.qtd;
    end if;
    update public.produtos set quantidade_estoque = quantidade_estoque - r.qtd
     where id = r.produto_id and empresa_id = v_empresa;
  end loop;

  insert into public.bar_pedidos (empresa_id, comanda_id, mesa_id, idempotencia_key, criado_por)
  values (v_empresa, p_comanda_id, v_comanda.mesa_id, p_idempotencia, auth.uid())
  returning id into v_pedido;

  -- Insere cada item e, na sequência, sua baixa detalhada (para estorno exato depois) e, quando é
  -- um composto do modelo novo, o snapshot das escolhas (para o Bar/Cozinha e o Relatório B). O
  -- item comercial de um composto do modelo novo é gravado com destino_operacional='sem_destino'
  -- (ele mesmo nunca é roteado ao Bar/Cozinha — quem é roteado são as escolhas, uma por destino).
  for r in select * from _bar_itens_pedido order by ordem loop
    insert into public.bar_pedidos_itens
      (empresa_id, pedido_id, comanda_id, bar_produto_id, produto_id, quantidade, preco_unitario, destino_operacional, observacao)
    values
      (v_empresa, v_pedido, p_comanda_id, r.bar_produto_id, r.produto_id, r.quantidade,
       round(r.preco_venda, 2),
       case when r.tipo = 'composto' and r.usa_grupos then 'sem_destino' else r.destino_operacional end,
       r.observacao)
    returning id into v_item_id;

    insert into public.bar_pedidos_itens_baixas (empresa_id, pedido_item_id, produto_id, quantidade)
    select v_empresa, v_item_id, b.produto_baixa_id, b.quantidade
      from _bar_baixas_por_item b
     where b.ordem = r.ordem;

    if r.tipo = 'composto' and r.usa_grupos then
      insert into public.bar_pedidos_itens_escolhas
        (empresa_id, pedido_item_id, grupo_id, grupo_nome, produto_id, produto_nome, destino_operacional, quantidade)
      select v_empresa, v_item_id, e.grupo_id, e.grupo_nome, e.produto_id, e.produto_nome, e.destino_operacional, e.quantidade
        from _bar_escolhas_por_item e
       where e.ordem = r.ordem;
    end if;

    v_qtd_itens := v_qtd_itens + 1;
  end loop;

  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, referencia_id, detalhes, criado_por)
  values (v_empresa, 'pedido_enviado', v_comanda.mesa_id, p_comanda_id, v_pedido, jsonb_build_object('itens', v_qtd_itens), auth.uid());

  pedido_id := v_pedido;
  itens_criados := v_qtd_itens;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_pedido_item_cancelar(p_item_id uuid, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_item    public.bar_pedidos_itens%rowtype;
  v_mesa_id uuid;
  v_comanda_id uuid;
  v_mesa public.bar_mesas%rowtype;
  v_comanda public.bar_comandas%rowtype;
  r         record;
  v_saldo   record;
begin
perform private.florest_cancelamento_exigir('bar_item_cancelar',p_item_id);
if exists(select 1 from public.bar_pedidos_itens i join public.bar_comandas c on c.id=i.comanda_id and c.empresa_id=i.empresa_id join public.documentos_fiscais d on d.venda_id=c.venda_id and d.empresa_id=c.empresa_id where i.id=p_item_id and i.empresa_id=private.exigir_empresa_ativa() and d.status in ('processando','autorizada')) then raise exception 'Documento fiscal impede cancelamento operacional. Utilize o procedimento fiscal separado.'; end if;
if exists(select 1 from public.bar_pedidos_itens where id=p_item_id and empresa_id=private.exigir_empresa_ativa() and item_venda_id is not null) then raise exception 'Item já consolidado em venda. Requer procedimento administrativo separado.'; end if;
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;

  if p_motivo is null or length(btrim(p_motivo)) < 3 then
    raise exception 'Informe o motivo do cancelamento (mínimo 3 caracteres).';
  end if;

  -- Travas na ordem mesa -> comanda -> item, igual ao fechamento e ao lançamento.
  -- A leitura inicial identifica a mesa, mas a validade é rechecada sob as travas.
  select i.comanda_id, c.mesa_id into v_comanda_id, v_mesa_id
    from public.bar_pedidos_itens i
    join public.bar_comandas c on c.id = i.comanda_id and c.empresa_id = i.empresa_id
   where i.id = p_item_id and i.empresa_id = v_empresa;
  if not found then
    raise exception 'Item de pedido não encontrado.';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = v_mesa_id and empresa_id = v_empresa for update;
  if not found or v_mesa.status <> 'ocupada' or v_mesa.comanda_atual_id is distinct from v_comanda_id then
    raise exception 'Mesa não está ocupada com esta comanda.';
  end if;

  select * into v_comanda from public.bar_comandas
   where id = v_comanda_id and empresa_id = v_empresa for update;
  if not found or v_comanda.status <> 'aberta' then
    raise exception 'Esta comanda não está aberta.';
  end if;

  select * into v_item from public.bar_pedidos_itens
   where id = p_item_id and empresa_id = v_empresa and comanda_id = v_comanda_id
     for update;
  if not found then
    raise exception 'Item de pedido não encontrado.';
  end if;
  if v_item.estornado then
    raise exception 'Este item já foi cancelado.';
  end if;

  -- Migration 018 (Revisão 2): item vinculado a um pagamento ESTILO ANTIGO continua bloqueado
  -- aqui, exatamente como a Migration 016 sempre fez — desfazer isso exigiria reverter
  -- itens_venda/vendas.total já assentados; o caminho seguro continua sendo estornar o pagamento
  -- primeiro (public.bar_pagamento_estornar). Um item nunca vinculado a pagamento nenhum (o caso
  -- normal do novo modelo monetário) passa a poder ser cancelado mesmo após já ter havido
  -- pagamento parcial — protegido, em vez disso, pela trava financeira ao final desta função.
  if v_item.pagamento_id is not null then
    raise exception 'Este item já foi incluído em um pagamento e não pode mais ser cancelado. Estorne o pagamento primeiro.';
  end if;


  for r in
    select produto_id, quantidade from public.bar_pedidos_itens_baixas
     where pedido_item_id = p_item_id and empresa_id = v_empresa and estornada = false
     order by produto_id
  loop
    update public.produtos set quantidade_estoque = quantidade_estoque + r.quantidade
     where id = r.produto_id and empresa_id = v_empresa;
    if not found then
      raise exception 'Produto do núcleo não encontrado ao devolver estoque.';
    end if;
  end loop;

  update public.bar_pedidos_itens_baixas
     set estornada = true
   where pedido_item_id = p_item_id and empresa_id = v_empresa and estornada = false;

  update public.bar_pedidos_itens
     set estornado = true, estornado_em = now(), estornado_por = auth.uid(), estorno_motivo = btrim(p_motivo)
   where id = p_item_id and empresa_id = v_empresa;

  -- TRAVA FINANCEIRA (Migration 018, pedida explicitamente pelo usuário): recalcula o saldo já
  -- COM este item cancelado; se os pagamentos válidos ultrapassarem o novo total, desfaz tudo
  -- (o RAISE aborta a transação inteira desta chamada, revertendo também a devolução de estoque
  -- acima) e pede para estornar um pagamento antes.
  select * into v_saldo from private.bar_comanda_saldo_calcular(v_item.comanda_id, v_empresa);
  if v_saldo.saldo < -0.01 then
    raise exception 'Não é possível cancelar este item: os pagamentos já recebidos (R$ %) ficariam maiores que o novo total da conta (R$ %). Estorne um pagamento antes de cancelar.',
      round(v_saldo.total_pago, 2), round(v_saldo.total_final, 2);
  end if;


  insert into public.bar_eventos (empresa_id, tipo, mesa_id, comanda_id, referencia_id, detalhes, criado_por)
  values (v_empresa, 'item_cancelado', v_mesa_id, v_item.comanda_id, p_item_id, jsonb_build_object('motivo', btrim(p_motivo)), auth.uid());

  -- O cancelamento quitou exatamente o saldo: concluir a comanda na mesma transação.
  -- Mantém a validação de permissões, venda e liberação existentes em bar_mesa_fechar.
  if v_saldo.saldo <= 0.01 then
    perform public.bar_mesa_fechar(v_mesa_id);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_pedido_lancar(p_mesa_id uuid, p_itens jsonb, p_idempotencia uuid)
 RETURNS TABLE(comanda_id uuid, pedido_id uuid, itens_criados integer, mesa_aberta_agora boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa   uuid := private.exigir_empresa_ativa();
  v_mesa      public.bar_mesas%rowtype;
  v_comanda   uuid;
  v_abriu     boolean := false;
  v_pedido    uuid;
  v_itens_qtd integer;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_pedidos') then
    raise exception 'Você não tem permissão para lançar pedidos no bar.' using errcode = '42501';
  end if;

  select * into v_mesa from public.bar_mesas
   where id = p_mesa_id and empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Mesa não encontrada.';
  end if;
  if v_mesa.status = 'fechada' then
    raise exception 'Esta mesa está fora de serviço.';
  end if;

  if v_mesa.status = 'livre' then
    v_comanda := private.bar_mesa_abrir_interna(p_mesa_id, 0);
    v_abriu := true;
  else
    v_comanda := v_mesa.comanda_atual_id;
    if v_comanda is null then
      raise exception 'Mesa ocupada sem comanda associada (inconsistência) — contate o suporte.';
    end if;
  end if;

  select pe.pedido_id, pe.itens_criados into v_pedido, v_itens_qtd
    from public.bar_pedido_enviar(v_comanda, p_itens, p_idempotencia) pe;

  comanda_id := v_comanda;
  pedido_id := v_pedido;
  itens_criados := v_itens_qtd;
  mesa_aberta_agora := v_abriu;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_produto_salvar(p_id uuid, p_produto_id uuid, p_tipo text, p_destino_operacional text, p_ativo_cardapio boolean, p_componentes jsonb DEFAULT NULL::jsonb, p_grupos jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa    uuid := private.exigir_empresa_ativa();
  v_id         uuid;
  v_tipo       text := lower(btrim(coalesce(p_tipo, '')));
  v_destino    text := lower(btrim(coalesce(p_destino_operacional, '')));
  v_invalido   boolean;
  v_grupo      record;
  v_grupo_id   uuid;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_configurar') then
    raise exception 'Você não tem permissão para configurar o cardápio do bar.' using errcode = '42501';
  end if;

  if v_tipo not in ('simples', 'composto') then
    raise exception 'Tipo de item do cardápio inválido.';
  end if;
  if p_produto_id is null or not exists (
       select 1 from public.produtos pr where pr.id = p_produto_id and pr.empresa_id = v_empresa
     ) then
    raise exception 'Produto do catálogo não encontrado.';
  end if;

  -- CORREÇÃO (revisão de segurança pré-produção): com o auto-provisionamento desta mesma migration
  -- (seção 6), TODO produto já nasce com uma linha em bar_produtos (tipo simples, sem_destino) — ou
  -- seja, ao contrário da Migration 016, quando o dono clica em "+ Criar produto composto" e escolhe
  -- um produto do catálogo, quase sempre JÁ existe uma linha bar_produtos para aquele produto_id
  -- (a auto-provisionada). O frontend, ao criar, sempre manda p_id = null (não sabe o id da linha
  -- auto-provisionada). Sem este ajuste, o bloco abaixo bloquearia TODA criação de composto com a
  -- mensagem "Este produto já está cadastrado no cardápio do bar" (e, se não bloqueasse, o INSERT
  -- mais abaixo ainda falharia por violar bar_produtos_empresa_produto_key, o unique(empresa_id,
  -- produto_id) da Migration 016). A correção resolve isto de forma transparente: se p_id não foi
  -- informado mas já existe uma linha para este produto_id (o caso normal, pós auto-provisionamento),
  -- passamos a EDITAR essa linha existente em vez de tentar inserir uma segunda — exatamente o que o
  -- dono espera ("converter este produto em composto"), sem exigir que o frontend descubra o id da
  -- linha auto-provisionada antes de chamar esta função.
  if p_id is null then
    select bp.id into p_id from public.bar_produtos bp
     where bp.empresa_id = v_empresa and bp.produto_id = p_produto_id;
  end if;

  if exists (
       select 1 from public.bar_produtos bp
        where bp.empresa_id = v_empresa and bp.produto_id = p_produto_id and bp.id <> coalesce(p_id, '00000000-0000-0000-0000-000000000000'::uuid)
     ) then
    raise exception 'Este produto já está cadastrado no cardápio do bar.';
  end if;

  if v_tipo = 'simples' then
    -- Item simples: destino é o que o dono escolheu (tela "Destino dos Produtos", individual ou
    -- em lote — ver bar_produtos_definir_destino_em_lote).
    if v_destino not in ('bar', 'cozinha', 'sem_destino') then
      raise exception 'Destino operacional inválido.';
    end if;
    if p_componentes is not null or p_grupos is not null then
      raise exception 'Um item simples não pode ter componentes nem grupos de escolha.';
    end if;
  else
    -- Item composto: destino NUNCA é fixo aqui (requisito #6) — é sempre determinado pelos
    -- produtos físicos efetivamente escolhidos no lançamento do pedido (ver bar_pedido_enviar).
    -- p_destino_operacional é ignorado de propósito para composto.
    v_destino := 'sem_destino';
    if (p_componentes is not null) = (p_grupos is not null) then
      raise exception 'Um item composto precisa de componentes (modelo antigo) OU de grupos de escolha (modelo novo) — nunca os dois, nem nenhum.';
    end if;

    if p_componentes is not null then
      -- Modelo antigo (Migration 016) — mantido tal e qual, só para edição de itens já existentes.
      if jsonb_typeof(p_componentes) <> 'array' or jsonb_array_length(p_componentes) = 0 then
        raise exception 'Um item composto precisa de pelo menos um componente.';
      end if;
      if jsonb_array_length(p_componentes) > 100 then
        raise exception 'Componentes demais em um único item (máximo 100).';
      end if;
      begin
        select exists (
          select 1 from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer)
           where x.componente_produto_id is null or x.quantidade is null or x.quantidade <= 0
        ) into v_invalido;
      exception when others then
        v_invalido := true;
      end;
      if v_invalido then
        raise exception 'Componente inválido (produto e quantidade maior que zero são obrigatórios).';
      end if;
      if exists (
           select componente_produto_id
             from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer)
            group by componente_produto_id having count(*) > 1
         ) then
        raise exception 'Um componente não pode aparecer duas vezes na mesma lista.';
      end if;
      if exists (
           select 1 from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer)
            where x.componente_produto_id = p_produto_id
         ) then
        raise exception 'Um item composto não pode ter a si mesmo como componente.';
      end if;
      if exists (
           select 1 from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer)
            where not exists (select 1 from public.produtos pr where pr.id = x.componente_produto_id and pr.empresa_id = v_empresa)
         ) then
        raise exception 'Um ou mais componentes não correspondem a produtos do catálogo desta empresa.';
      end if;
      -- CORREÇÃO (revisão de segurança pré-produção): um componente precisa ser sempre um produto
      -- FÍSICO (requisito #1/#3 — "produtos físicos já cadastrados"), nunca outro item composto. Sem
      -- esta checagem seria possível aninhar um composto dentro de outro (ex.: usar "Jantinha" como
      -- componente do "Combo Família"); o backend trataria esse componente como se fosse um produto
      -- de estoque simples e daria baixa direta em produtos.quantidade_estoque do composto aninhado
      -- (que normalmente não é controlado como estoque), em vez de expandir recursivamente a receita
      -- dele — corrompendo silenciosamente o estoque e os dois relatórios.
      if exists (
           select 1 from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer)
            join public.bar_produtos bp2 on bp2.produto_id = x.componente_produto_id and bp2.empresa_id = v_empresa
           where bp2.tipo = 'composto'
         ) then
        raise exception 'Um componente precisa ser um produto físico simples — um item composto (ex.: outra Jantinha ou Combo) não pode ser componente de outro composto.';
      end if;
    else
      -- Modelo novo (requisito #5): p_grupos = array de
      --   { "nome": text, "quantidade_escolhas": int, "ordem": int,
      --     "opcoes": [ { "produto_id": uuid, "ordem": int }, ... ] }
      if jsonb_typeof(p_grupos) <> 'array' or jsonb_array_length(p_grupos) = 0 then
        raise exception 'Um produto composto precisa de pelo menos um grupo de escolha (ex.: "Escolha o espeto").';
      end if;
      if jsonb_array_length(p_grupos) > 20 then
        raise exception 'Grupos de escolha demais em um único produto composto (máximo 20).';
      end if;
      begin
        select exists (
          select 1 from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
           where g.nome is null or length(btrim(g.nome)) = 0
              or g.opcoes is null or jsonb_typeof(g.opcoes) <> 'array' or jsonb_array_length(g.opcoes) = 0
        ) into v_invalido;
      exception when others then
        v_invalido := true;
      end;
      if v_invalido then
        raise exception 'Grupo de escolha inválido (nome e ao menos uma opção são obrigatórios).';
      end if;
      if exists (
           select 1 from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
            where coalesce(g.quantidade_escolhas, 1) < 1 or coalesce(g.quantidade_escolhas, 1) > jsonb_array_length(g.opcoes)
         ) then
        raise exception 'A quantidade de escolhas de um grupo não pode ser menor que 1 nem maior que o número de opções cadastradas nele.';
      end if;
      begin
        select exists (
          select 1
            from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
            cross join lateral jsonb_to_recordset(g.opcoes) as op(produto_id uuid, ordem integer)
           where op.produto_id is null
              or op.produto_id = p_produto_id
              or not exists (select 1 from public.produtos pr where pr.id = op.produto_id and pr.empresa_id = v_empresa)
        ) into v_invalido;
      exception when others then
        v_invalido := true;
      end;
      if v_invalido then
        raise exception 'Uma ou mais opções de grupo são inválidas, não correspondem a produtos do catálogo desta empresa, ou referenciam o próprio produto composto.';
      end if;
      -- CORREÇÃO (revisão de segurança pré-produção): mesma proteção do modelo antigo de componentes,
      -- aplicada às opções de um grupo — uma opção precisa ser sempre um produto FÍSICO, nunca outro
      -- item composto (evita compostos aninhados e a corrupção de estoque/relatórios descrita acima).
      if exists (
           select 1
             from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
             cross join lateral jsonb_to_recordset(g.opcoes) as op(produto_id uuid, ordem integer)
             join public.bar_produtos bp2 on bp2.produto_id = op.produto_id and bp2.empresa_id = v_empresa
            where bp2.tipo = 'composto'
         ) then
        raise exception 'Uma opção de grupo precisa ser um produto físico simples — um item composto (ex.: outra Jantinha ou Combo) não pode ser opção de escolha de outro composto.';
      end if;
      if exists (
           select 1
             from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
             cross join lateral jsonb_to_recordset(g.opcoes) as op(produto_id uuid, ordem integer)
            group by g.nome, op.produto_id
           having count(*) > 1
         ) then
        raise exception 'Uma opção não pode aparecer duas vezes no mesmo grupo.';
      end if;
    end if;
  end if;

  if v_tipo = 'composto' then   -- [046:bar_produto_salvar]
    perform private.produtos_exigir_ativos(v_empresa, (
      select array_agg(z.pid) from (
        select x.componente_produto_id as pid
          from jsonb_to_recordset(coalesce(p_componentes, '[]'::jsonb)) as x(componente_produto_id uuid)
        union all
        select op.produto_id
          from jsonb_to_recordset(coalesce(p_grupos, '[]'::jsonb)) as g(opcoes jsonb)
          cross join lateral jsonb_to_recordset(g.opcoes) as op(produto_id uuid)) z));
  end if;
  if p_id is null then
    insert into public.bar_produtos (empresa_id, produto_id, tipo, destino_operacional, ativo_cardapio)
    values (v_empresa, p_produto_id, v_tipo, v_destino, coalesce(p_ativo_cardapio, true))
    returning id into v_id;
  else
    update public.bar_produtos
       set produto_id = p_produto_id, tipo = v_tipo, destino_operacional = v_destino,
           ativo_cardapio = coalesce(p_ativo_cardapio, true)
     where id = p_id and empresa_id = v_empresa
    returning id into v_id;
    if v_id is null then
      raise exception 'Item do cardápio do bar não encontrado.';
    end if;
  end if;

  -- Substitui SEMPRE a composição inteira deste item (idêntico em espírito ao comportamento
  -- original de componentes): nunca mistura configuração antiga com nova no mesmo registro. Editar
  -- um composto antigo passando p_grupos migra ele para o modelo novo nesta mesma chamada.
  delete from public.bar_produtos_componentes where bar_produto_id = v_id and empresa_id = v_empresa;
  delete from public.bar_produto_grupos where bar_produto_id = v_id and empresa_id = v_empresa; -- cascade limpa as opções

  if v_tipo = 'composto' and p_componentes is not null then
    insert into public.bar_produtos_componentes (empresa_id, bar_produto_id, componente_produto_id, quantidade, baixar_estoque, ordem)
    select v_empresa, v_id, x.componente_produto_id, x.quantidade, coalesce(x.baixar_estoque, true), coalesce(x.ordem, 0)
      from jsonb_to_recordset(p_componentes) as x(componente_produto_id uuid, quantidade numeric, baixar_estoque boolean, ordem integer);
  elsif v_tipo = 'composto' and p_grupos is not null then
    for v_grupo in
      select g.nome, coalesce(g.quantidade_escolhas, 1) as quantidade_escolhas, coalesce(g.ordem, 0) as ordem, g.opcoes
        from jsonb_to_recordset(p_grupos) as g(nome text, quantidade_escolhas integer, ordem integer, opcoes jsonb)
       order by coalesce(g.ordem, 0)
    loop
      insert into public.bar_produto_grupos (empresa_id, bar_produto_id, nome, quantidade_escolhas, ordem)
      values (v_empresa, v_id, btrim(v_grupo.nome), v_grupo.quantidade_escolhas, v_grupo.ordem)
      returning id into v_grupo_id;

      insert into public.bar_produto_grupo_opcoes (empresa_id, grupo_id, produto_id, ordem)
      select v_empresa, v_grupo_id, op.produto_id, coalesce(op.ordem, 0)
        from jsonb_to_recordset(v_grupo.opcoes) as op(produto_id uuid, ordem integer);
    end loop;
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.bar_produtos_definir_destino_em_lote(p_produto_ids uuid[], p_destino_operacional text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_destino text := lower(btrim(coalesce(p_destino_operacional, '')));
  v_qtd     integer;
begin
  if not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.perm('bar_configurar') then
    raise exception 'Você não tem permissão para configurar o cardápio do bar.' using errcode = '42501';
  end if;
  if v_destino not in ('bar', 'cozinha', 'sem_destino') then
    raise exception 'Destino operacional inválido.';
  end if;
  if p_produto_ids is null or array_length(p_produto_ids, 1) is null then
    raise exception 'Selecione ao menos um produto.';
  end if;
  if array_length(p_produto_ids, 1) > 500 then
    raise exception 'Selecione no máximo 500 produtos por vez.';
  end if;
  if exists (
       select 1 from unnest(p_produto_ids) as pid
        where not exists (select 1 from public.produtos pr where pr.id = pid and pr.empresa_id = v_empresa)
     ) then
    raise exception 'Um ou mais produtos selecionados não pertencem a esta empresa.';
  end if;

  update public.bar_produtos
     set destino_operacional = v_destino
   where empresa_id = v_empresa
     and produto_id = any (p_produto_ids)
     and tipo = 'simples';
  get diagnostics v_qtd = row_count;

  insert into public.bar_eventos (empresa_id, tipo, detalhes, criado_por)
  values (v_empresa, 'destino_definido_em_lote',
          jsonb_build_object('destino', v_destino, 'quantidade_produtos', array_length(p_produto_ids, 1), 'quantidade_afetada', v_qtd),
          auth.uid());

  return v_qtd;
end;
$function$

CREATE OR REPLACE FUNCTION public.caixa_abrir(p_tipo text, p_valor_inicial numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_tipo    text := private.caixa_tipo_validar(p_tipo);
  v_valor   numeric(14,2);
  v_numero  integer;
  v_caixa   public.caixas%rowtype;
begin
  if v_tipo = 'BAR' and not private.empresa_tem_modulo('bar') then
    raise exception 'Este recurso exige o módulo Bar ativo para esta empresa.' using errcode = '42501';
  end if;
  if not private.caixa_pode_operar(v_tipo) then
    raise exception 'Você não tem permissão para abrir o Caixa %.', case when v_tipo = 'BAR' then 'do Bar' else 'PDV' end
      using errcode = '42501';
  end if;

  if p_valor_inicial is not null and (p_valor_inicial < 0 or p_valor_inicial > 99999999999.99) then
    raise exception 'Valor inicial inválido (zero ou maior, até R$ 99.999.999.999,99).';
  end if;
  v_valor := round(coalesce(p_valor_inicial, 0), 2);

  -- serializa aberturas simultâneas da mesma empresa/tipo (numeração e mensagem amigável);
  -- a garantia de verdade continua sendo o índice único parcial.
  perform pg_advisory_xact_lock(hashtextextended(v_empresa::text || ':caixa:' || v_tipo, 0));

  if exists (select 1 from public.caixas c where c.empresa_id = v_empresa and c.tipo_caixa = v_tipo and c.status = 'aberto') then
    raise exception 'Já existe um Caixa % aberto.', case when v_tipo = 'BAR' then 'do Bar' else 'PDV' end
      using errcode = 'CX002';
  end if;

  select coalesce(max(c.numero), 0) + 1 into v_numero
    from public.caixas c where c.empresa_id = v_empresa and c.tipo_caixa = v_tipo;

  begin
    insert into public.caixas (empresa_id, tipo_caixa, numero, status, aberto_por, aberto_por_nome, valor_inicial)
    values (v_empresa, v_tipo, v_numero, 'aberto', (select auth.uid()), private.caixa_nome_usuario(), v_valor)
    returning * into v_caixa;
  exception when unique_violation then
    raise exception 'Já existe um Caixa % aberto.', case when v_tipo = 'BAR' then 'do Bar' else 'PDV' end
      using errcode = 'CX002';
  end;

  return jsonb_build_object('aberto', true, 'caixa', private.caixa_json(v_caixa),
                            'resumo', private.caixa_calcular(v_caixa), 'pode_operar', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.caixa_atual(p_tipo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_tipo    text := private.caixa_tipo_validar(p_tipo);
  v_caixa   public.caixas%rowtype;
begin
  -- BAR: consultar o estado para receber não concede acesso aos dados financeiros.
  -- A autorização sobre o responsável é verificada abaixo, antes de calcular o resumo.
  if v_tipo = 'BAR' then
    if not private.caixa_pode_operar(v_tipo) then
      raise exception 'Você não tem permissão para acessar o caixa do Bar.' using errcode = '42501';
    end if;
  elsif not private.caixa_pode_ver(v_tipo) then
    raise exception 'Você não tem permissão para consultar o Caixa %.', case when v_tipo = 'BAR' then 'do Bar' else 'PDV' end
      using errcode = '42501';
  end if;

  select * into v_caixa from public.caixas c
   where c.empresa_id = v_empresa and c.tipo_caixa = v_tipo and c.status = 'aberto';
  if not found then
    return jsonb_build_object('aberto', false, 'caixa', null, 'resumo', null,
                              'pode_operar', private.caixa_pode_operar(v_tipo));
  end if;
  if v_tipo = 'BAR' and not private.caixa_bar_pode_acessar(v_caixa.empresa_id, v_caixa.aberto_por) then
    -- Há caixa aberto para receber pagamentos, mas seus dados não pertencem a este usuário.
    return jsonb_build_object('aberto', false, 'caixa', null, 'resumo', null,
                              'pode_operar', false, 'bloqueado_por_outro', true);
  end if;
  return jsonb_build_object('aberto', true, 'caixa', private.caixa_json(v_caixa),
                            'resumo', private.caixa_calcular(v_caixa),
                            'pode_operar', private.caixa_pode_operar(v_tipo));
end;
$function$

CREATE OR REPLACE FUNCTION public.caixa_detalhe(p_caixa_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_caixa   public.caixas%rowtype;
  v_mov     jsonb;
  v_recebimentos jsonb;
  v_despesas jsonb;
begin
  select * into v_caixa from public.caixas c where c.id = p_caixa_id and c.empresa_id = v_empresa;
  if not found then
    raise exception 'Caixa não encontrado.';
  end if;
  if not private.caixa_pode_ver(v_caixa.tipo_caixa) then
    raise exception 'Você não tem permissão para consultar este caixa.' using errcode = '42501';
  end if;

  if v_caixa.tipo_caixa = 'BAR' and not private.caixa_bar_pode_acessar(v_caixa.empresa_id, v_caixa.aberto_por) then
    raise exception 'Você só pode acessar caixas do Bar abertos por você na sua empresa.' using errcode = '42501';
  end if;

  if v_caixa.tipo_caixa = 'PDV' then
    select coalesce(jsonb_agg(m.j order by m.em desc, m.numero desc), '[]'::jsonb) into v_mov
      from (
        select v.criado_em as em, v.numero_venda as numero,
               jsonb_build_object(
                 'tipo', 'venda', 'id', v.id, 'numero', v.numero_venda, 'em', v.criado_em, 'total', v.total,
                 'forma_pagamento', v.forma_pagamento, 'cancelada', v.cancelada_em is not null,
                 'cliente', (select cl.nome from public.clientes cl where cl.id = v.cliente_id and cl.empresa_id = v_empresa),
                 'valor_recebido', case when v.forma_pagamento = 'Nota a Prazo' then 0 else null end,
                 'pagamentos', coalesce((select jsonb_agg(jsonb_build_object('forma', vp.forma_pagamento, 'valor', vp.valor) order by vp.ordem)
                                           from public.vendas_pagamentos vp
                                          where vp.empresa_id = v.empresa_id and vp.venda_id = v.id), '[]'::jsonb)
               ) as j
          from public.vendas v
         where v.empresa_id = v_empresa and v.caixa_id = v_caixa.id
         order by v.criado_em desc, v.numero_venda desc
         limit 500
      ) m;
  else
    select coalesce(jsonb_agg(m.j order by m.em desc, m.id desc), '[]'::jsonb) into v_mov
      from (
        select p.criado_em as em, p.id,
               jsonb_build_object(
                 'tipo', 'pagamento', 'id', p.id, 'em', p.criado_em, 'total', p.total, 'estornado', p.estornado,
                 'mesa', mesa.numero,
                 'formas', coalesce((select jsonb_agg(jsonb_build_object('forma', f.forma_pagamento, 'valor', f.valor) order by f.criado_em, f.id)
                                       from public.bar_pagamentos_formas f
                                      where f.empresa_id = p.empresa_id and f.pagamento_id = p.id), '[]'::jsonb)
               ) as j
          from public.bar_pagamentos p
          left join public.bar_comandas cm on cm.empresa_id = p.empresa_id and cm.id = p.comanda_id
          left join public.bar_mesas mesa on mesa.empresa_id = cm.empresa_id and mesa.id = cm.mesa_id
         where p.empresa_id = v_empresa and p.caixa_id = v_caixa.id
         order by p.criado_em desc, p.id desc
         limit 500
      ) m;
  end if;

  select coalesce(jsonb_agg(x.j order by x.em desc,x.id), '[]'::jsonb) into v_recebimentos from (
    select r.id,r.recebido_em as em,jsonb_build_object(
      'id',r.id,'tipo','recebimento_nota_prazo','em',r.recebido_em,'total',r.valor_total,
      'cliente',(select cl.nome from public.clientes cl where cl.id=r.cliente_id and cl.empresa_id=v_empresa),
      'usuario',coalesce((select pf.nome from public.perfis pf where pf.id=r.recebido_por and pf.empresa_id=v_empresa),r.recebido_por::text),
      'formas',(select coalesce(jsonb_agg(jsonb_build_object('forma',f.forma_pagamento,'valor',f.valor) order by f.ordem),'[]'::jsonb)
        from public.contas_receber_recebimentos_formas f where f.empresa_id=v_empresa and f.recebimento_id=r.id),
      'titulos',(select coalesce(jsonb_agg(jsonb_build_object('titulo_id',t.titulo_id,'numero_venda',v.numero_venda,'valor',t.valor_baixado)
        order by t.criado_em,t.id),'[]'::jsonb)
        from public.contas_receber_recebimentos_titulos t
        join public.contas_receber cr on cr.id=t.titulo_id and cr.empresa_id=t.empresa_id
        join public.vendas v on v.id=cr.venda_id and v.empresa_id=cr.empresa_id
        where t.empresa_id=v_empresa and t.recebimento_id=r.id)
    ) as j from public.contas_receber_recebimentos r
    where r.empresa_id=v_empresa and r.caixa_id=v_caixa.id order by r.recebido_em desc,r.id limit 500
  ) x;
  SELECT coalesce(jsonb_agg(x.j ORDER BY x.em DESC,x.id),'[]'::jsonb) INTO v_despesas FROM (
    SELECT p.id,p.pago_em AS em,jsonb_build_object('id',p.id,'despesa_id',d.id,'descricao',d.descricao,
      'parcela',d.cp_parcela,'quantidade',d.cp_quantidade,'total',p.valor,'em',p.pago_em,
      'usuario',coalesce(pf.nome,p.pago_por::text),
      'formas',(SELECT jsonb_agg(jsonb_build_object('forma',f.forma_pagamento,'valor',f.valor) ORDER BY f.ordem)
        FROM public.despesas_pagamentos_formas f WHERE f.empresa_id=v_empresa AND f.pagamento_id=p.id)) AS j
    FROM public.despesas_pagamentos p JOIN public.despesas d ON d.empresa_id=p.empresa_id AND d.id=p.despesa_id
    LEFT JOIN public.perfis pf ON pf.id=p.pago_por AND pf.empresa_id=v_empresa
    WHERE p.empresa_id=v_empresa AND p.caixa_id=v_caixa.id ORDER BY p.pago_em DESC,p.id LIMIT 500
  ) x;
  return jsonb_build_object('caixa', private.caixa_json(v_caixa),
                            'resumo', private.caixa_calcular(v_caixa),
                            'resumo_fechamento', v_caixa.fechamento_resumo,
                            'movimentos', v_mov,
                            'recebimentos_titulos', v_recebimentos,
                            'pagamentos_despesas', v_despesas);
end;
$function$

CREATE OR REPLACE FUNCTION public.caixa_fechar(p_caixa_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_caixa   public.caixas%rowtype;
  v_resumo  jsonb;
begin
  -- FOR UPDATE: espera as vendas/pagamentos em andamento (que seguram FOR SHARE) e impede novas.
  select * into v_caixa from public.caixas c
   where c.id = p_caixa_id and c.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Caixa não encontrado.';
  end if;
  if not private.caixa_pode_operar(v_caixa.tipo_caixa) then
    raise exception 'Você não tem permissão para fechar o Caixa %.', case when v_caixa.tipo_caixa = 'BAR' then 'do Bar' else 'PDV' end
      using errcode = '42501';
  end if;
  if v_caixa.tipo_caixa = 'BAR' and not private.caixa_bar_pode_acessar(v_caixa.empresa_id, v_caixa.aberto_por) then
    raise exception 'Você só pode acessar caixas do Bar abertos por você na sua empresa.' using errcode = '42501';
  end if;

  if v_caixa.status <> 'aberto' then
    raise exception 'Este caixa já foi fechado.' using errcode = 'CX003';
  end if;

  v_resumo := private.caixa_calcular(v_caixa);

  update public.caixas
     set status = 'fechado', fechado_em = now(), fechado_por = (select auth.uid()),
         fechado_por_nome = private.caixa_nome_usuario(), fechamento_resumo = v_resumo
   where id = v_caixa.id and empresa_id = v_empresa
   returning * into v_caixa;

  return jsonb_build_object('caixa', private.caixa_json(v_caixa), 'resumo', v_resumo);
end;
$function$

CREATE OR REPLACE FUNCTION public.caixa_listar(p_tipo text DEFAULT NULL::text, p_de date DEFAULT NULL::date, p_ate date DEFAULT NULL::date, p_limite integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa  uuid := private.exigir_empresa_ativa();
  v_tipos    text[];
  v_limite   integer := least(greatest(coalesce(p_limite, 100), 1), 500);
  v_itens    jsonb;
  v_totais   jsonb;
begin
  if p_tipo is null or upper(btrim(p_tipo)) in ('', 'TODOS') then
    select coalesce(array_agg(t order by t), '{}') into v_tipos
      from unnest(array['PDV','BAR']) t
     where private.caixa_pode_ver(t);
  else
    v_tipos := array[private.caixa_tipo_validar(p_tipo)];
    if not private.caixa_pode_ver(v_tipos[1]) then
      raise exception 'Você não tem permissão para consultar o Caixa %.', case when v_tipos[1] = 'BAR' then 'do Bar' else 'PDV' end
        using errcode = '42501';
    end if;
  end if;
  if coalesce(array_length(v_tipos, 1), 0) = 0 then
    raise exception 'Você não tem permissão para consultar caixas.' using errcode = '42501';
  end if;
  if p_de is not null and p_ate is not null and p_ate < p_de then
    raise exception 'A data final não pode ser anterior à data inicial.';
  end if;

  with sel as (
    select c as cx, c.tipo_caixa, c.aberto_em, c.id
      from public.caixas c
     where c.empresa_id = v_empresa
       and (c.tipo_caixa <> 'BAR' or private.caixa_bar_pode_acessar(c.empresa_id, c.aberto_por))
       and c.tipo_caixa = any (v_tipos)
       and (p_de  is null or (c.aberto_em at time zone 'America/Sao_Paulo')::date >= p_de)
       and (p_ate is null or (c.aberto_em at time zone 'America/Sao_Paulo')::date <= p_ate)
     order by c.aberto_em desc, c.id
     limit v_limite
  ), lin as (
    select s.tipo_caixa, s.aberto_em, s.id,
           private.caixa_json(s.cx) as caixa,
           private.caixa_calcular(s.cx) as resumo
      from sel s
  )
  select coalesce(jsonb_agg(jsonb_build_object('caixa', l.caixa, 'resumo', l.resumo) order by l.aberto_em desc, l.id), '[]'::jsonb),
         jsonb_build_object(
           'caixas', count(*),
           'total_recebido', coalesce(sum((l.resumo ->> 'total_recebido')::numeric), 0),
           'por_tipo', jsonb_build_object(
             'PDV', jsonb_build_object('caixas', count(*) filter (where l.tipo_caixa = 'PDV'),
                                       'total_recebido', coalesce(sum((l.resumo ->> 'total_recebido')::numeric) filter (where l.tipo_caixa = 'PDV'), 0)),
             'BAR', jsonb_build_object('caixas', count(*) filter (where l.tipo_caixa = 'BAR'),
                                       'total_recebido', coalesce(sum((l.resumo ->> 'total_recebido')::numeric) filter (where l.tipo_caixa = 'BAR'), 0))
           )
         )
    into v_itens, v_totais
    from lin l;

  return jsonb_build_object('itens', v_itens, 'totais', v_totais, 'tipos_permitidos', to_jsonb(v_tipos),
                            'limitado', (select count(*) from public.caixas c
                                          where c.empresa_id = v_empresa and c.tipo_caixa = any (v_tipos)
                                            and (c.tipo_caixa <> 'BAR' or private.caixa_bar_pode_acessar(c.empresa_id, c.aberto_por))
                                            and (p_de  is null or (c.aberto_em at time zone 'America/Sao_Paulo')::date >= p_de)
                                            and (p_ate is null or (c.aberto_em at time zone 'America/Sao_Paulo')::date <= p_ate)) > v_limite);
end;
$function$

