CREATE OR REPLACE FUNCTION public.contas_pagar_criar(p_dados jsonb, p_chave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa uuid:=private.exigir_empresa_ativa(); v_desc text:=btrim(p_dados->>'descricao');
  v_tipo text:=p_dados->>'tipo'; v_origem text:=p_dados->>'origem';
  v_valor numeric:=(p_dados->>'valor')::numeric; v_venc date:=(p_dados->>'vencimento')::date;
  v_qtd integer:=(p_dados->>'quantidade')::integer; v_dia integer;
  v_obs text:=nullif(btrim(p_dados->>'observacoes'),''); v_req jsonb; v_anterior jsonb;
  v_ids jsonb; v_cent bigint; v_base bigint; v_sobra integer; v_mes date; v_data date; v_parcela numeric; i integer;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão para Contas a Pagar.' USING ERRCODE='42501'; END IF;
  IF p_chave IS NULL OR v_desc IS NULL OR length(v_desc) NOT BETWEEN 1 AND 200
    OR v_valor IS NULL OR v_valor::text IN ('NaN','Infinity','-Infinity') OR v_valor<=0
    OR v_valor>999999999999.99 OR v_valor<>round(v_valor,2) OR v_venc IS NULL OR NOT isfinite(v_venc)
    OR v_tipo IS NULL OR v_tipo NOT IN ('unica','parcelada','recorrente')
    OR v_origem IS NULL OR v_origem NOT IN ('PDV','BAR') OR v_qtd IS NULL OR v_qtd NOT BETWEEN 1 AND 600
    OR (v_tipo='unica' AND v_qtd<>1) OR length(coalesce(v_obs,''))>4000 THEN
    RAISE EXCEPTION 'Confira descrição, valor positivo com duas casas, vencimento, origem e quantidade (1 a 600).';
  END IF;
  v_dia:=CASE WHEN v_tipo='recorrente' THEN (p_dados->>'dia')::integer ELSE extract(day FROM v_venc)::integer END;
  IF v_dia IS NULL OR v_dia NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'Dia do vencimento deve estar entre 1 e 31.'; END IF;
  v_req:=jsonb_build_object('descricao',v_desc,'tipo',v_tipo,'origem',v_origem,'valor',v_valor,
    'vencimento',v_venc,'quantidade',v_qtd,'dia',v_dia,'observacoes',v_obs);
  PERFORM pg_advisory_xact_lock(hashtextextended('cp_criar:'||v_empresa||':'||p_chave,0));
  SELECT d.cp_solicitacao INTO v_anterior FROM public.despesas d
    WHERE d.empresa_id=v_empresa AND d.cp_lote=p_chave ORDER BY d.cp_parcela LIMIT 1;
  IF FOUND THEN
    IF v_anterior IS DISTINCT FROM v_req THEN RAISE EXCEPTION 'Chave já utilizada para outra conta. Confira o lançamento.'; END IF;
    SELECT jsonb_agg(d.id ORDER BY d.cp_parcela) INTO v_ids FROM public.despesas d WHERE d.empresa_id=v_empresa AND d.cp_lote=p_chave;
    RETURN jsonb_build_object('ids',v_ids,'quantidade',jsonb_array_length(v_ids),'repetida',true);
  END IF;
  v_cent:=(v_valor*100)::bigint; v_base:=v_cent/v_qtd; v_sobra:=(v_cent%v_qtd)::integer;
  IF v_tipo='parcelada' AND v_base<1 THEN RAISE EXCEPTION 'Cada parcela deve ter ao menos um centavo.'; END IF;
  FOR i IN 1..v_qtd LOOP
    v_mes:=(date_trunc('month',v_venc)+(i-1)*interval '1 month')::date;
    v_data:=CASE WHEN v_tipo='unica' THEN v_venc ELSE v_mes+least(v_dia,extract(day FROM v_mes+interval '1 month - 1 day')::integer)-1 END;
    v_parcela:=CASE WHEN v_tipo='parcelada' THEN (v_base+CASE WHEN i<=v_sobra THEN 1 ELSE 0 END)::numeric/100 ELSE v_valor END;
    INSERT INTO public.despesas(empresa_id,descricao,valor,data,vencimento,status,observacoes,
      origem_caixa,cp_tipo,cp_lote,cp_parcela,cp_quantidade,cp_solicitacao)
    VALUES(v_empresa,v_desc,v_parcela,v_data,v_data,'pendente',v_obs,v_origem,v_tipo,p_chave,i,v_qtd,v_req);
  END LOOP;
  SELECT jsonb_agg(d.id ORDER BY d.cp_parcela) INTO v_ids FROM public.despesas d WHERE d.empresa_id=v_empresa AND d.cp_lote=p_chave;
  RETURN jsonb_build_object('ids',v_ids,'quantidade',v_qtd,'repetida',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.contas_pagar_definir_origem(p_despesa uuid, p_origem text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_empresa uuid:=private.exigir_empresa_ativa(); v_d public.despesas%rowtype;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE='42501'; END IF;
  IF p_origem IS NULL OR p_origem NOT IN ('PDV','BAR') THEN RAISE EXCEPTION 'Informe PDV ou BAR.'; END IF;
  SELECT * INTO v_d FROM public.despesas WHERE empresa_id=v_empresa AND id=p_despesa FOR UPDATE;
  IF NOT FOUND OR v_d.status='pago' OR v_d.origem_caixa IS NOT NULL OR EXISTS (
    SELECT 1 FROM public.despesas_pagamentos WHERE empresa_id=v_empresa AND despesa_id=p_despesa
  ) THEN RAISE EXCEPTION 'Conta indisponível para definição de origem.'; END IF;
  UPDATE public.despesas SET origem_caixa=p_origem WHERE empresa_id=v_empresa AND id=p_despesa;
END;
$function$

CREATE OR REPLACE FUNCTION public.contas_pagar_pagar(p_despesa uuid, p_pagamentos jsonb, p_chave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_empresa uuid:=private.exigir_empresa_ativa(); v_d public.despesas%rowtype; v_c public.caixas%rowtype;
  v_p public.despesas_pagamentos%rowtype; v_soma numeric; v_pago numeric; v_formas jsonb; v_req jsonb;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE='42501'; END IF;
  IF p_chave IS NULL OR p_despesa IS NULL THEN RAISE EXCEPTION 'Conta e chave obrigatórias.'; END IF;
  IF EXISTS(SELECT 1 FROM private.venda_mista_validar_pagamentos(p_pagamentos) x WHERE x.forma_pagamento IN ('Outros','Cartão de Crédito')) THEN
    RAISE EXCEPTION 'Use Dinheiro, Pix ou Cartão de Débito. Crédito exige controle de fatura e está bloqueado nesta etapa.';
  END IF;
  SELECT sum(x.valor),jsonb_agg(jsonb_build_object('forma_pagamento',x.forma_pagamento,'valor',x.valor) ORDER BY x.ordem)
    INTO v_soma,v_formas FROM private.venda_mista_validar_pagamentos(p_pagamentos) x;
  IF v_soma IS NULL OR v_soma<=0 THEN RAISE EXCEPTION 'Informe valor positivo.'; END IF;
  v_req:=jsonb_build_object('despesa',p_despesa,'formas',v_formas);
  PERFORM pg_advisory_xact_lock(hashtextextended('cp_pagar:'||v_empresa||':'||p_chave,0));
  SELECT * INTO v_p FROM public.despesas_pagamentos WHERE empresa_id=v_empresa AND chave_idempotencia=p_chave;
  IF FOUND THEN
    IF v_p.solicitacao IS DISTINCT FROM v_req THEN RAISE EXCEPTION 'Chave utilizada para outro pagamento.'; END IF;
    SELECT * INTO v_c FROM public.caixas WHERE empresa_id=v_empresa AND id=v_p.caixa_id;
    RETURN jsonb_build_object('pagamento_id',v_p.id,'valor',v_p.valor,'repetida',true,
      'caixa',jsonb_build_object('tipo_caixa',v_c.tipo_caixa,'numero',v_c.numero));
  END IF;
  BEGIN
    SELECT * INTO v_d FROM public.despesas WHERE empresa_id=v_empresa AND id=p_despesa FOR UPDATE;
    IF NOT FOUND OR v_d.status='pago' THEN RAISE EXCEPTION 'Conta inexistente ou já paga.'; END IF;
    IF v_d.origem_caixa IS NULL THEN RAISE EXCEPTION 'Defina a origem financeira desta conta antes de pagar.'; END IF;
    SELECT coalesce(sum(valor),0) INTO v_pago FROM public.despesas_pagamentos WHERE empresa_id=v_empresa AND despesa_id=v_d.id;
    IF v_soma>v_d.valor-v_pago THEN RAISE EXCEPTION 'Pagamento maior que o saldo pendente.'; END IF;
    -- Mesmo lock das vendas e recebimentos: o fechamento espera esta transação concluir.
    SELECT * INTO v_c FROM public.caixas WHERE empresa_id=v_empresa AND tipo_caixa=v_d.origem_caixa AND status='aberto' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Abra o Caixa % para pagar esta conta.',v_d.origem_caixa USING ERRCODE='CX001'; END IF;
    INSERT INTO public.despesas_pagamentos(empresa_id,despesa_id,caixa_id,valor,pago_por,chave_idempotencia,solicitacao)
      VALUES(v_empresa,v_d.id,v_c.id,v_soma,auth.uid(),p_chave,v_req) RETURNING * INTO v_p;
    INSERT INTO public.despesas_pagamentos_formas(empresa_id,pagamento_id,ordem,forma_pagamento,valor)
      SELECT v_empresa,v_p.id,x.ordem,x.forma_pagamento,x.valor FROM private.venda_mista_validar_pagamentos(p_pagamentos) x;
    UPDATE public.despesas SET status=CASE WHEN v_pago+v_soma=valor THEN 'pago' ELSE 'pendente' END,
      pago_em=CASE WHEN v_pago+v_soma=valor THEN (now() AT TIME ZONE 'America/Sao_Paulo')::date ELSE NULL END
      WHERE empresa_id=v_empresa AND id=v_d.id;
    RETURN jsonb_build_object('pagamento_id',v_p.id,'valor',v_soma,'saldo',v_d.valor-v_pago-v_soma,'repetida',false,
      'caixa',jsonb_build_object('tipo_caixa',v_c.tipo_caixa,'numero',v_c.numero));
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE=SQLSTATE,MESSAGE=SQLERRM,DETAIL='CP_ETAPA3_SEM_PAGAMENTO';
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.contas_pagar_preparar(p_despesa uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_empresa uuid:=private.exigir_empresa_ativa(); v_d public.despesas%rowtype; v_c public.caixas%rowtype; v_pago numeric;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_d FROM public.despesas WHERE empresa_id=v_empresa AND id=p_despesa;
  IF NOT FOUND OR v_d.status='pago' THEN RAISE EXCEPTION 'Conta não encontrada ou já paga.'; END IF;
  IF v_d.origem_caixa IS NULL THEN RAISE EXCEPTION 'Defina explicitamente a origem PDV/BAR desta conta antiga antes de pagar.'; END IF;
  SELECT * INTO v_c FROM public.caixas WHERE empresa_id=v_empresa AND tipo_caixa=v_d.origem_caixa AND status='aberto';
  IF NOT FOUND THEN RAISE EXCEPTION 'Abra o Caixa % para pagar esta conta.',v_d.origem_caixa USING ERRCODE='CX001'; END IF;
  SELECT coalesce(sum(valor),0) INTO v_pago FROM public.despesas_pagamentos WHERE empresa_id=v_empresa AND despesa_id=v_d.id;
  RETURN jsonb_build_object('id',v_d.id,'descricao',v_d.descricao,'valor_original',v_d.valor,'valor_pago',v_pago,
    'saldo',v_d.valor-v_pago,'caixa',jsonb_build_object('id',v_c.id,'tipo_caixa',v_c.tipo_caixa,'numero',v_c.numero));
END;
$function$

CREATE OR REPLACE FUNCTION public.contas_receber_cancelar(p_titulo_id uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_motivo  text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_tit     public.contas_receber%rowtype;
begin
  if not private.perm('financeiro') then
    raise exception 'Você não tem permissão para cancelar contas a receber.' using errcode = '42501';
  end if;
  if p_titulo_id is null then
    raise exception 'Informe o título.';
  end if;
  if v_motivo is null or length(v_motivo) < 3 or length(v_motivo) > 200 then
    raise exception 'Informe o motivo do cancelamento (3 a 200 caracteres).';
  end if;

  select * into v_tit
    from public.contas_receber cr
   where cr.id = p_titulo_id and cr.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Título não encontrado.';
  end if;
  if v_tit.status = 'cancelado' then
    return jsonb_build_object('titulo_id', v_tit.id, 'ja_cancelado', true);
  end if;
  if v_tit.status <> 'aberto' then
    raise exception 'Só é possível cancelar um título totalmente em aberto (este está %).', v_tit.status;
  end if;

  update public.contas_receber
     set status = 'cancelado', saldo_aberto = 0, cancelado_em = now(),
         cancelado_por = (select auth.uid()), motivo_cancelamento = v_motivo
   where id = v_tit.id and empresa_id = v_empresa;

  return jsonb_build_object('titulo_id', v_tit.id, 'ja_cancelado', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.contas_receber_preparar(p_titulos uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa uuid := private.exigir_empresa_ativa();
  v_qtd integer; v_clientes integer; v_tipos integer; v_invalidos integer;
  v_cliente uuid; v_tipo text; v_caixa public.caixas%rowtype; v_itens jsonb; v_total numeric;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão para receber contas.' USING ERRCODE='42501'; END IF;
  IF p_titulos IS NULL OR cardinality(p_titulos) NOT BETWEEN 1 AND 200
    OR EXISTS(SELECT 1 FROM unnest(p_titulos) x WHERE x IS NULL)
    OR (SELECT count(DISTINCT x) FROM unnest(p_titulos) x) <> cardinality(p_titulos) THEN
    RAISE EXCEPTION 'Selecione de 1 a 200 títulos distintos.';
  END IF;
  SELECT count(*), count(DISTINCT t.cliente_id), count(DISTINCT t.tipo),
    count(*) FILTER(WHERE t.tipo IS NULL OR t.status NOT IN ('aberto','parcialmente_pago') OR t.saldo_aberto <= 0),
    min(t.cliente_id::text)::uuid, min(t.tipo), sum(t.saldo_aberto)
  INTO v_qtd,v_clientes,v_tipos,v_invalidos,v_cliente,v_tipo,v_total
  FROM (SELECT cr.*, private.contas_receber_tipo_caixa(cr.id,v_empresa) AS tipo
        FROM public.contas_receber cr WHERE cr.empresa_id=v_empresa AND cr.id=ANY(p_titulos)) t;
  IF v_qtd <> cardinality(p_titulos) THEN RAISE EXCEPTION 'Título não encontrado nesta empresa.'; END IF;
  IF v_invalidos > 0 THEN RAISE EXCEPTION 'Há título quitado, cancelado ou com origem de caixa não identificável/divergente. Confira antes de receber.'; END IF;
  IF v_clientes <> 1 THEN RAISE EXCEPTION 'Selecione títulos de um único cliente.'; END IF;
  IF v_tipos <> 1 THEN RAISE EXCEPTION 'Não misture títulos PDV e BAR. Faça operações separadas.'; END IF;
  SELECT * INTO v_caixa FROM public.caixas c
    WHERE c.empresa_id=v_empresa AND c.tipo_caixa=v_tipo AND c.status='aberto';
  IF NOT FOUND THEN RAISE EXCEPTION 'Abra o Caixa % para receber estes títulos.',v_tipo USING ERRCODE='CX001'; END IF;
  SELECT jsonb_agg(jsonb_build_object('titulo_id',cr.id,'numero_venda',v.numero_venda,
    'valor_original',cr.valor_original,'valor_recebido',cr.valor_original-cr.saldo_aberto,'saldo_aberto',cr.saldo_aberto)
    ORDER BY cr.vencimento,cr.criado_em,cr.id) INTO v_itens
  FROM public.contas_receber cr JOIN public.vendas v ON v.id=cr.venda_id AND v.empresa_id=cr.empresa_id
  WHERE cr.empresa_id=v_empresa AND cr.id=ANY(p_titulos);
  RETURN jsonb_build_object('cliente_id',v_cliente,
    'cliente_nome',(SELECT cl.nome FROM public.clientes cl WHERE cl.id=v_cliente AND cl.empresa_id=v_empresa),
    'tipo_caixa',v_tipo,'caixa',jsonb_build_object('id',v_caixa.id,'numero',v_caixa.numero,'tipo_caixa',v_tipo),
    'titulos',v_itens,'saldo_total',v_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.contas_receber_receber(p_titulos uuid[], p_pagamentos jsonb, p_chave_idempotencia text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_empresa uuid := private.exigir_empresa_ativa();
  v_chave text := btrim(coalesce(p_chave_idempotencia,''));
  v_rec public.contas_receber_recebimentos%rowtype;
  v_solicitacao jsonb; v_formas jsonb; v_soma numeric; v_info jsonb;
  v_tipo text; v_caixa uuid; v_cliente uuid; v_restante numeric; v_baixa numeric;
  v_rateio jsonb := '[]'::jsonb; r record;
BEGIN
  IF NOT private.perm('financeiro') THEN RAISE EXCEPTION 'Sem permissão para receber contas.' USING ERRCODE='42501'; END IF;
  IF length(v_chave) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Chave de recebimento inválida (8 a 100 caracteres).'; END IF;
  IF p_titulos IS NULL OR cardinality(p_titulos) NOT BETWEEN 1 AND 200
    OR EXISTS(SELECT 1 FROM unnest(p_titulos) x WHERE x IS NULL)
    OR (SELECT count(DISTINCT x) FROM unnest(p_titulos) x) <> cardinality(p_titulos) THEN
    RAISE EXCEPTION 'Selecione de 1 a 200 títulos distintos.';
  END IF;
  IF EXISTS(SELECT 1 FROM private.venda_mista_validar_pagamentos(p_pagamentos) x WHERE x.forma_pagamento='Outros') THEN
    RAISE EXCEPTION 'Use Dinheiro, Pix, Cartão de Débito ou Cartão de Crédito.';
  END IF;
  SELECT sum(x.valor),jsonb_agg(jsonb_build_object('forma_pagamento',x.forma_pagamento,'valor',x.valor) ORDER BY x.ordem)
  INTO v_soma,v_formas FROM private.venda_mista_validar_pagamentos(p_pagamentos) x;
  IF v_soma IS NULL OR v_soma <= 0 THEN RAISE EXCEPTION 'Informe um valor recebido maior que zero.'; END IF;
  v_solicitacao := jsonb_build_object('titulos',(SELECT jsonb_agg(x ORDER BY x) FROM unnest(p_titulos) x),'pagamentos',v_formas);
  PERFORM pg_advisory_xact_lock(hashtextextended('contas_receber_receber:'||v_empresa::text||':'||v_chave,0));
  SELECT * INTO v_rec FROM public.contas_receber_recebimentos x WHERE x.empresa_id=v_empresa AND x.chave_idempotencia=v_chave;
  IF FOUND THEN
    IF v_rec.solicitacao IS DISTINCT FROM v_solicitacao THEN
      RAISE EXCEPTION 'Chave já utilizada por outra operação ou recebimento legado. Confira o histórico; não reutilize a chave.';
    END IF;
    RETURN jsonb_build_object(
    'recebimento_id', v_rec.id, 'cliente_id', v_rec.cliente_id, 'valor_total', v_rec.valor_total,
    'quantidade_titulos', v_rec.quantidade_titulos, 'recebido_em', v_rec.recebido_em, 'repetida', true,
    'caixa', (SELECT jsonb_build_object('id', c.id, 'numero', c.numero, 'tipo_caixa', c.tipo_caixa)
              FROM public.caixas c WHERE c.id = v_rec.caixa_id AND c.empresa_id = v_empresa),
    'titulos', (SELECT coalesce(jsonb_agg(t.titulo_id ORDER BY t.titulo_id), '[]'::jsonb)
                FROM public.contas_receber_recebimentos_titulos t WHERE t.recebimento_id = v_rec.id AND t.empresa_id = v_empresa),
    'rateio', (SELECT coalesce(jsonb_agg(jsonb_build_object('titulo_id',t.titulo_id,'valor',t.valor_baixado,
                  'saldo_antes',t.saldo_antes,'saldo_depois',t.saldo_depois) ORDER BY t.criado_em,t.id), '[]'::jsonb)
                FROM public.contas_receber_recebimentos_titulos t WHERE t.recebimento_id = v_rec.id AND t.empresa_id = v_empresa));
  END IF;

  BEGIN -- Qualquer falha aqui garante que esta chave não confirmou recebimento novo.
  -- Ordem fixa dos locks protege contra concorrência e ultrapassagem de saldo.
  PERFORM 1 FROM public.contas_receber cr WHERE cr.empresa_id=v_empresa AND cr.id=ANY(p_titulos) ORDER BY cr.id FOR UPDATE;
  v_info := public.contas_receber_preparar(p_titulos);
  IF v_soma > (v_info->>'saldo_total')::numeric THEN RAISE EXCEPTION 'O valor recebido supera o saldo em aberto.'; END IF;
  v_tipo := v_info->>'tipo_caixa'; v_cliente := (v_info->>'cliente_id')::uuid;
  -- Receber exige Financeiro; não concede acesso administrativo ao caixa.
  -- O caixa não vem do cliente/API. FOR SHARE impede fechamento durante a operação.
  SELECT c.id INTO v_caixa FROM public.caixas c
    WHERE c.empresa_id=v_empresa AND c.tipo_caixa=v_tipo AND c.status='aberto' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Abra o Caixa % para receber estes títulos.',v_tipo USING ERRCODE='CX001'; END IF;

  -- Rateio determinístico: vencimento, criação e ID; o saldo de cada título nunca fica negativo.
  v_restante := v_soma;
  FOR r IN SELECT cr.id,cr.saldo_aberto FROM public.contas_receber cr
    WHERE cr.empresa_id=v_empresa AND cr.id=ANY(p_titulos) ORDER BY cr.vencimento,cr.criado_em,cr.id LOOP
    v_baixa := least(r.saldo_aberto,v_restante);
    IF v_baixa > 0 THEN
      v_rateio := v_rateio || jsonb_build_array(jsonb_build_object('titulo_id',r.id,'valor',v_baixa,
        'saldo_antes',r.saldo_aberto,'saldo_depois',r.saldo_aberto-v_baixa));
      v_restante := v_restante-v_baixa;
    END IF;
  END LOOP;
  IF v_restante <> 0 THEN RAISE EXCEPTION 'Rateio inconsistente; nada foi recebido.'; END IF;
  INSERT INTO public.contas_receber_recebimentos
    (empresa_id,cliente_id,valor_total,quantidade_titulos,recebido_por,chave_idempotencia,caixa_id,solicitacao)
  VALUES(v_empresa,v_cliente,v_soma,jsonb_array_length(v_rateio),(SELECT auth.uid()),v_chave,v_caixa,v_solicitacao)
  RETURNING * INTO v_rec;
  INSERT INTO public.contas_receber_recebimentos_formas(empresa_id,recebimento_id,ordem,forma_pagamento,valor)
  SELECT v_empresa,v_rec.id,x.ordem,x.forma_pagamento,x.valor FROM private.venda_mista_validar_pagamentos(p_pagamentos) x;
  FOR r IN SELECT * FROM jsonb_to_recordset(v_rateio) AS x(titulo_id uuid,valor numeric,saldo_antes numeric,saldo_depois numeric) LOOP
    INSERT INTO public.contas_receber_recebimentos_titulos
      (empresa_id,recebimento_id,titulo_id,valor_baixado,saldo_antes,saldo_depois)
    VALUES(v_empresa,v_rec.id,r.titulo_id,r.valor,r.saldo_antes,r.saldo_depois);
    UPDATE public.contas_receber cr SET saldo_aberto=r.saldo_depois,
      status=CASE WHEN r.saldo_depois=0 THEN 'pago' ELSE 'parcialmente_pago' END,
      quitado_em=CASE WHEN r.saldo_depois=0 THEN now() ELSE NULL END
      WHERE cr.empresa_id=v_empresa AND cr.id=r.titulo_id;
  END LOOP;
  RETURN jsonb_build_object(
    'recebimento_id', v_rec.id, 'cliente_id', v_rec.cliente_id, 'valor_total', v_rec.valor_total,
    'quantidade_titulos', v_rec.quantidade_titulos, 'recebido_em', v_rec.recebido_em, 'repetida', false,
    'caixa', (SELECT jsonb_build_object('id', c.id, 'numero', c.numero, 'tipo_caixa', c.tipo_caixa)
              FROM public.caixas c WHERE c.id = v_rec.caixa_id AND c.empresa_id = v_empresa),
    'titulos', (SELECT coalesce(jsonb_agg(t.titulo_id ORDER BY t.titulo_id), '[]'::jsonb)
                FROM public.contas_receber_recebimentos_titulos t WHERE t.recebimento_id = v_rec.id AND t.empresa_id = v_empresa),
    'rateio', (SELECT coalesce(jsonb_agg(jsonb_build_object('titulo_id',t.titulo_id,'valor',t.valor_baixado,
                  'saldo_antes',t.saldo_antes,'saldo_depois',t.saldo_depois) ORDER BY t.criado_em,t.id), '[]'::jsonb)
                FROM public.contas_receber_recebimentos_titulos t WHERE t.recebimento_id = v_rec.id AND t.empresa_id = v_empresa));
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE=SQLSTATE, MESSAGE=SQLERRM, DETAIL='CR_ETAPA2_SEM_RECEBIMENTO';
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.florest_aplicar_assinatura(p_empresa_id uuid, p_assinatura_id uuid, p_revisao bigint, p_status_conta text, p_vencimento date, p_motivo text DEFAULT NULL::text, p_ator text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_emp    public.empresas%rowtype;
  v_ator   text := left(nullif(btrim(coalesce(p_ator, '')), ''), 200);
  v_motivo text := left(nullif(btrim(coalesce(p_motivo, '')), ''), 500);
  v_novo   public.empresas%rowtype;
begin
  -- validação de entrada (antes de tocar em qualquer linha)
  if p_empresa_id is null or p_assinatura_id is null or p_revisao is null or p_revisao < 1 then
    raise exception 'FS001: empresa_id, assinatura_id e revisao (>= 1) são obrigatórios.' using errcode = 'FS001';
  end if;
  if p_status_conta is null or p_status_conta not in ('pendente','aprovado','bloqueado') then
    raise exception 'FS002: status_conta inválido (use pendente, aprovado ou bloqueado).' using errcode = 'FS002';
  end if;
  if p_status_conta = 'aprovado' and p_vencimento is null then
    raise exception 'FS003: vencimento é obrigatório para aprovar.' using errcode = 'FS003';
  end if;

  -- trava a empresa: dois comandos simultâneos são serializados
  select * into v_emp from public.empresas where id = p_empresa_id for update;
  if not found then
    raise exception 'FS004: empresa não encontrada.' using errcode = 'FS004';
  end if;

  -- proteção: nunca trocar a assinatura já vinculada (vale mesmo para revisão antiga)
  if v_emp.assinatura_id is not null and v_emp.assinatura_id <> p_assinatura_id then
    raise exception 'FS005: esta empresa já está vinculada a outra assinatura.' using errcode = 'FS005';
  end if;

  -- idempotência por revisão
  if p_revisao <= v_emp.florest_revisao then
    return jsonb_build_object(
      'ok', true, 'aplicado', false,
      'motivo', case when p_revisao = v_emp.florest_revisao then 'revisao_repetida' else 'revisao_antiga' end,
      'revisao_atual', v_emp.florest_revisao,
      'status_conta', v_emp.status_conta,
      'vencimento', v_emp.vencimento);
  end if;

  -- a assinatura não pode estar vinculada a OUTRA empresa
  if exists (select 1 from public.empresas o where o.assinatura_id = p_assinatura_id and o.id <> p_empresa_id) then
    raise exception 'FS006: esta assinatura já está vinculada a outra empresa.' using errcode = 'FS006';
  end if;

  -- aplica. bloqueado NÃO é enviado: o trigger private.empresas_regras o deriva de status_conta
  -- e carimba aprovado_em / bloqueado_em nas transições. Aqui ficam aprovado_por e bloqueado_motivo.
  update public.empresas
     set assinatura_id    = p_assinatura_id,
         status_conta     = p_status_conta,
         vencimento       = p_vencimento,
         florest_revisao  = p_revisao,
         florest_sync_em  = now(),
         aprovado_por     = case when p_status_conta = 'aprovado'  and v_emp.status_conta <> 'aprovado'
                                 then coalesce(v_ator, 'florest-sync') else aprovado_por end,
         bloqueado_motivo = case when p_status_conta = 'bloqueado' and v_emp.status_conta <> 'bloqueado'
                                 then coalesce(v_motivo, 'nao_informado') else bloqueado_motivo end
   where id = p_empresa_id
   returning * into v_novo;

  return jsonb_build_object(
    'ok', true, 'aplicado', true,
    'revisao_anterior', v_emp.florest_revisao,
    'revisao_atual', v_novo.florest_revisao,
    'status_conta', v_novo.status_conta,
    'bloqueado', v_novo.bloqueado,
    'vencimento', v_novo.vencimento);
end;
$function$

CREATE OR REPLACE FUNCTION public.florest_autorizacao_emitir(p_solicitante uuid, p_autorizador uuid, p_operacao text, p_alvo uuid, p_parametros jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid; token uuid;
begin
 select p.empresa_id into e from public.perfis p join public.empresas em on em.id=p.empresa_id
 where p.id=p_solicitante and p.ativo and em.status_conta='aprovado' and not em.bloqueado;
 if e is null or not exists(select 1 from public.perfis where id=p_autorizador and empresa_id=e and ativo and papel='proprietario') then raise exception 'Autorização inválida.' using errcode='42501'; end if;
 if p_operacao not in ('bar_item_cancelar','bar_mesa_cancelar','bar_comanda_cancelar','bar_pedido_cancelar') or p_alvo is null then raise exception 'Operação inválida.'; end if;
 if p_operacao like 'bar_%' and not exists(select 1 from public.empresa_modulos where empresa_id=e and modulo='bar' and ativo) then raise exception 'Módulo Bar não contratado.'; end if;
 insert into private.florest_autorizacoes(empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,parametros)
 values(e,p_solicitante,p_autorizador,p_operacao,p_alvo,coalesce(p_parametros,'{}')) returning florest_autorizacoes.token into token;
 return token;
end $function$

CREATE OR REPLACE FUNCTION public.florest_bar_cancelar(p_token uuid, p_operacao text, p_alvo uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.florest_autorizacoes; c public.bar_comandas; item public.bar_pedidos_itens; m uuid; r record; v_resultado jsonb; antes jsonb;
begin
 a:=private.florest_autorizacao_consumir(p_token,auth.uid(),p_operacao,p_alvo,jsonb_build_object('motivo',p_motivo));
 if a.resultado is not null then return a.resultado; end if;
 if a.consumida_em is not null and a.transacao<>txid_current() then raise exception 'Autorização já utilizada.'; end if;
 begin
  if p_operacao='bar_item_cancelar' then
   select * into item from public.bar_pedidos_itens where id=p_alvo and empresa_id=a.empresa_id;
   select * into c from public.bar_comandas where id=item.comanda_id and empresa_id=a.empresa_id;
  elsif p_operacao='bar_pedido_cancelar' then
   select co.* into c from public.bar_pedidos pe join public.bar_comandas co on co.id=pe.comanda_id and co.empresa_id=pe.empresa_id where pe.id=p_alvo and pe.empresa_id=a.empresa_id;
  elsif p_operacao='bar_comanda_cancelar' then select * into c from public.bar_comandas where id=p_alvo and empresa_id=a.empresa_id;
  elsif p_operacao='bar_mesa_cancelar' then select co.* into c from public.bar_mesas me join public.bar_comandas co on co.id=me.comanda_atual_id and co.empresa_id=me.empresa_id where me.id=p_alvo and me.empresa_id=a.empresa_id;
  else raise exception 'Operação inválida.'; end if;
  if c.id is null then raise exception 'Operação não encontrada.'; end if;
  perform 1 from public.bar_mesas where id=c.mesa_id and empresa_id=a.empresa_id for update;
  select * into c from public.bar_comandas where id=c.id and empresa_id=a.empresa_id for update;
  if c.status<>'aberta' then raise exception 'Comanda não está aberta.'; end if;
  if exists(select 1 from public.documentos_fiscais where empresa_id=a.empresa_id and venda_id=c.venda_id and status in ('processando','autorizada')) then raise exception 'Documento fiscal impede cancelamento operacional. Utilize o procedimento fiscal separado.'; end if;
  antes:=jsonb_build_object('mesa_id',c.mesa_id,'comanda_id',c.id,'itens',(select jsonb_agg(to_jsonb(i)) from public.bar_pedidos_itens i where i.comanda_id=c.id and i.empresa_id=a.empresa_id and not i.estornado and (p_operacao not in ('bar_item_cancelar','bar_pedido_cancelar') or i.id=p_alvo or i.pedido_id=p_alvo)));
  if p_operacao='bar_item_cancelar' then perform public.bar_pedido_item_cancelar(p_alvo,p_motivo);
  else
   if p_operacao in ('bar_mesa_cancelar','bar_comanda_cancelar') and exists(select 1 from public.bar_pagamentos where comanda_id=c.id and empresa_id=a.empresa_id) then raise exception 'Há histórico de pagamento; use o fluxo financeiro próprio.'; end if;
   for r in select id from public.bar_pedidos_itens where comanda_id=c.id and empresa_id=a.empresa_id and not estornado and (p_operacao<>'bar_pedido_cancelar' or pedido_id=p_alvo) order by id loop
    perform public.bar_pedido_item_cancelar(r.id,p_motivo);
   end loop;
   if p_operacao in ('bar_mesa_cancelar','bar_comanda_cancelar') then perform public.bar_mesa_cancelar(c.mesa_id,p_motivo); end if;
  end if;
  v_resultado:=jsonb_build_object('ok',true,'mesa_id',c.mesa_id,'comanda_id',c.id);
  insert into public.florest_auditoria_operacoes(empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,motivo,antes,depois,resultado)
  values(a.empresa_id,auth.uid(),a.autorizador_id,p_operacao,p_alvo,p_motivo,antes,v_resultado,'sucesso');
 exception when others then
  v_resultado:=jsonb_build_object('ok',false,'mensagem',sqlerrm);
  insert into public.florest_auditoria_operacoes(empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,motivo,resultado)
  values(a.empresa_id,auth.uid(),a.autorizador_id,p_operacao,p_alvo,p_motivo,'erro: '||sqlerrm);
 end;
 update private.florest_autorizacoes set resultado=v_resultado where token=p_token;
 return v_resultado;
end $function$

CREATE OR REPLACE FUNCTION public.florest_outbox_concluir(p_id bigint, p_ok boolean, p_erro text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_o      public.florest_outbox%rowtype;
  v_espera integer;
begin
  select * into v_o from public.florest_outbox where id = p_id for update;
  if not found then
    raise exception 'FS007: evento do outbox não encontrado.' using errcode = 'FS007';
  end if;
  if v_o.status = 'enviado' then
    return 'enviado';                                  -- idempotente
  end if;

  if coalesce(p_ok, false) then
    update public.florest_outbox
       set status = 'enviado', enviado_em = now(), reservado_ate = null, ultimo_erro = null
     where id = p_id;
    return 'enviado';
  end if;

  if v_o.tentativas >= 20 then
    update public.florest_outbox
       set status = 'falhou', reservado_ate = null, ultimo_erro = left(p_erro, 500)
     where id = p_id;
    return 'falhou';
  end if;

  v_espera := (array[60, 300, 900, 3600, 21600])[least(greatest(v_o.tentativas, 1), 5)];
  update public.florest_outbox
     set status = 'pendente', reservado_ate = null, ultimo_erro = left(p_erro, 500),
         proxima_tentativa_em = now() + make_interval(secs => v_espera)
   where id = p_id;
  return 'pendente';
end;
$function$

CREATE OR REPLACE FUNCTION public.florest_senha_preparar(p_ator uuid, p_alvo uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid;
begin
 select p.empresa_id into e from public.perfis p join public.empresas em on em.id=p.empresa_id
 where p.id=p_ator and p.papel='proprietario' and p.ativo and em.status_conta='aprovado' and not em.bloqueado;
 if e is null or not exists(select 1 from public.perfis where id=p_alvo and empresa_id=e) then raise exception 'Operação não autorizada.' using errcode='42501'; end if;
 return e;
end $function$

CREATE OR REPLACE FUNCTION public.florest_usuario_promover_novo(p_ator uuid, p_alvo uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid:=public.florest_senha_preparar(p_ator,p_alvo); antes jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(e::text,9481));
 select to_jsonb(p) into antes from public.perfis p where id=p_alvo and empresa_id=e for update;
 update public.perfis set papel='proprietario',tipo_acesso='erp' where id=p_alvo and empresa_id=e;
 insert into public.florest_auditoria_operacoes(empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,antes,depois,resultado)
 values(e,p_ator,p_ator,'proprietario_concedido',p_alvo,antes,jsonb_build_object('papel','proprietario'),'sucesso');
end $function$

CREATE OR REPLACE FUNCTION public.florest_usuario_salvar(p_id uuid, p_nome text, p_ativo boolean, p_permissoes text[], p_usuario text, p_papel text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid:=private.exigir_empresa_ativa(); a public.perfis; t public.perfis; permiss text[]; tipo_original text;
begin
 perform pg_advisory_xact_lock(hashtextextended(e::text,9481));
 select * into a from public.perfis where id=auth.uid() and empresa_id=e;
 select * into t from public.perfis where id=p_id and empresa_id=e for update;
 if not found then raise exception 'Usuário não encontrado.'; end if;
 if a.papel<>'proprietario' then
  if p_papel is distinct from t.papel or t.papel='proprietario' then raise exception 'Somente proprietário pode alterar esse acesso.' using errcode='42501'; end if;
  perform public.usuarios_atualizar(p_id,p_nome,p_ativo,p_permissoes,p_usuario); return;
 end if;
 if p_papel not in ('funcionario','proprietario') or p_papel is null then raise exception 'Perfil inválido.'; end if;
 if length(btrim(p_nome)) not between 2 and 200 or p_nome is null then raise exception 'Nome inválido.'; end if;
 if p_usuario is not null and btrim(p_usuario)<>'' and lower(btrim(p_usuario)) !~ '^\S{2,60}$' then raise exception 'Usuário inválido.'; end if;
 permiss:=case when p_papel='proprietario' then t.permissoes else private.usuarios_normalizar_permissoes(coalesce(p_permissoes,'{}'),a.papel,a.permissoes) end;
 if t.papel='proprietario' and p_papel='funcionario' then
  select au.antes->>'tipo_acesso' into tipo_original from public.florest_auditoria_operacoes au
  where au.empresa_id=e and au.alvo_id=p_id and au.operacao='usuario_atualizado' and au.antes->>'papel'='funcionario' and au.depois->>'papel'='proprietario'
  order by au.criado_em desc,au.id desc limit 1;
  if tipo_original='garcom' then permiss:=t.permissoes; end if;
 end if;
 update public.perfis set nome=btrim(p_nome),ativo=p_ativo,papel=p_papel,permissoes=permiss,
  usuario=coalesce(nullif(lower(btrim(p_usuario)),''),usuario),
  tipo_acesso=case when p_papel='proprietario' then 'erp' when tipo_original='garcom' then 'garcom' else tipo_acesso end where id=p_id and empresa_id=e;
 insert into public.florest_auditoria_operacoes(empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,antes,depois,resultado)
 values(e,auth.uid(),auth.uid(),'usuario_atualizado',p_id,to_jsonb(t),(select to_jsonb(p) from public.perfis p where id=p_id),'sucesso');
end $function$

CREATE OR REPLACE FUNCTION public.florest_venda_corrigir(p_venda uuid, p_alteracoes jsonb, p_motivo text, p_idempotencia uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid:=private.exigir_empresa_ativa(); v public.vendas; c public.bar_comandas; r record; x jsonb; f public.bar_pagamentos_formas; b public.bar_pedidos_itens; i public.itens_venda; anterior jsonb; q numeric; preco numeric; delta numeric; saldo record; auditoria public.florest_auditoria_operacoes; novo public.bar_produtos;
begin
 perform private.bar_historico_exigir('bar_venda_editar');
 perform private.bar_historico_exigir('bar_historico_detalhar');
 if p_idempotencia is null or length(btrim(p_motivo))<3 or p_motivo is null then raise exception 'Informe motivo e chave da operação.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_idempotencia::text,182));
 if p_alteracoes is null or jsonb_typeof(p_alteracoes)<>'object' then raise exception 'Alterações inválidas.'; end if;
 select * into auditoria from public.florest_auditoria_operacoes where id=p_idempotencia and empresa_id=e and operacao='venda_corrigida' and alvo_id=p_venda;
 if found then
  if auditoria.solicitante_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Operação pertence a outro usuário.'; END IF;
  if auditoria.depois->'_alteracoes' is distinct from p_alteracoes or auditoria.motivo is distinct from p_motivo then raise exception 'Chave de idempotência reutilizada com conteúdo diferente.'; end if;
  return jsonb_build_object('ok',true,'repetida',true);
 end if;
 select * into c from public.bar_comandas where venda_id=p_venda and empresa_id=e;
 if c.id is null then raise exception 'Esta ferramenta corrige vendas do Bar.'; end if;
 perform 1 from public.bar_mesas where id=c.mesa_id for update;
 select * into c from public.bar_comandas where id=c.id and empresa_id=e for update;
 select * into v from public.vendas where id=p_venda and empresa_id=e for update;
 if v.cancelada_em is not null then raise exception 'Venda cancelada é imutável.'; end if;
 if private.bar_historico_fiscal_bloqueado(p_venda,e) then raise exception 'Documento fiscal impede correção operacional. Utilize o procedimento fiscal separado.'; end if;
 if exists(select 1 from jsonb_object_keys(p_alteracoes) k where k not in ('pagamentos','itens','desconto','cliente_id')) then raise exception 'Campo de alteração não permitido.'; end if;
 perform private.bar_historico_financeiro_travar(p_venda,e);
 anterior:=public.florest_venda_detalhar(p_venda);
 for x in select * from jsonb_array_elements(coalesce(p_alteracoes->'pagamentos','[]')) loop
  select fo.* into f from public.bar_pagamentos_formas fo join public.bar_pagamentos pa on pa.id=fo.pagamento_id and pa.empresa_id=fo.empresa_id where fo.id=(x->>'id')::uuid and pa.venda_id=p_venda and fo.empresa_id=e and not pa.estornado for update of fo;
  if not found then raise exception 'Pagamento não encontrado.'; end if;
  if exists(select 1 from public.bar_pagamentos pa join public.caixas cx on cx.id=pa.caixa_id and cx.empresa_id=pa.empresa_id where pa.id=f.pagamento_id and cx.status<>'aberto') then raise exception 'Caixa encerrado: pagamento não pode ser reclassificado.'; end if;
  if x ? 'valor' and (x->>'valor')::numeric<>f.valor then raise exception 'Valor recebido não pode ser alterado por reclassificação.'; end if;
  if x ? 'forma_pagamento' and x->>'forma_pagamento' is distinct from f.forma_pagamento and x->>'forma_pagamento' not in ('Dinheiro','Pix','Cartão de Débito','Cartão de Crédito') then raise exception 'Forma inválida.'; end if;
  update public.bar_pagamentos_formas set forma_pagamento=coalesce(x->>'forma_pagamento',forma_pagamento),comprovante_referencia=case when x ? 'comprovante_referencia' then left(x->>'comprovante_referencia',200) else comprovante_referencia end where id=f.id;
 end loop;
 if p_alteracoes ? 'itens' or p_alteracoes ? 'desconto' then
  if c.status NOT IN ('aberta','fechada') or exists(select 1 from public.bar_pagamentos where comanda_id=c.id and empresa_id=e and not estornado) then raise exception 'Itens e valores só podem mudar sem pagamentos liquidados. Estorne primeiro os recebimentos pelo fluxo próprio.'; end if;
  if exists(select 1 from public.bar_pagamentos pa join public.caixas cx on cx.id=pa.caixa_id and cx.empresa_id=pa.empresa_id where pa.comanda_id=c.id and pa.empresa_id=e and cx.status<>'aberto') then raise exception 'Há vínculo com caixa encerrado; a correção financeira exige tratamento próprio.'; end if;
  for x in select * from jsonb_array_elements(coalesce(p_alteracoes->'itens','[]')) loop
   select * into i from public.itens_venda where id=(x->>'id')::bigint and venda_id=p_venda and empresa_id=e for update;
   if not found then raise exception 'Item não encontrado.'; end if;
   select * into b from public.bar_pedidos_itens where item_venda_id=i.id and empresa_id=e and not estornado for update;
   if not found then raise exception 'Item sem vínculo operacional seguro.'; end if;
   q:=coalesce((x->>'quantidade')::numeric,i.quantidade); preco:=coalesce((x->>'preco_unitario')::numeric,i.preco_unitario);
   if q<=0 or preco<0 or q::text in ('NaN','Infinity','-Infinity') or preco::text in ('NaN','Infinity','-Infinity') then raise exception 'Quantidade/preço inválidos. Para excluir, use cancelamento autorizado do item.'; end if;
   IF x ? 'bar_produto_id' AND (x->>'bar_produto_id')::uuid IS DISTINCT FROM b.bar_produto_id THEN
    SELECT * INTO novo FROM public.bar_produtos bp WHERE bp.id=(x->>'bar_produto_id')::uuid AND bp.empresa_id=e AND bp.tipo='simples' AND bp.ativo_cardapio;
    IF NOT FOUND OR EXISTS(SELECT 1 FROM public.bar_produto_grupos WHERE bar_produto_id=novo.id AND empresa_id=e)
     OR EXISTS(SELECT 1 FROM public.bar_produtos_componentes WHERE bar_produto_id=novo.id AND empresa_id=e)
    THEN RAISE EXCEPTION 'Substituição exige produto simples ativo; compostos mantêm sua receita original.'; END IF;
    PERFORM 1 FROM public.produtos WHERE empresa_id=e AND id IN
     (SELECT produto_id FROM public.bar_pedidos_itens_baixas WHERE pedido_item_id=b.id AND empresa_id=e AND NOT estornada UNION SELECT novo.produto_id) ORDER BY id FOR UPDATE;
    FOR r IN SELECT * FROM public.bar_pedidos_itens_baixas WHERE pedido_item_id=b.id AND empresa_id=e AND NOT estornada ORDER BY produto_id FOR UPDATE LOOP
     UPDATE public.produtos SET quantidade_estoque=quantidade_estoque+r.quantidade WHERE id=r.produto_id AND empresa_id=e;
    END LOOP;
    UPDATE public.bar_pedidos_itens_baixas SET estornada=true WHERE pedido_item_id=b.id AND empresa_id=e AND NOT estornada;
    IF (SELECT quantidade_estoque FROM public.produtos WHERE id=novo.produto_id AND empresa_id=e)<q
     AND NOT coalesce((SELECT permitir_venda_sem_estoque FROM public.configuracoes_empresa WHERE empresa_id=e),false)
    THEN RAISE EXCEPTION 'Estoque insuficiente para a substituição.'; END IF;
    PERFORM private.produto_exigir_ativo(e,novo.produto_id);
    UPDATE public.produtos SET quantidade_estoque=quantidade_estoque-q WHERE id=novo.produto_id AND empresa_id=e;
    INSERT INTO public.bar_pedidos_itens_baixas(empresa_id,pedido_item_id,produto_id,quantidade) VALUES(e,b.id,novo.produto_id,q);
    -- A substituição de um composto é bloqueada para não apagar suas escolhas históricas.
    IF EXISTS(SELECT 1 FROM public.bar_produtos WHERE id=b.bar_produto_id AND empresa_id=e AND tipo='composto')
     OR EXISTS(SELECT 1 FROM public.bar_pedidos_itens_escolhas WHERE pedido_item_id=b.id AND empresa_id=e) THEN RAISE EXCEPTION 'Composto: só quantidade e preço podem ser corrigidos; use Refazer para outra composição.'; END IF;
    UPDATE public.bar_pedidos_itens SET bar_produto_id=novo.id,produto_id=novo.produto_id,destino_operacional=novo.destino_operacional WHERE id=b.id AND empresa_id=e;
    UPDATE public.itens_venda SET produto_id=novo.produto_id WHERE id=i.id AND empresa_id=e;
   ELSE
   for r in select * from public.bar_pedidos_itens_baixas where pedido_item_id=b.id and empresa_id=e and not estornada order by produto_id for update loop
    delta:=round(r.quantidade*(q/b.quantidade-1),4);
    perform 1 from public.produtos where id=r.produto_id and empresa_id=e for update;
    if delta>0 and (select quantidade_estoque from public.produtos where id=r.produto_id)<delta and not coalesce((select permitir_venda_sem_estoque from public.configuracoes_empresa where empresa_id=e),false) then raise exception 'Estoque insuficiente.'; end if;
    IF delta>0 THEN PERFORM private.produto_exigir_ativo(e,r.produto_id); END IF;
    update public.produtos set quantidade_estoque=quantidade_estoque-delta where id=r.produto_id and empresa_id=e;
    update public.bar_pedidos_itens_baixas set quantidade=quantidade+delta where id=r.id;
   end loop;
   update public.bar_pedidos_itens_escolhas set quantidade=round(quantidade*q/b.quantidade,4) where pedido_item_id=b.id and empresa_id=e;
   END IF;
   update public.bar_pedidos_itens set quantidade=q,preco_unitario=preco where id=b.id;
   update public.itens_venda set quantidade=q,preco_unitario=preco where id=i.id;
  end loop;
  if p_alteracoes ? 'desconto' then
   if p_alteracoes->>'desconto' is null or (p_alteracoes->>'desconto')::numeric<0 or (p_alteracoes->>'desconto')::numeric::text in ('NaN','Infinity','-Infinity') then raise exception 'Desconto inválido.'; end if;
   update public.bar_comandas set desconto=(p_alteracoes->>'desconto')::numeric where id=c.id;
  end if;
  select * into saldo from private.bar_comanda_saldo_calcular(c.id,e);
  if saldo.total_final<0 then raise exception 'Total inválido.'; end if;
  update public.vendas set total=saldo.total_final where id=p_venda;
 end if;
 IF p_alteracoes ? 'cliente_id' THEN
  IF p_alteracoes->>'cliente_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=(p_alteracoes->>'cliente_id')::uuid AND empresa_id=e) THEN RAISE EXCEPTION 'Cliente inválido para esta empresa.'; END IF;
  IF p_alteracoes->>'cliente_id' IS NULL AND EXISTS(SELECT 1 FROM public.contas_receber WHERE venda_id=p_venda AND empresa_id=e AND status<>'cancelado') THEN RAISE EXCEPTION 'Nota a Prazo exige cliente.'; END IF;
  UPDATE public.vendas SET cliente_id=(p_alteracoes->>'cliente_id')::uuid WHERE id=p_venda AND empresa_id=e;
  UPDATE public.contas_receber SET cliente_id=(p_alteracoes->>'cliente_id')::uuid WHERE venda_id=p_venda AND empresa_id=e AND status='aberto';
 END IF;
 SELECT * INTO saldo FROM private.bar_comanda_saldo_calcular(c.id,e);
 IF EXISTS(SELECT 1 FROM public.contas_receber WHERE venda_id=p_venda AND empresa_id=e AND status='aberto') AND saldo.saldo<=0 THEN RAISE EXCEPTION 'Nota a Prazo deve manter saldo positivo.'; END IF;
 UPDATE public.contas_receber SET valor_original=saldo.saldo,saldo_aberto=saldo.saldo WHERE venda_id=p_venda AND empresa_id=e AND status='aberto';
 perform private.bar_venda_recalcular_forma_pagamento(p_venda,e);
 IF EXISTS(SELECT 1 FROM public.contas_receber WHERE venda_id=p_venda AND empresa_id=e AND status<>'cancelado') THEN
  UPDATE public.vendas SET forma_pagamento=CASE WHEN saldo.total_pago>0 THEN 'dividido' ELSE 'Nota a Prazo' END WHERE id=p_venda AND empresa_id=e;
 END IF;
 insert into public.florest_auditoria_operacoes(id,empresa_id,solicitante_id,autorizador_id,operacao,alvo_id,motivo,antes,depois,resultado)
 values(p_idempotencia,e,auth.uid(),auth.uid(),'venda_corrigida',p_venda,p_motivo,anterior,public.florest_venda_detalhar(p_venda)||jsonb_build_object('_alteracoes',p_alteracoes),'sucesso');
 return jsonb_build_object('ok',true);
end $function$

CREATE OR REPLACE FUNCTION public.pdv_atalhos_salvar(p_atalhos jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_uid     uuid := (select auth.uid());
  v_a       jsonb;
  v_p       jsonb;
  v_id      uuid;
  v_ordem   integer := 0;
  v_pord    integer;
  v_ids     uuid[] := '{}';
  v_pid     uuid;
  v_img     text;
begin
  if not exists (select 1 from public.perfis p
                  where p.id = v_uid and p.empresa_id = v_empresa and p.ativo and p.papel = 'proprietario') then
    raise exception 'Só o proprietário da empresa pode configurar os atalhos do PDV.' using errcode = '42501';
  end if;
  if p_atalhos is null or jsonb_typeof(p_atalhos) <> 'array' then
    raise exception 'Lista de atalhos inválida.';
  end if;
  if jsonb_array_length(p_atalhos) > 30 then
    raise exception 'No máximo 30 atalhos por empresa.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('pdv_atalhos:' || v_empresa::text, 0));

  for v_a in select value from jsonb_array_elements(p_atalhos) loop
    begin
      v_id := (v_a->>'id')::uuid;
    exception when others then
      raise exception 'Atalho com identificador inválido.';
    end;
    if v_id = any (v_ids) then
      raise exception 'Atalho repetido na lista.';
    end if;
    if length(btrim(coalesce(v_a->>'nome', ''))) not between 1 and 40 then
      raise exception 'O nome do atalho deve ter de 1 a 40 caracteres.';
    end if;
    if jsonb_typeof(coalesce(v_a->'produtos', '[]'::jsonb)) <> 'array'
       or jsonb_array_length(coalesce(v_a->'produtos', '[]'::jsonb)) > 100 then
      raise exception 'No máximo 100 produtos por atalho.';
    end if;
    -- um id de atalho de OUTRA empresa nunca é sobrescrito
    if exists (select 1 from public.pdv_atalhos x where x.id = v_id and x.empresa_id <> v_empresa) then
      raise exception 'Atalho com identificador inválido.';
    end if;
    v_ids := v_ids || v_id;

    insert into public.pdv_atalhos as t (id, empresa_id, nome, imagem, ordem, atualizado_por)
    values (v_id, v_empresa, btrim(v_a->>'nome'), nullif(v_a->>'imagem', ''), v_ordem, v_uid)
    on conflict (id) do update
       set nome = excluded.nome, imagem = excluded.imagem, ordem = excluded.ordem,
           atualizado_por = excluded.atualizado_por
     where t.empresa_id = v_empresa;
    v_ordem := v_ordem + 1;

    delete from public.pdv_atalhos_produtos where atalho_id = v_id and empresa_id = v_empresa;
    v_pord := 0;
    for v_p in select value from jsonb_array_elements(coalesce(v_a->'produtos', '[]'::jsonb)) loop
      begin
        v_pid := (v_p->>'produto_id')::uuid;
      exception when others then
        continue;
      end;
      v_img := nullif(v_p->>'imagem', '');
      insert into public.pdv_atalhos_produtos (atalho_id, empresa_id, produto_id, ordem, imagem)
      select v_id, v_empresa, pr.id, v_pord, v_img
        from public.produtos pr
       where pr.id = v_pid and pr.empresa_id = v_empresa
      on conflict (atalho_id, produto_id) do nothing;
      v_pord := v_pord + 1;
    end loop;
  end loop;

  delete from public.pdv_atalhos where empresa_id = v_empresa and not (id = any (v_ids));
  return v_ordem;
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_abrir(p_comanda_id uuid, p_cliente_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa      uuid := private.exigir_empresa_ativa();
  v_slot         public.pdv_comandas%rowtype;
  v_cliente_nome text;
  v_sessao       uuid;
  v_cli_atual    uuid;
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar as comandas do PDV.' using errcode = '42501';
  end if;
  if p_comanda_id is null then
    raise exception 'Informe a comanda.';
  end if;
  if p_cliente_id is null then
    raise exception 'Informe o cliente: toda comanda precisa de um cliente cadastrado.';
  end if;

  -- trava a posição: dois "abrir" simultâneos nunca abrem duas sessões
  select * into v_slot
    from public.pdv_comandas c
   where c.id = p_comanda_id and c.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;
  if not v_slot.ativa then
    raise exception 'Esta comanda está desativada.';
  end if;

  select cl.nome into v_cliente_nome
    from public.clientes cl
   where cl.id = p_cliente_id and cl.empresa_id = v_empresa;
  if not found then
    raise exception 'Cliente não encontrado.';
  end if;

  if v_slot.sessao_atual_id is not null then
    select s.cliente_id into v_cli_atual
      from public.pdv_comandas_sessoes s
     where s.id = v_slot.sessao_atual_id and s.empresa_id = v_empresa;
    if v_cli_atual = p_cliente_id then
      -- repetição (duplo clique/reenvio) para o MESMO cliente: devolve a sessão que já existe
      return jsonb_build_object('sessao_id', v_slot.sessao_atual_id, 'comanda_id', v_slot.id, 'numero', v_slot.numero,
                                'cliente_id', p_cliente_id, 'cliente_nome', v_cliente_nome, 'repetida', true);
    end if;
    raise exception 'A comanda % já está aberta para outro cliente.', v_slot.numero;
  end if;

  insert into public.pdv_comandas_sessoes (empresa_id, comanda_id, cliente_id, aberta_por)
  values (v_empresa, v_slot.id, p_cliente_id, (select auth.uid()))
  returning id into v_sessao;

  update public.pdv_comandas
     set status = 'aberta', sessao_atual_id = v_sessao
   where id = v_slot.id and empresa_id = v_empresa;

  return jsonb_build_object('sessao_id', v_sessao, 'comanda_id', v_slot.id, 'numero', v_slot.numero,
                            'cliente_id', p_cliente_id, 'cliente_nome', v_cliente_nome, 'repetida', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_cancelar(p_sessao_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_sessao  public.pdv_comandas_sessoes%rowtype;
  v_motivo  text := nullif(btrim(coalesce(p_motivo, '')), '');
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar as comandas do PDV.' using errcode = '42501';
  end if;
  if p_sessao_id is null then
    raise exception 'Informe a comanda.';
  end if;
  if v_motivo is not null and length(v_motivo) > 200 then
    raise exception 'Motivo longo demais (máximo 200 caracteres).';
  end if;

  select * into v_sessao
    from public.pdv_comandas_sessoes s
   where s.id = p_sessao_id and s.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;
  if v_sessao.status = 'cancelada' then
    return jsonb_build_object('sessao_id', v_sessao.id, 'ja_cancelada', true);
  end if;
  if v_sessao.status = 'finalizada' then
    raise exception 'Esta comanda já foi finalizada.';
  end if;
  if exists (select 1 from public.pdv_comandas_itens i
              where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo') then
    raise exception 'Cancele (remova) os itens da comanda antes de cancelá-la, para o estoque ser devolvido.';
  end if;

  update public.pdv_comandas_sessoes
     set status = 'cancelada', cancelada_em = now(), cancelada_por = (select auth.uid()), motivo_cancelamento = v_motivo
   where id = v_sessao.id and empresa_id = v_empresa;

  update public.pdv_comandas
     set status = 'livre', sessao_atual_id = null
   where id = v_sessao.comanda_id and empresa_id = v_empresa and sessao_atual_id = v_sessao.id;

  return jsonb_build_object('sessao_id', v_sessao.id, 'ja_cancelada', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_finalizar(p_sessao_id uuid, p_chave_idempotencia text, p_pagamentos jsonb DEFAULT NULL::jsonb, p_nota_prazo boolean DEFAULT false, p_cpf_nota text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa    uuid := private.exigir_empresa_ativa();
  v_chave      text := btrim(coalesce(p_chave_idempotencia, ''));
  v_prazo      boolean := coalesce(p_nota_prazo, false);
  v_sessao     public.pdv_comandas_sessoes%rowtype;
  v_cpf_nota   text;
  v_qtd_itens  integer;
  v_total      numeric(14,2);
  v_total_iv   numeric(14,2);
  v_qtd_pag    integer;
  v_qtd_formas integer;
  v_unica      text;
  v_soma       numeric;
  v_forma      text;
  v_numero     bigint;
  v_venda      uuid;
  v_iv         bigint;
  v_titulo     uuid;
  v_venc       date;
  v_caixa      uuid;
  r            record;
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para registrar vendas.' using errcode = '42501';
  end if;
  if p_sessao_id is null then
    raise exception 'Informe a comanda.';
  end if;
  if length(v_chave) < 8 or length(v_chave) > 100 then
    raise exception 'Chave de finalização inválida (8 a 100 caracteres).';
  end if;

  -- trava a sessão: duplo clique/duas abas serializam aqui; a segunda chamada vê a comanda já finalizada
  select * into v_sessao
    from public.pdv_comandas_sessoes s
   where s.id = p_sessao_id and s.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;

  -- IDEMPOTÊNCIA: mesma chave numa comanda já finalizada devolve a MESMA venda/título (nada novo é criado)
  if v_sessao.status = 'finalizada' then
    if v_sessao.finalizacao_chave = v_chave then
      select v.numero_venda into v_numero from public.vendas v where v.id = v_sessao.venda_id and v.empresa_id = v_empresa;
      select cr.id, cr.vencimento into v_titulo, v_venc
        from public.contas_receber cr
       where cr.empresa_id = v_empresa and cr.venda_id = v_sessao.venda_id and cr.origem = 'nota_prazo';
      select v.forma_pagamento into v_forma from public.vendas v where v.id = v_sessao.venda_id and v.empresa_id = v_empresa;
      return jsonb_build_object('venda_id', v_sessao.venda_id, 'numero_venda', v_numero, 'total', v_sessao.total_final,
                                'forma_pagamento', v_forma, 'titulo_id', v_titulo, 'vencimento', v_venc, 'repetida', true);
    end if;
    raise exception 'Esta comanda já foi finalizada.';
  end if;
  if v_sessao.status = 'cancelada' then
    raise exception 'Esta comanda foi cancelada.';
  end if;

  -- Migration 032: finalizar (paga ou a prazo) é uma VENDA do PDV: exige Caixa PDV aberto. Fica depois do
  -- replay idempotente acima (repetir uma finalização já feita nunca falha por caixa fechado depois).
  v_caixa := private.caixa_exigir_aberto('PDV');

  -- a chave nunca pode ter sido usada por OUTRA comanda
  if exists (select 1 from public.pdv_comandas_sessoes s
              where s.empresa_id = v_empresa and s.finalizacao_chave = v_chave and s.id <> v_sessao.id) then
    raise exception 'Chave de finalização já utilizada em outra comanda. Gere uma nova chave.';
  end if;

  -- modo: OU pagamentos (venda paga) OU nota a prazo (título); nunca os dois, nunca nenhum
  if v_prazo then
    if p_pagamentos is not null and not (jsonb_typeof(p_pagamentos) = 'array' and jsonb_array_length(p_pagamentos) = 0) then
      raise exception 'Nota a Prazo não recebe pagamentos: o valor fica a receber.';
    end if;
  else
    if p_pagamentos is null then
      raise exception 'Informe os pagamentos da comanda ou finalize como Nota a Prazo.';
    end if;
  end if;

  -- CPF na nota (opcional) — mesma validação de registrar_venda
  v_cpf_nota := nullif(regexp_replace(coalesce(p_cpf_nota, ''), '[^0-9]', '', 'g'), '');
  if v_cpf_nota is not null and not private.cpf_valido(v_cpf_nota) then
    raise exception 'CPF informado na nota é inválido.';
  end if;

  -- itens ativos (o total vem dos subtotais gravados nos itens: preços já fixados no lançamento)
  select count(*)::integer, coalesce(sum(i.subtotal), 0)
    into v_qtd_itens, v_total
    from public.pdv_comandas_itens i
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo';
  if v_qtd_itens = 0 then
    raise exception 'A comanda não tem itens.';
  end if;
  if v_total <= 0 then
    raise exception 'A comanda não tem valor a cobrar (total zero).';
  end if;

  if v_prazo then
    v_forma := 'Nota a Prazo';
  else
    -- valida os pagamentos (mesma função da Migration 028) ANTES de criar qualquer coisa
    select count(*)::integer, count(distinct x.forma_pagamento)::integer, min(x.forma_pagamento), coalesce(sum(x.valor), 0)
      into v_qtd_pag, v_qtd_formas, v_unica, v_soma
      from private.venda_mista_validar_pagamentos(p_pagamentos) x;
    if round(v_soma * 100)::bigint <> round(v_total * 100)::bigint then
      raise exception 'A soma dos pagamentos (R$ %) não é igual ao total da comanda (R$ %).',
        replace(v_soma::text, '.', ','), replace(v_total::text, '.', ',');
    end if;
    v_forma := case when v_qtd_formas = 1 then v_unica else 'dividido' end;
  end if;

  -- numeração normal de vendas (a linha do contador serializa vendas simultâneas) — igual a registrar_venda
  insert into public.contadores_venda as c (empresa_id, ultimo_numero)
  values (v_empresa, 1)
  on conflict (empresa_id) do update set ultimo_numero = c.ultimo_numero + 1
  returning c.ultimo_numero into v_numero;

  insert into public.vendas (empresa_id, numero_venda, cliente_id, forma_pagamento, total, criado_por, cpf_nota, caixa_id)
  values (v_empresa, v_numero, v_sessao.cliente_id, v_forma, v_total, (select auth.uid()), v_cpf_nota, v_caixa)
  returning id into v_venda;

  -- itens_venda: um por item ativo, na ordem do lançamento. SEM tocar em produtos.quantidade_estoque
  -- (o estoque já foi baixado em cada lançamento).
  for r in
    select i.id, i.produto_id, i.quantidade, i.preco_unitario
      from public.pdv_comandas_itens i
     where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo'
     order by i.seq
  loop
    insert into public.itens_venda (empresa_id, venda_id, produto_id, quantidade, preco_unitario)
    values (v_empresa, v_venda, r.produto_id, r.quantidade, r.preco_unitario)
    returning id into v_iv;

    update public.pdv_comandas_itens set item_venda_id = v_iv where id = r.id and empresa_id = v_empresa;
  end loop;

  -- defesa: o total da venda tem que ser exatamente a soma dos itens gravados
  select coalesce(sum(iv.subtotal), 0) into v_total_iv
    from public.itens_venda iv where iv.empresa_id = v_empresa and iv.venda_id = v_venda;
  if round(v_total_iv * 100)::bigint <> round(v_total * 100)::bigint then
    raise exception 'Inconsistência no total da venda (itens R$ %, comanda R$ %). Nada foi gravado.', v_total_iv, v_total;
  end if;

  if v_prazo then
    -- venda SEM pagamento recebido + UM título; vencimento = último dia do mês da venda (fuso do negócio)
    v_venc := private.ultimo_dia_do_mes(private.pdv_hoje());
    insert into public.contas_receber (empresa_id, cliente_id, venda_id, origem, valor_original, saldo_aberto, vencimento, criado_por)
    values (v_empresa, v_sessao.cliente_id, v_venda, 'nota_prazo', v_total, v_total, v_venc, (select auth.uid()))
    returning id into v_titulo;
  else
    insert into public.vendas_pagamentos (empresa_id, venda_id, forma_pagamento, valor, ordem, criado_por, caixa_id)
    select v_empresa, v_venda, x.forma_pagamento, x.valor, x.ordem, (select auth.uid()), v_caixa
      from private.venda_mista_validar_pagamentos(p_pagamentos) x
     order by x.ordem;
  end if;

  perform private.taxas_registrar('pdv',p.id,p_pagamentos->(p.ordem-1)) from public.vendas_pagamentos p where p.empresa_id=v_empresa and p.venda_id=v_venda;

  update public.pdv_comandas_sessoes
     set status = 'finalizada', venda_id = v_venda, finalizada_em = now(), finalizada_por = (select auth.uid()),
         tipo_fechamento = case when v_prazo then 'nota_prazo' else 'pagamento' end,
         finalizacao_chave = v_chave, total_final = v_total
   where id = v_sessao.id and empresa_id = v_empresa;

  -- libera a posição para um novo cliente (histórico fica em pdv_comandas_sessoes/itens)
  update public.pdv_comandas
     set status = 'livre', sessao_atual_id = null
   where id = v_sessao.comanda_id and empresa_id = v_empresa and sessao_atual_id = v_sessao.id;

  return jsonb_build_object('venda_id', v_venda, 'numero_venda', v_numero, 'total', v_total,
                            'forma_pagamento', v_forma, 'titulo_id', v_titulo, 'vencimento', v_venc, 'repetida', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_item_adicionar(p_sessao_id uuid, p_produto_id uuid, p_quantidade numeric DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa     uuid := private.exigir_empresa_ativa();
  v_qtd         numeric(14,4);
  v_sessao      public.pdv_comandas_sessoes%rowtype;
  v_ativos      integer;
  v_sem_estoque boolean;
  v_nome        text;
  v_estoque     numeric;
  v_preco       numeric(14,2);
  v_item        uuid;
  v_subtotal    numeric(14,2);
  v_total       numeric(14,2);
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar as comandas do PDV.' using errcode = '42501';
  end if;
  if p_sessao_id is null or p_produto_id is null then
    raise exception 'Informe a comanda e o produto.';
  end if;
  if p_quantidade is null or p_quantidade <= 0 or p_quantidade > 100000 then
    raise exception 'Quantidade inválida (precisa ser maior que zero).';
  end if;
  v_qtd := round(p_quantidade, 4);
  if v_qtd <= 0 then
    raise exception 'Quantidade inválida (precisa ser maior que zero).';
  end if;

  -- trava a sessão: serializa lançamentos, cancelamentos e finalização desta comanda
  select * into v_sessao
    from public.pdv_comandas_sessoes s
   where s.id = p_sessao_id and s.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;
  if v_sessao.status <> 'aberta' then
    raise exception 'Esta comanda não está aberta (já foi finalizada ou cancelada).';
  end if;

  select count(*)::integer into v_ativos
    from public.pdv_comandas_itens i
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo';
  if v_ativos >= 500 then
    raise exception 'Itens demais nesta comanda (máximo 500 lançamentos ativos).';
  end if;

  -- mesma regra de registrar_venda: configuração POR EMPRESA (sem linha = desligado)
  select coalesce((select c.permitir_venda_sem_estoque from public.configuracoes_empresa c where c.empresa_id = v_empresa), false)
    into v_sem_estoque;

  -- trava o produto (FOR UPDATE), confere estoque e dá baixa AGORA
  select p.nome, p.quantidade_estoque, p.preco_venda
    into v_nome, v_estoque, v_preco
    from public.produtos p
   where p.id = p_produto_id and p.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Produto não encontrado.';
  end if;
  perform private.produto_exigir_ativo(v_empresa, p_produto_id);   -- [046:pdv_comanda_item]
  if v_estoque < v_qtd and not v_sem_estoque then
    raise exception 'Estoque insuficiente para "%": disponível %, solicitado %.', v_nome, v_estoque, v_qtd;
  end if;

  update public.produtos
     set quantidade_estoque = quantidade_estoque - v_qtd
   where id = p_produto_id and empresa_id = v_empresa;

  -- snapshot do preço (servidor): mudar o preço do produto depois NÃO altera este item
  insert into public.pdv_comandas_itens (empresa_id, sessao_id, produto_id, quantidade, preco_unitario, criado_por)
  values (v_empresa, v_sessao.id, p_produto_id, v_qtd, v_preco, (select auth.uid()))
  returning id, subtotal into v_item, v_subtotal;

  select coalesce(sum(i.subtotal), 0) into v_total
    from public.pdv_comandas_itens i
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo';

  return jsonb_build_object('item_id', v_item, 'produto_id', p_produto_id, 'produto_nome', v_nome,
                            'quantidade', v_qtd, 'preco_unitario', v_preco, 'subtotal', v_subtotal,
                            'total_comanda', v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_item_cancelar(p_item_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa   uuid := private.exigir_empresa_ativa();
  v_sessao_id uuid;
  v_sessao    public.pdv_comandas_sessoes%rowtype;
  v_item      public.pdv_comandas_itens%rowtype;
  v_motivo    text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_total     numeric(14,2);
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar as comandas do PDV.' using errcode = '42501';
  end if;
  if p_item_id is null then
    raise exception 'Informe o item.';
  end if;
  if v_motivo is not null and length(v_motivo) > 200 then
    raise exception 'Motivo longo demais (máximo 200 caracteres).';
  end if;

  -- 1) descobre a sessão (sem travar) -> 2) trava a sessão -> 3) trava o item e relê o estado
  select i.sessao_id into v_sessao_id
    from public.pdv_comandas_itens i
   where i.id = p_item_id and i.empresa_id = v_empresa;
  if not found then
    raise exception 'Item não encontrado.';
  end if;

  select * into v_sessao
    from public.pdv_comandas_sessoes s
   where s.id = v_sessao_id and s.empresa_id = v_empresa
     for update;

  select * into v_item
    from public.pdv_comandas_itens i
   where i.id = p_item_id and i.empresa_id = v_empresa
     for update;

  -- já cancelado (duplo clique/reenvio): NÃO devolve estoque de novo
  if v_item.status = 'cancelado' then
    return jsonb_build_object('item_id', v_item.id, 'ja_cancelado', true, 'quantidade_devolvida', 0);
  end if;

  if v_sessao.status <> 'aberta' then
    raise exception 'Esta comanda já foi finalizada ou cancelada: o item não pode mais ser cancelado por aqui.';
  end if;

  -- devolve EXATAMENTE a quantidade deste item (produto travado, mesma ordem de travas do lançamento)
  perform 1
    from public.produtos p
   where p.id = v_item.produto_id and p.empresa_id = v_empresa
     for update;
  if not found then
    raise exception 'Produto do item não encontrado.';
  end if;

  update public.produtos
     set quantidade_estoque = quantidade_estoque + v_item.quantidade
   where id = v_item.produto_id and empresa_id = v_empresa;

  update public.pdv_comandas_itens
     set status = 'cancelado', cancelado_em = now(), cancelado_por = (select auth.uid()), motivo_cancelamento = v_motivo
   where id = v_item.id and empresa_id = v_empresa and status = 'ativo';

  select coalesce(sum(i.subtotal), 0) into v_total
    from public.pdv_comandas_itens i
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo';

  return jsonb_build_object('item_id', v_item.id, 'ja_cancelado', false,
                            'quantidade_devolvida', v_item.quantidade, 'total_comanda', v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_comanda_obter(p_comanda_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_slot    public.pdv_comandas%rowtype;
  v_sessao  public.pdv_comandas_sessoes%rowtype;
  v_nome    text;
  v_itens   jsonb;
  v_total   numeric(14,2);
  v_cancel  integer;
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar as comandas do PDV.' using errcode = '42501';
  end if;
  if p_comanda_id is null then
    raise exception 'Informe a comanda.';
  end if;

  select * into v_slot from public.pdv_comandas c where c.id = p_comanda_id and c.empresa_id = v_empresa;
  if not found then
    raise exception 'Comanda não encontrada.';
  end if;

  if v_slot.sessao_atual_id is null then
    return jsonb_build_object('comanda_id', v_slot.id, 'numero', v_slot.numero, 'status', 'livre',
                              'sessao_id', null, 'cliente_id', null, 'cliente_nome', null,
                              'itens', '[]'::jsonb, 'total', 0, 'qtd_itens', 0);
  end if;

  select * into v_sessao from public.pdv_comandas_sessoes s where s.id = v_slot.sessao_atual_id and s.empresa_id = v_empresa;
  select cl.nome into v_nome from public.clientes cl where cl.id = v_sessao.cliente_id and cl.empresa_id = v_empresa;

  select coalesce(jsonb_agg(jsonb_build_object(
           'item_id',        i.id,
           'produto_id',     i.produto_id,
           'produto_nome',   p.nome,
           'quantidade',     i.quantidade,
           'preco_unitario', i.preco_unitario,
           'subtotal',       i.subtotal,
           'lancado_em',     i.criado_em
         ) order by i.seq), '[]'::jsonb),
         coalesce(sum(i.subtotal), 0)
    into v_itens, v_total
    from public.pdv_comandas_itens i
    join public.produtos p on p.empresa_id = i.empresa_id and p.id = i.produto_id
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'ativo';

  select count(*)::integer into v_cancel
    from public.pdv_comandas_itens i
   where i.empresa_id = v_empresa and i.sessao_id = v_sessao.id and i.status = 'cancelado';

  return jsonb_build_object(
    'comanda_id', v_slot.id, 'numero', v_slot.numero, 'status', v_slot.status,
    'sessao_id', v_sessao.id, 'cliente_id', v_sessao.cliente_id, 'cliente_nome', v_nome,
    'aberta_em', v_sessao.aberta_em, 'itens', v_itens, 'total', v_total,
    'qtd_itens', jsonb_array_length(v_itens), 'qtd_itens_cancelados', v_cancel);
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_desktop_sincronizar(p_id_local uuid, p_caixa_id uuid, p_pedido jsonb, p_criada_em timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid := private.exigir_empresa_ativa(); anterior private.pdv_desktop_recebimentos%rowtype;
  v uuid; num bigint; atual uuid;
begin
  if not private.perm('pdv') then raise exception 'Você não tem permissão para registrar vendas.' using errcode='42501'; end if;
  if p_id_local is null or p_caixa_id is null or p_criada_em is null or jsonb_typeof(p_pedido) is distinct from 'object' then
    raise exception 'Venda offline incompleta'; end if;
  perform pg_advisory_xact_lock(hashtextextended('pdv_desktop:'||e::text||':'||p_id_local::text,0));
  select * into anterior from private.pdv_desktop_recebimentos where empresa_id=e and id_local=p_id_local;
  if found then
    if anterior.usuario_id<>auth.uid() or anterior.pedido is distinct from p_pedido then
      raise exception 'Identificador pertence a outra venda ou operador.' using errcode='42501'; end if;
    return jsonb_build_object('empresaId',e,'idLocal',p_id_local,'idRemoto',anterior.venda_id,'numeroVenda',anterior.numero_venda,'repetida',true);
  end if;
  -- Não transfere silenciosamente vendas de um caixa fechado para outro caixa.
  atual := private.caixa_exigir_aberto('PDV');
  if atual<>p_caixa_id then raise exception 'O caixa desta venda foi fechado ou substituído. A venda permanece pendente para conferência.' using errcode='CX003'; end if;
  if coalesce((p_pedido->>'prazo')::boolean,false) then
    select r.venda_id,r.numero_venda into v,num from public.registrar_venda_prazo(
      (p_pedido->>'clienteId')::uuid,p_pedido->'itens',p_id_local,p_pedido->>'cpf') r;
  else
    select r.venda_id,r.numero_venda into v,num from public.registrar_venda_mista(
      (p_pedido->>'clienteId')::uuid,p_pedido->'itens',p_pedido->'pagamentos',p_pedido->>'cpf') r;
  end if;
  if v is null then raise exception 'Servidor não confirmou a venda'; end if;
  insert into private.pdv_desktop_recebimentos(empresa_id,id_local,usuario_id,pedido,venda_id,numero_venda,criada_local_em)
    values(e,p_id_local,auth.uid(),p_pedido,v,num,p_criada_em);
  return jsonb_build_object('empresaId',e,'idLocal',p_id_local,'idRemoto',v,'numeroVenda',num,'repetida',false);
end $function$

CREATE OR REPLACE FUNCTION public.pdv_produtos_buscar(p_busca text, p_limite integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, nome text, codigo text, gtin text, preco_venda numeric, quantidade_estoque numeric, unidade_comercial text, venda_granel boolean, total bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_lim     integer := least(greatest(coalesce(p_limite, 50), 1), 100);
  v_off     integer := least(greatest(coalesce(p_offset, 0), 0), 100000);
  v_busca   text := nullif(btrim(coalesce(p_busca, '')), '');
  v_pad     text;
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar o PDV.' using errcode = '42501';
  end if;
  if v_busca is null then
    return;
  end if;

  v_pad := '%' || replace(replace(replace(left(v_busca, 80), '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
    select p.id, p.nome, p.codigo, p.gtin, p.preco_venda, p.quantidade_estoque, p.unidade_comercial,
           p.venda_granel,
           count(*) over () as total
      from public.produtos p
     where p.empresa_id = v_empresa and p.ativo   -- [046:pdv_buscar]
       and (p.nome ilike v_pad or p.codigo ilike v_pad or p.gtin ilike v_pad)
     order by p.nome, p.id
     limit v_lim offset v_off;
end;
$function$

CREATE OR REPLACE FUNCTION public.pdv_produtos_consultar(p_ids uuid[] DEFAULT NULL::uuid[], p_gtins text[] DEFAULT NULL::text[], p_codigo text DEFAULT NULL::text, p_busca text DEFAULT NULL::text, p_limite integer DEFAULT 10)
 RETURNS TABLE(id uuid, nome text, codigo text, gtin text, preco_venda numeric, quantidade_estoque numeric, unidade_comercial text, venda_granel boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_empresa uuid := private.exigir_empresa_ativa();
  v_lim     integer := least(greatest(coalesce(p_limite, 10), 1), 50);
  v_busca   text := nullif(btrim(coalesce(p_busca, '')), '');
  v_pad     text;
begin
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para usar o PDV.' using errcode = '42501';
  end if;
  if p_ids is not null and cardinality(p_ids) > 100 then
    raise exception 'Muitos produtos na consulta.';
  end if;
  if p_gtins is not null and cardinality(p_gtins) > 20 then
    raise exception 'Muitos códigos de barras na consulta.';
  end if;
  if p_ids is not null then v_lim := 100; end if;
  if v_busca is not null then
    v_pad := '%' || replace(replace(replace(left(v_busca, 80), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;
  if p_ids is null and p_gtins is null and nullif(p_codigo, '') is null and v_busca is null then
    return;
  end if;

  return query
    select p.id, p.nome, p.codigo, p.gtin, p.preco_venda, p.quantidade_estoque, p.unidade_comercial,
           p.venda_granel
      from public.produtos p
     where p.empresa_id = v_empresa and p.ativo   -- [046:pdv_consultar]
       and ( (p_ids is not null   and p.id = any (p_ids))
          or (p_gtins is not null and p.gtin = any (p_gtins))
          or (nullif(p_codigo, '') is not null and p.codigo = p_codigo)
          or (v_busca is not null and (p.nome ilike v_pad or p.codigo ilike v_pad or p.gtin ilike v_pad)) )
     order by p.nome, p.id
     limit v_lim;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_venda(p_cliente_id uuid, p_forma_pagamento text, p_itens jsonb, p_cpf_nota text DEFAULT NULL::text)
 RETURNS TABLE(venda_id uuid, numero_venda bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  v_empresa      uuid := private.exigir_empresa_ativa();
  v_forma        text := btrim(coalesce(p_forma_pagamento, ''));
  v_venda        uuid;
  v_numero       bigint;
  v_invalido     boolean;
  v_tem_pacote   boolean;
  r              record;
  v_nome         text;
  v_estoque      numeric;
  v_sem_estoque  boolean;
  v_pacote       public.pacotes_clientes%rowtype;
  v_cpf_nota     text;  -- NOVO (Migration 025)
begin
  -- permissão de módulo (proprietário sempre pode; funcionário precisa de PDV) — inalterado
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para registrar vendas.' using errcode = '42501';
  end if;
  -- configuração POR EMPRESA (sem linha = desligado = comportamento antigo) — inalterado
  select coalesce((select c.permitir_venda_sem_estoque from public.configuracoes_empresa c where c.empresa_id = v_empresa), false)
    into v_sem_estoque;
  if v_forma = '' or length(v_forma) > 40 then
    raise exception 'Forma de pagamento inválida.';
  end if;
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    raise exception 'A venda precisa ter pelo menos um item.';
  end if;
  if jsonb_array_length(p_itens) > 500 then
    raise exception 'Itens demais em uma única venda (máximo 500).';
  end if;
  if p_cliente_id is not null and not exists (
       select 1 from public.clientes c where c.id = p_cliente_id and c.empresa_id = v_empresa) then
    raise exception 'Cliente não encontrado.';
  end if;

  -- NOVO (Migration 025): "CPF na nota" — totalmente opcional. Normaliza para somente dígitos
  -- (string vazia/só pontuação vira NULL) e valida o dígito verificador no servidor, nunca
  -- confiando apenas na validação feita no navegador. Nenhum CPF informado = comportamento
  -- idêntico a antes desta migration.
  v_cpf_nota := nullif(regexp_replace(coalesce(p_cpf_nota, ''), '[^0-9]', '', 'g'), '');
  if v_cpf_nota is not null and not private.cpf_valido(v_cpf_nota) then
    raise exception 'CPF informado na nota é inválido.';
  end if;

  -- valida os itens (tipos, quantidade > 0, preço >= 0) — inalterado; pacote_cliente_id,
  -- quando vier, é validado à parte mais abaixo, só quando presente
  begin
    select exists (
      select 1 from jsonb_to_recordset(p_itens) as x(produto_id uuid, quantidade numeric, preco_unitario numeric)
       where x.produto_id is null or x.quantidade is null or x.quantidade <= 0
          or x.preco_unitario is null or x.preco_unitario < 0
    ) into v_invalido;
  exception when others then
    v_invalido := true;
  end;
  if v_invalido then
    raise exception 'Item da venda inválido (produto, quantidade maior que zero e preço são obrigatórios).';
  end if;

  -- RAMO NOVO, OPCIONAL: só entra aqui se algum item trouxer pacote_cliente_id. Uma venda
  -- comum (nenhum item com pacote_cliente_id) nunca passa por este bloco — continua igual
  -- para QUALQUER empresa, com ou sem o módulo Pet.
  select exists (
    select 1 from jsonb_to_recordset(p_itens) as x(produto_id uuid, quantidade numeric, preco_unitario numeric, pacote_cliente_id uuid)
     where x.pacote_cliente_id is not null
  ) into v_tem_pacote;

  if v_tem_pacote then
    if not private.empresa_tem_modulo('pet') then
      raise exception 'Este recurso exige o módulo Pet ativo para esta empresa.' using errcode = '42501';
    end if;
    if not private.perm('pacotes') then
      raise exception 'Você não tem permissão para consumir sessões de pacote.' using errcode = '42501';
    end if;
  end if;

  -- trava os produtos (ordem fixa = sem deadlock), confere estoque e dá baixa — inalterado;
  -- itens ligados a pacote passam por aqui igual a qualquer outro item (o controle de estoque
  -- não muda de comportamento para eles)
  -- [046:registrar_venda] produto inativo não entra em venda nova (consumo de sessão de pacote já pago continua permitido)
  perform private.produtos_exigir_ativos(v_empresa, (
    select array_agg(x.produto_id)
      from jsonb_to_recordset(p_itens) as x(produto_id uuid, pacote_cliente_id uuid)
     where x.pacote_cliente_id is null));
  for r in
    select x.produto_id, sum(round(x.quantidade, 4)) as qtd
      from jsonb_to_recordset(p_itens) as x(produto_id uuid, quantidade numeric, preco_unitario numeric)
     group by x.produto_id
     order by x.produto_id
  loop
    select p.nome, p.quantidade_estoque into v_nome, v_estoque
      from public.produtos p
     where p.id = r.produto_id and p.empresa_id = v_empresa
       for update;
    if not found then
      raise exception 'Produto não encontrado.';
    end if;
    if v_estoque < r.qtd and not v_sem_estoque then
      raise exception 'Estoque insuficiente para "%": disponível %, solicitado %.', v_nome, v_estoque, r.qtd;
    end if;
    update public.produtos set quantidade_estoque = quantidade_estoque - r.qtd
     where id = r.produto_id and empresa_id = v_empresa;
  end loop;

  -- NOVO: consumo de sessão de pacote, um item por vez (permite redimir mais de uma sessão do
  -- mesmo pacote na mesma venda). Ordem fixa (por pacote_cliente_id) = sem deadlock, mesma
  -- lógica do loop de estoque acima. Cada item aqui:
  --   * precisa ter quantidade = 1 (uma sessão por linha, mesmo padrão de usar_sessao_pacote);
  --   * o produto do item precisa ser o mesmo produto do pacote;
  --   * não pode exceder sessoes_totais (checado sob FOR UPDATE: trava a mesma linha que
  --     usar_sessao_pacote trava, então as duas vias nunca estouram o pacote por concorrência);
  --   * fica registrado em pacote_usos, igual a usar_sessao_pacote.
  if v_tem_pacote then
    for r in
      select x.produto_id, x.quantidade, x.pacote_cliente_id
        from jsonb_to_recordset(p_itens) as x(produto_id uuid, quantidade numeric, preco_unitario numeric, pacote_cliente_id uuid)
       where x.pacote_cliente_id is not null
       order by x.pacote_cliente_id
    loop
      if round(r.quantidade, 4) <> 1 then
        raise exception 'Cada item de consumo de sessão de pacote deve ter quantidade igual a 1.';
      end if;

      select * into v_pacote from public.pacotes_clientes pc
       where pc.id = r.pacote_cliente_id and pc.empresa_id = v_empresa
         for update;
      if not found then
        raise exception 'Pacote não encontrado.';
      end if;
      if v_pacote.produto_id <> r.produto_id then
        raise exception 'O produto do item não corresponde ao produto do pacote informado.';
      end if;
      if v_pacote.sessoes_usadas >= v_pacote.sessoes_totais then
        raise exception 'Este pacote já está concluído.';
      end if;

      update public.pacotes_clientes
         set sessoes_usadas = sessoes_usadas + 1
       where id = r.pacote_cliente_id and empresa_id = v_empresa;

      insert into public.pacote_usos (empresa_id, pacote_id)
      values (v_empresa, r.pacote_cliente_id);
    end loop;
  end if;

  -- número sequencial por empresa (a linha do contador serializa vendas simultâneas) — inalterado
  insert into public.contadores_venda as c (empresa_id, ultimo_numero)
  values (v_empresa, 1)
  on conflict (empresa_id) do update set ultimo_numero = c.ultimo_numero + 1
  returning c.ultimo_numero into v_numero;

  -- NOVO (Migration 025): grava cpf_nota (já normalizado/validado acima, ou NULL) junto com a
  -- venda. Todas as demais colunas inalteradas.
  insert into public.vendas (empresa_id, numero_venda, cliente_id, forma_pagamento, total, criado_por, cpf_nota)
  values (v_empresa, v_numero, p_cliente_id, v_forma, 0, (select auth.uid()), v_cpf_nota)
  returning id into v_venda;

  -- item ligado a pacote nunca é cobrado de novo (preco_unitario forçado a 0): o valor já foi
  -- pago na compra do pacote (vender_pacote_produto). O total da venda soma o subtotal
  -- (gerado automaticamente), então esses itens naturalmente não somam nada ao total.
  insert into public.itens_venda (empresa_id, venda_id, produto_id, quantidade, preco_unitario, pacote_cliente_id)
  select v_empresa, v_venda, x.produto_id, round(x.quantidade, 4),
         case when x.pacote_cliente_id is not null then 0 else round(x.preco_unitario, 2) end,
         x.pacote_cliente_id
    from rows from (jsonb_to_recordset(p_itens) as (produto_id uuid, quantidade numeric, preco_unitario numeric, pacote_cliente_id uuid))
         with ordinality as x(produto_id, quantidade, preco_unitario, pacote_cliente_id, ordem)
   order by x.ordem;

  update public.vendas v
     set total = (select coalesce(sum(i.subtotal), 0) from public.itens_venda i where i.venda_id = v_venda)
   where v.id = v_venda;

  venda_id := v_venda;
  numero_venda := v_numero;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_venda_mista(p_cliente_id uuid, p_itens jsonb, p_pagamentos jsonb, p_cpf_nota text DEFAULT NULL::text)
 RETURNS TABLE(venda_id uuid, numero_venda bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  -- empresa SEMPRE derivada do usuário autenticado — nenhum parâmetro de empresa existe
  v_empresa      uuid := private.exigir_empresa_ativa();
  v_qtd          integer;
  v_qtd_formas   integer;
  v_unica        text;
  v_soma         numeric;
  v_resumo       text;
  v_venda        uuid;
  v_numero       bigint;
  v_total        numeric;
  v_caixa        uuid;
begin
  -- mesma permissão de public.registrar_venda (proprietário sempre pode; funcionário precisa de PDV)
  if not private.perm('pdv') then
    raise exception 'Você não tem permissão para registrar vendas.' using errcode = '42501';
  end if;

  -- Migration 032: sem Caixa PDV aberto não há venda. Trava o caixa (FOR SHARE) até o fim da transação:
  -- o fechamento espera esta venda terminar; uma venda iniciada depois do fechamento é recusada.
  v_caixa := private.caixa_exigir_aberto('PDV');

  -- 1) valida os pagamentos ANTES de tocar em estoque/venda (falha rápida e barata)
  select count(*)::integer,
         count(distinct x.forma_pagamento)::integer,
         min(x.forma_pagamento),
         coalesce(sum(x.valor), 0)
    into v_qtd, v_qtd_formas, v_unica, v_soma
    from private.venda_mista_validar_pagamentos(p_pagamentos) x;

  -- 2) uma forma distinta -> o nome dela; duas ou mais formas distintas -> 'dividido'
  v_resumo := case when v_qtd_formas = 1 then v_unica else 'dividido' end;

  -- 3) cria a venda pela função EXISTENTE (estoque, pacotes, numeração, itens e total ficam 100%
  --    sob a lógica atual dela — inclusive a validação de itens, cliente e CPF da nota)
  select r.venda_id, r.numero_venda
    into v_venda, v_numero
    from public.registrar_venda(p_cliente_id, v_resumo, p_itens, p_cpf_nota) r;

  if v_venda is null then
    raise exception 'Não foi possível registrar a venda.';
  end if;

  -- 4) total REAL calculado pelo servidor (lido da própria venda recém-criada, da MESMA empresa)
  select v.total
    into v_total
    from public.vendas v
   where v.id = v_venda
     and v.empresa_id = v_empresa;
  if not found then
    raise exception 'Venda não encontrada após o registro.';
  end if;

  -- 5) soma dos pagamentos == total, comparados em CENTAVOS (inteiros); senão exceção = rollback
  --    de tudo (venda, itens, estoque, número da venda e pagamentos)
  if round(v_soma * 100)::bigint <> round(v_total * 100)::bigint then
    raise exception 'A soma dos pagamentos (R$ %) não é igual ao total da venda (R$ %).',
      replace(v_soma::text, '.', ','), replace(v_total::text, '.', ',');
  end if;

  -- 5b) Migration 032: vincula a venda ao Caixa PDV aberto (vínculo persistente, por FK — nunca por data)
  update public.vendas set caixa_id = v_caixa where id = v_venda and empresa_id = v_empresa;

  -- 6) grava os pagamentos: empresa_id e venda_id vêm do servidor (nunca do chamador); a FK
  --    composta (empresa_id, venda_id) reconfirma que a venda é desta empresa
  insert into public.vendas_pagamentos (empresa_id, venda_id, forma_pagamento, valor, ordem, criado_por, caixa_id)
  select v_empresa, v_venda, x.forma_pagamento, x.valor, x.ordem, (select auth.uid()), v_caixa
    from private.venda_mista_validar_pagamentos(p_pagamentos) x
   order by x.ordem;

  perform private.taxas_registrar('pdv',p.id,p_pagamentos->(p.ordem-1)) from public.vendas_pagamentos p where p.empresa_id=v_empresa and p.venda_id=v_venda;
  venda_id := v_venda;
  numero_venda := v_numero;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_venda_prazo(p_cliente_id uuid, p_itens jsonb, p_chave_idempotencia uuid, p_cpf_nota text DEFAULT NULL::text)
 RETURNS TABLE(venda_id uuid, numero_venda bigint, titulo_id uuid, total numeric, vencimento date, repetida boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE
  v_empresa uuid := private.exigir_empresa_ativa();
  v_pedido jsonb;
  v_venda public.vendas%rowtype;
  v_id uuid;
  v_numero bigint;
  v_caixa uuid;
  v_titulo uuid;
  v_vencimento date;
BEGIN
  IF NOT private.perm('pdv') THEN
    RAISE EXCEPTION 'Você não tem permissão para registrar vendas.' USING ERRCODE = '42501';
  END IF;
  IF p_cliente_id IS NULL THEN RAISE EXCEPTION 'Nota a Prazo exige um cliente cadastrado.'; END IF;
  IF p_chave_idempotencia IS NULL THEN RAISE EXCEPTION 'Informe a chave de idempotência da venda.'; END IF;
  v_pedido := jsonb_build_object('cliente_id', p_cliente_id, 'itens', p_itens,
    'cpf_nota', nullif(regexp_replace(coalesce(p_cpf_nota, ''), '[^0-9]', '', 'g'), ''));
  PERFORM pg_advisory_xact_lock(hashtextextended('pdv_prazo:' || v_empresa::text || ':' || p_chave_idempotencia::text, 0));

  SELECT * INTO v_venda FROM public.vendas v
    WHERE v.empresa_id = v_empresa AND v.pdv_prazo_chave = p_chave_idempotencia;
  IF FOUND THEN
    IF v_venda.pdv_prazo_pedido IS DISTINCT FROM v_pedido THEN
      RAISE EXCEPTION 'Esta chave já pertence a outra tentativa de venda. Não repita com dados diferentes.';
    END IF;
    SELECT cr.id, cr.vencimento INTO v_titulo, v_vencimento FROM public.contas_receber cr
      WHERE cr.empresa_id = v_empresa AND cr.venda_id = v_venda.id AND cr.origem = 'nota_prazo';
    IF NOT FOUND THEN RAISE EXCEPTION 'Título da venda não encontrado. Procure o responsável.'; END IF;
    RETURN QUERY SELECT v_venda.id, v_venda.numero_venda, v_titulo, v_venda.total::numeric, v_vencimento, true;
    RETURN;
  END IF;

  -- FOR SHARE mantido até o fim: o fechamento aguarda a transação da venda.
  v_caixa := private.caixa_exigir_aberto('PDV');
  -- Valida cliente, produtos, preços, CPF e estoque pela implementação existente.
  SELECT r.venda_id, r.numero_venda INTO v_id, v_numero
    FROM public.registrar_venda(p_cliente_id, 'Nota a Prazo', p_itens, p_cpf_nota) r;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Não foi possível registrar a venda.'; END IF;
  UPDATE public.vendas v SET caixa_id = v_caixa, pdv_prazo_chave = p_chave_idempotencia,
    pdv_prazo_pedido = v_pedido
    WHERE v.id = v_id AND v.empresa_id = v_empresa RETURNING v.* INTO v_venda;
  IF NOT FOUND OR v_venda.total <= 0 THEN RAISE EXCEPTION 'Nota a Prazo exige valor maior que zero.'; END IF;

  v_vencimento := private.ultimo_dia_do_mes(private.pdv_hoje());
  -- A chave única existente (empresa_id, venda_id, origem) impede dois títulos.
  INSERT INTO public.contas_receber
    (empresa_id, cliente_id, venda_id, origem, valor_original, saldo_aberto, vencimento, criado_por)
  VALUES (v_empresa, p_cliente_id, v_id, 'nota_prazo', v_venda.total, v_venda.total,
    v_vencimento, (SELECT auth.uid())) RETURNING id INTO v_titulo;
  -- Não insere vendas_pagamentos: nenhum dinheiro foi recebido.
  RETURN QUERY SELECT v_id, v_numero, v_titulo, v_venda.total::numeric, v_vencimento, false;
END;
$function$

CREATE OR REPLACE FUNCTION public.taxas_pagamento_obter()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid:=private.exigir_empresa_ativa(); r jsonb;
begin
 if not (private.perm('pdv') or private.perm('bar_caixa') or private.perm('financeiro')) then raise exception 'Sem permissão para consultar formas de pagamento.' using errcode='42501'; end if;
 select jsonb_build_object('id',v.id,'ativo',v.ativo,'regras',v.regras) into r from private.taxas_config c join private.taxas_versoes v on v.id=c.versao_id and v.empresa_id=c.empresa_id where c.empresa_id=e;
 return coalesce(r,'{"id":null,"ativo":false,"regras":[]}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.taxas_pagamento_salvar(p_ativo boolean, p_regras jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e uuid:=private.exigir_empresa_ativa(); v uuid; item jsonb; f text; b text; p numeric; regras jsonb:='[]'; chaves text[]:='{}'; chave text;
begin
 if not private.perm('financeiro') then raise exception 'Sem permissão para configurar taxas no Financeiro.' using errcode='42501'; end if;
 if p_ativo is null or jsonb_typeof(p_regras) is distinct from 'array' or jsonb_array_length(p_regras)>13 then raise exception 'Configuração de taxas inválida'; end if;
 for item in select value from jsonb_array_elements(p_regras) loop
  f:=item->>'forma'; b:=nullif(item->>'bandeira','');
  if f not in ('Pix','Cartão de Débito','Cartão de Crédito') or f is null then raise exception 'Forma inválida'; end if;
  if (f='Pix' and b is not null) or (f<>'Pix' and (b is null or b not in ('Visa','Mastercard','Elo','American Express','Hipercard','Diners'))) then raise exception 'Bandeira inválida'; end if;
  if jsonb_typeof(item->'percentual') is distinct from 'number' then raise exception 'Informe a taxa percentual'; end if;
  p:=(item->>'percentual')::numeric;
  if p<0 or p>100 or p<>round(p,4) then raise exception 'Taxa deve estar entre 0 e 100, com até quatro casas'; end if;
  chave:=f||':'||coalesce(b,''); if chave=any(chaves) then raise exception 'Bandeira repetida'; end if; chaves:=array_append(chaves,chave);
  regras:=regras||jsonb_build_array(jsonb_build_object('forma',f,'bandeira',b,'percentual',p));
 end loop;
 perform pg_advisory_xact_lock(hashtextextended('taxas-config:'||e::text,0));
 insert into private.taxas_versoes(empresa_id,ativo,regras,criado_por) values(e,p_ativo,regras,auth.uid()) returning id into v;
 insert into private.taxas_config values(e,v) on conflict(empresa_id) do update set versao_id=excluded.versao_id;
 return public.taxas_pagamento_obter();
end $function$

CREATE OR REPLACE FUNCTION public.usuarios_atualizar(p_id uuid, p_nome text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean, p_permissoes text[] DEFAULT NULL::text[], p_usuario text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid     uuid := (select auth.uid());
  v_a       record;
  v_nome    text;
  v_perm    text[];
  v_usuario text;
begin
  select * into v_a from private.usuarios_alvo(v_uid, p_id);
  if p_nome is not null then
    v_nome := btrim(p_nome);
    if length(v_nome) < 2 or length(v_nome) > 200 then
      raise exception 'Informe o nome do usuário (2 a 200 caracteres).';
    end if;
  end if;
  if p_permissoes is not null then
    v_perm := private.usuarios_normalizar_permissoes(p_permissoes, v_a.o_papel_ator, v_a.o_perm_ator);
  end if;
  -- Migration 027: "usuario" é opcional (default null) — um funcionário atualizado sem ele mantém
  -- exatamente o que já tinha (ou continua sem um, se nunca teve). String vazia depois do btrim
  -- também é tratada como "não informado" (mesmo idioma de registrar_empresa/Migration 026).
  if p_usuario is not null then
    v_usuario := nullif(lower(btrim(p_usuario)), '');
    if v_usuario is not null and v_usuario !~ '^\S{2,60}$' then
      raise exception 'Informe um usuário sem espaços, de 2 a 60 caracteres, ou deixe em branco.';
    end if;
    -- Checagem amigável; a garantia real é o índice único perfis_usuario_empresa_ci_uk (Migration
    -- 021) — exclui o próprio p_id da checagem de conflito, para o funcionário poder reenviar o
    -- usuario que já tem sem erro.
    if v_usuario is not null and exists (
      select 1 from public.perfis p
       where p.empresa_id = v_a.o_empresa and lower(p.usuario) = v_usuario and p.id <> p_id
    ) then
      raise exception 'Este nome de usuário já está em uso nesta empresa.';
    end if;
  end if;
  update public.perfis p
     set nome = coalesce(v_nome, p.nome),
         ativo = coalesce(p_ativo, p.ativo),
         permissoes = coalesce(v_perm, p.permissoes),
         usuario = coalesce(v_usuario, p.usuario)
   where p.id = p_id and p.empresa_id = v_a.o_empresa and p.papel = 'funcionario';
end;
$function$

CREATE OR REPLACE FUNCTION public.usuarios_preparar_criacao(p_ator uuid, p_permissoes text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_a record;
begin
  select * into v_a from private.usuarios_ator(p_ator);
  perform private.usuarios_normalizar_permissoes(p_permissoes, v_a.o_papel, v_a.o_permissoes);
  if (select count(*) from public.perfis p where p.empresa_id = v_a.o_empresa and p.papel = 'funcionario') >= 50 then
    raise exception 'Limite de 50 funcionários por empresa atingido.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.usuarios_vincular(p_ator uuid, p_user_id uuid, p_nome text, p_permissoes text[], p_usuario text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_a       record;
  v_nome    text := btrim(coalesce(p_nome, ''));
  v_usuario text := nullif(lower(btrim(p_usuario)), '');
  v_perm    text[];
begin
  select * into v_a from private.usuarios_ator(p_ator);
  v_perm := private.usuarios_normalizar_permissoes(p_permissoes, v_a.o_papel, v_a.o_permissoes);
  if length(v_nome) < 2 or length(v_nome) > 200 then
    raise exception 'Informe o nome do usuário (2 a 200 caracteres).';
  end if;
  -- Fase 5 / Migration 026: "usuario" é opcional (default null) — um funcionário ERP criado sem
  -- ele continua exatamente como hoje (só entra por e-mail pessoal + senha). Quando informado:
  -- mesmo formato exigido por perfis_usuario_formato_ck (Migration 021), mesma normalização
  -- (trim + minúsculas) já usada por bar_garcom_vincular (Migration 020/022).
  if v_usuario is not null and v_usuario !~ '^\S{2,60}$' then
    raise exception 'Informe um usuário sem espaços, de 2 a 60 caracteres, ou deixe em branco.';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'Usuário de autenticação não encontrado.';
  end if;
  if exists (select 1 from public.perfis p where p.id = p_user_id) then
    raise exception 'Este e-mail já está vinculado a uma empresa.';
  end if;
  if (select count(*) from public.perfis p where p.empresa_id = v_a.o_empresa and p.papel = 'funcionario') >= 50 then
    raise exception 'Limite de 50 funcionários por empresa atingido.';
  end if;
  -- Checagem amigável; a garantia real é o índice único perfis_usuario_empresa_ci_uk (Migration
  -- 021, não filtra por ativo, preserva identidade histórica) — mesmo padrão já usado por
  -- bar_garcom_vincular (Migration 020/022).
  if v_usuario is not null and exists (
    select 1 from public.perfis p
     where p.empresa_id = v_a.o_empresa and lower(p.usuario) = v_usuario
  ) then
    raise exception 'Este nome de usuário já está em uso nesta empresa.';
  end if;
  insert into public.perfis (id, empresa_id, nome, usuario, papel, permissoes, ativo, criado_por, tipo_acesso)
  values (p_user_id, v_a.o_empresa, v_nome, v_usuario, 'funcionario', v_perm, true, p_ator, 'erp');
  return p_user_id;
end;
$function$
